INSERT INTO `chars` (`id_char`, `id_user`, `name`, `raza`, `pdf_path`, `image_path`, `full_body_image_path`) VALUES
(1, 1, 'Draelith', 'Elfo de los bosques', 'Pablo.pdf', 'imagenPequeña.png', 'imagenGeneral.png'),
(3, 25, 'Prythos', 'Tieflin', 'guerrero.pdf', 'nope', 'Nope'),
(4, 25, 'JoseJu', 'Fungus', 'ficha.pdf', 'imagenPequeña.png', 'imagenGeneral.png'),
(5, 1, 'Ren', 'Humano', 'ficha.pdf', 'imagenPequeña.png', 'imagenGeneral.png');
INSERT INTO `conjuros` (`id_spell`, `name`, `descr`, `duracion`, `concentracion`, `casteo`, `level`, `rango`, `clases`, `escuela`) VALUES
(1, 'Salpicadura de ácido (Acid Splash)', 'Lanzas una burbuja de ácido. Elige una criatura dentro del alcance, o elige dos criaturas dentro del alcance que estén a menos de 5 pies la una de la otra. El objetivo debe tener éxito en una tirada de salvación de destreza o recibir 1d6 puntos de daño por ácido. El daño de este conjuro aumenta en 1d6 cuando alcanzas el 5º nivel (2d6), 11º nivel (3d6) y 17º nivel (4d6).', 'Instantaneo', 'no', '1 acción', 'Truco', '60 pies', 'Hechicero, Mago, Lanzador de Rituales', 'Conjuracion'),
(2, 'Protección con hojas (Blade Ward)', 'Extiendes la mano y trazas un sello de protección en el aire. Hasta el final de tu siguiente turno, tienes resistencia contra el daño contundente, perforante y cortante infligido por ataques con armas.', '1 ronda', 'no', '1 acción', 'Truco', 'Personal', 'Bardo, Hechicero, Mago, Brujo, Lanzador de Rituales', 'Abjuracion'),
(3, 'Espada atronadora (Booming Blade)', 'Como parte de la acción utilizada para lanzar este hechizo, debes realizar un ataque cuerpo a cuerpo con un arma contra una criatura dentro del alcance del hechizo, de lo contrario el hechizo falla. Si aciertas, el objetivo sufre los efectos normales del ataque y queda envuelto en energía retumbante hasta el inicio de tu siguiente turno. Si el objetivo se mueve voluntariamente antes de ese momento, recibe inmediatamente 1d8 puntos de daño por trueno y el hechizo termina.El daño de este hechizo aumenta cuando alcanzas niveles superiores. A 5º nivel, el ataque cuerpo a cuerpo inflige 1d8 puntos de daño de trueno adicionales al objetivo, y el daño que recibe el objetivo por moverse aumenta a 2d8. Ambas tiradas de daño aumentan en 1d8 a 11º nivel y 17º nivel.', '1 ronda', 'no', '1 acción', 'Truco', '5 pies', 'Hechicero, Mago, Brujo, Lanzador de Rituales', 'Evocacion'),
(4, 'Toque gélido (Chill Touch)', 'Creas una mano fantasmal y esquelética en el espacio de una criatura dentro de tu alcance. Haz un ataque de conjuro a distancia contra la criatura para atacarla con el frío de la tumba. Si aciertas, el objetivo recibe 1d8 puntos de daño necrótico y no puede recuperar puntos de golpe hasta el inicio de tu siguiente turno. Hasta entonces, la mano se aferra al objetivo.Si golpeas a un objetivo no muerto, también tiene desventaja en las tiradas de ataque contra ti hasta el final de tu siguiente turno.El daño de este hechizo aumenta en 1d8 cuando alcanzas el 5º nivel (2d8), 11º nivel (3d8) y 17º nivel (4d8).', '1 ronda', 'no', '1 acción', 'Truco', '120 pies', 'Hechicero, Mago, Brujo, Lanzador de Rituales', 'Nigromancia'),
(5, 'Controlar llamas (Control Flames)', 'Eliges una llama no mágica que puedas ver dentro del alcance y que quepa dentro de un cubo de 5 pies. La afectas de una de las siguientes maneras:- Expandes instantáneamente la llama 1,5 m en una dirección, siempre que haya madera u otro combustible en la nueva ubicación.- Extingues instantáneamente las llamas dentro del cubo.- Duplicas o reduces a la mitad el área de luz brillante y tenue emitida por la llama, cambias su color o ambas cosas. El cambio dura 1 hora.- Haces que aparezcan dentro de las llamas formas simples -como la forma vaga de una criatura, un objeto inanimado o un lugar- y que se animen como quieras. Las formas duran 1 hora.Si lanzas este conjuro varias veces, puedes tener hasta tres de sus efectos no instantáneos activos a la vez, y puedes descartar tal efecto como una acción.', 'Instantaneous/1 hora', 'no', '1 acción', 'Truco', '60 pies', 'Druida, Hechicero, Mago, Lanzador de Rituales', 'Transmutacion'),
(6, 'Crear hoguera (Create Bonfire)', 'Creas una hoguera en el suelo que puedas ver dentro de tu alcance. Hasta que el conjuro termine, la hoguera llena un cubo de 5 pies. Cualquier criatura en el espacio de la hoguera cuando lanzas el conjuro debe tener éxito en una tirada de salvación de Destreza o recibir 1d8 puntos de daño por fuego. Una criatura también debe hacer la tirada de salvación cuando entra en el espacio de la hoguera por primera vez en un turno o termina su turno allí.El daño del conjuro aumenta en 1d8 cuando alcanzas el 5º nivel (2d8), 11º nivel (3d8) y 17º nivel (4d8).', 'Hasta 1 minuto', 'si', '1 acción', 'Truco', '60 pies', 'Hechicero, Mago, Brujo, Lanzador de Rituales', 'Conjuracion'),
(7, 'Luces danzantes (Dancing Lights)', 'Creas hasta cuatro luces del tamaño de una antorcha dentro de tu alcance, haciéndolas aparecer como antorchas, linternas u orbes brillantes que flotan en el aire mientras duran. También puedes combinar las cuatro luces en una forma brillante vagamente humanoide de tamaño Medio. Sea cual sea la forma que elijas, cada luz emite una luz tenue en un radio de 10 pies.Como acción de bonificación en tu turno, puedes mover las luces hasta 60 pies a un nuevo punto dentro del alcance. Una luz debe estar a menos de 20 pies de otra luz creada por este conjuro, y una luz se apaga si excede el alcance del conjuro.', 'Hasta 1 minuto', 'si', '1 acción', 'Truco', '120 pies', 'Bardo, Hechicero, Mago, Lanzador de Rituales', 'Evocacion'),
(8, 'Trucos Druidaas (Druidacraft)', 'Susurrando a los espíritus de la naturaleza, creas uno de los siguientes efectos dentro del \"alcance\":- Creas un efecto sensorial diminuto e inofensivo que predice el tiempo que hará en tu ubicación durante las próximas 24 horas. El efecto puede manifestarse como un orbe dorado para los cielos despejados, una nube para la lluvia, copos de nieve cayendo para la nieve, etc. Este efecto persiste durante 1 asalto. Este efecto persiste durante 1 asalto.- Haces florecer instantáneamente una flor, que se abra una vaina de semilla o que brote una hoja.- Creas un efecto sensorial instantáneo e inofensivo, como hojas que caen, una ráfaga de viento, el sonido de un animal pequeño o la débil orden de la mofeta. El efecto debe caber en un cubo de 1,5 m.- Enciendes o apagas instantáneamente una vela, una antorcha o una pequeña hoguera.', 'Instantaneo', 'no', '1 acción', 'Truco', '30 pies', 'Druida', 'Transmutacion'),
(9, 'Explosión sobrenatural (Eldritch Blast)', 'Un rayo de energía crepitante se dirige hacia una criatura dentro del alcance. Realiza un ataque de hechizo a distancia contra el objetivo. Si aciertas, el objetivo sufre 1d10 puntos de daño de fuerza.El hechizo crea más de un rayo cuando alcanzas niveles superiores: dos rayos a 5º nivel, tres rayos a 11º nivel y cuatro rayos a 17º nivel. Puedes dirigir los haces al mismo objetivo o a objetivos diferentes. Haz una tirada de ataque distinta para cada rayo.', 'Instantaneo', 'no', '1 acción', 'Truco', '120 pies', 'Brujo', 'Evocacion'),
(10, 'Rayo de fuego (Fire Bolt)', 'Lanzas una mota de fuego a una criatura u objeto dentro de tu alcance. Realiza un ataque de hechizo a distancia contra el objetivo. Si aciertas, el objetivo sufre 1d10 puntos de daño por fuego. Un objeto inflamable alcanzado por este hechizo se incendia si no se lleva puesto o encima.El daño de este conjuro aumenta en 1d10 cuando alcanzas el 5º nivel (2d10), 11º nivel (3d10) y 17º nivel (4d10).', 'Instantaneo', 'no', '1 acción', 'Truco', '120 pies', 'Hechicero, Mago', 'Evocacion'),
(11, 'Amigos (Friends)', 'Mientras dure, tienes ventaja en todos los chequeos de Carisma dirigidos a una criatura de tu elección que no sea hostil hacia ti. Cuando el hechizo termina, la criatura se da cuenta de que has utilizado magia para influir en su estado de ánimo y se vuelve hostil hacia ti. Una criatura propensa a la violencia podría atacarte. Otra criatura podría buscar retribución de otras formas (a discreción del DM), dependiendo de la naturaleza de tu interacción con ella.', 'Hasta 1 minuto', 'si', '1 acción', 'Truco', 'Personal', 'Bardo, Hechicero, Brujo, Mago', 'Encantamiento'),
(12, 'Mordida de escarcha (Frostbite)', 'Haces que se forme escarcha adormecedora en una criatura que puedas ver dentro de tu alcance. El objetivo debe realizar una tirada de salvación de Constitución. Si falla la tirada de salvación, el objetivo recibe 1d6 puntos de daño por frío y tiene desventaja en la siguiente tirada de ataque con arma que haga antes del final de su siguiente turno.El daño del conjuro aumenta en 1d6 cuando alcanzas el 5º nivel (2d6), 11º nivel (3d6) y 17º nivel (4d6).', 'Instantaneo', 'no', '1 acción', 'Truco', '60 pies', 'Druida, Hechicero, Brujo, Mago', 'Evocacion'),
(13, 'Espada de llama verde (Green-Flame Blade)', 'Como parte de la acción utilizada para lanzar este hechizo, debes realizar un ataque cuerpo a cuerpo con un arma contra una criatura dentro del alcance del hechizo, de lo contrario el hechizo falla. Si aciertas, el objetivo sufre los efectos normales del ataque, y fuego verde salta del objetivo a una criatura diferente de tu elección que puedas ver en un radio de 5 pies. La segunda criatura sufre un daño de fuego igual a tu modificador de lanzamiento de conjuros.El daño de este hechizo aumenta cuando alcanzas niveles superiores. A 5º nivel, el ataque cuerpo a cuerpo inflige 1d8 de daño de fuego adicional al objetivo, y el daño de fuego a la segunda criatura aumenta a 18d + tu modificador de habilidad de lanzamiento de conjuros. Ambas tiradas de daño aumentan en 1d8 a 11º y 17º nivel.', 'Instantaneo', 'no', '1 acción', 'Truco', '5 pies', 'Hechicero, Brujo, Mago', 'Evocacion'),
(14, 'Guía (Guidance)', 'Tocas a una criatura dispuesta. Una vez antes de que termine el hechizo, el objetivo puede tirar un d4 y sumar el número obtenido a un chequeo de habilidad de su elección. Puede lanzar el dado antes o después de realizar el chequeo de habilidad. El hechizo finaliza.', 'Hasta 1 minuto', 'si', '1 acción', 'Truco', 'Toque', 'Clerigo, Druida', 'Adivinacion'),
(15, 'Ráfaga (Gust)', 'Te apoderas del aire y lo obligas a crear uno de los siguientes efectos en un punto que puedas ver dentro del \"alcance\":- Una criatura mediana o más pequeña que elijas debe tener éxito en una tirada de salvación de Fuerza o ser empujada hasta 1,5 m lejos de ti.- Creas una pequeña ráfaga de aire capaz de mover un objeto que no se sostiene ni se transporta y que no pesa más de 5 libras. El objeto es empujado hasta 3 metros lejos de ti. No es empujado con fuerza suficiente para causar daño.- Creas un efecto sensorial inofensivo utilizando aire, como hacer que las hojas crujan, que el viento cierre de golpe las contraventanas o que tu ropa se ondule con la brisa.', 'Instantaneo', 'no', '1 acción', 'Truco', '30 pies', 'Druida, Hechicero, Mago', 'Transmutacion'),
(16, 'Luz (Light)', 'Tocas un objeto que no mida más de 10 pies en cualquier dimensión. Hasta que el hechizo termine, el objeto emite luz brillante en un radio de 20 pies y luz tenue en un radio adicional de 20 pies. La luz puede ser del color que desees. Cubrir completamente el objeto con algo opaco bloquea la luz. El hechizo termina si lo lanzas de nuevo o lo descartas como acción.Si apuntas a un objeto que sostiene o lleva una criatura hostil, esa criatura debe tener éxito en una tirada de salvación de destreza para evitar el hechizo.', '1 hora', 'no', '1 acción', 'Truco', 'Toque', 'Bardo, Clerigo, Hechicero, Mago', 'Evocacion'),
(17, 'Látigo eléctrico (Lightning Lure)', 'Creas un rayo de energía que golpea a una criatura de tu elección que puedas ver dentro de tu alcance. El objetivo debe tener éxito en una tirada de salvación de Fuerza o ser arrastrado hasta 3 metros en línea recta hacia ti y recibir 1d8 puntos de daño por rayo si está a menos de 1,5 metros de ti.El daño de este conjuro aumenta en 1d8 cuando alcanzas el 5º nivel (2d8), 11º nivel (3d8) y 17º nivel (4d8).', 'Instantaneo', 'no', '1 acción', 'Truco', '15 pies', 'Hechicero, Brujo, Mago', 'Evocacion'),
(18, 'Mano de mago (Mage Hand)', 'Una mano espectral y flotante aparece en un punto que elijas dentro del alcance. La mano dura lo que dure el hechizo o hasta que la rechaces como acción. La mano desaparece si alguna vez se aleja más de 30 pies de ti o si vuelves a lanzar este hechizo.Puedes utilizar tu acción para controlar la mano. Puedes utilizar la mano para manipular un objeto, abrir una puerta o un contenedor sin cerrar, guardar o recuperar un objeto de un contenedor abierto o verter el contenido de un vial. Puedes mover la mano hasta 30 pies cada vez que la utilices.La mano no puede atacar, activar objetos mágicos ni cargar más de 10 libras.', '1 minuto', 'no', '1 acción', 'Truco', '30 pies', 'Bardo, Hechicero, Brujo, Mago', 'Conjuracion'),
(19, 'Piedra mágica (Magic Stone)', 'Tocas de uno a tres guijarros y los imbuyes de magia. Tú u otra persona podéis realizar un ataque de hechizo a distancia con uno de los guijarros lanzándolo o arrojándolo con una honda. Si se lanza, tiene un alcance de 60 pies. Si otra persona ataca con el guijarro, ese atacante añade tu modificador de habilidad de conjuro, no el del atacante, a la tirada de ataque. Si acierta, el objetivo recibe un daño contundente igual a 1d6 + tu modificador de habilidad de hechicería. Tanto si aciertas como si fallas, el hechizo termina en la piedra.Si vuelves a lanzar este hechizo, el hechizo termina antes sobre cualquier guijarro que aún esté afectado por él.', '1 minuto', 'no', '1 acción adicional', 'Truco', 'Toque', 'Druida, Brujo', 'Transmutacion'),
(20, 'Reparar (Mending)', 'Este hechizo repara una sola rotura o desgarro en un objeto que toques, como una llave rota, una capa desgarrada o un odre que gotea. Siempre que la rotura o desgarro no supere 30 cm en cualquier dimensión, lo reparas sin dejar rastro del daño anterior.Este hechizo puede reparar físicamente un objeto o construcción mágica, pero no puede devolverle la magia.', 'Instantaneo', 'no', '1 minuto', 'Truco', 'Toque', 'Clerigo, Bardo, Druida, Hechicero, Mago', 'Transmutacion'),
(21, 'Mensaje (Message)', 'Apuntas con el dedo hacia una criatura que esté a tu alcance y le susurras un mensaje. El objetivo (y sólo el objetivo) oye el mensaje y puede responder en un susurro que sólo tú puedes oír.Puedes lanzar este hechizo a través de objetos sólidos si estás familiarizado con el objetivo y sabes que está más allá de la barrera. El silencio mágico, 1 pie de piedra, 1 pulgada de metal común, una fina lámina de plomo o 3 pies de madera bloquean el hechizo. El hechizo no tiene que seguir una línea recta y puede viajar libremente alrededor de esquinas o a través de aberturas.', '1 ronda', 'no', '1 acción', 'Truco', '120 pies', 'Bardo, Hechicero, Mago', 'Transmutacion'),
(22, 'Ilusión menor (Minor Illusion)', 'Creas un sonido o una imagen de un objeto dentro del alcance que dura lo que dura el hechizo. La ilusión también termina si la descartas como acción o vuelves a lanzar este conjuro.Si creas un sonido, su volumen puede variar desde un susurro hasta un grito. Puede ser tu voz, la voz de otra persona, el rugido de un león, un redoble de tambores o cualquier otro sonido que elijas. El sonido continúa ininterrumpidamente durante todo el hechizo, o puedes emitir sonidos distintos en diferentes momentos antes de que termine.Si creas una imagen de un objeto, como una silla, huellas de barro o un cofre pequeño, no debe ser mayor que un cubo de 1,5 metros. La imagen no puede crear sonido, luz, olor o cualquier otro efecto sensorial. La interacción física con la imagen revela que es una ilusión, porque las cosas pueden pasar a través de ella.Si una criatura usa su acción para examinar el sonido o la imagen, la criatura puede determinar que es una ilusión con un chequeo exitoso de Inteligencia (Investigación) contra su DC de salvación de conjuro. Si una criatura discierne la ilusión por lo que es, la ilusión se vuelve débil para la criatura.', '1 minuto', 'no', '1 acción', 'Truco', '30 pies', 'Bardo, Hechicero, Brujo, Mago', 'Ilusion'),
(23, 'Moldear tierra (Mold Earth)', 'Eliges una porción de tierra o piedra que puedas ver dentro de tu alcance y que quepa dentro de un cubo de 5 pies. La manipulas de una de las siguientes maneras:- Si eliges como objetivo una zona de tierra suelta, puedes excavarla instantáneamente, moverla por el suelo y depositarla a una distancia de hasta 5 pies. Este movimiento no tiene fuerza suficiente para causar daño.- Haces que aparezcan formas, colores o ambos en la tierra o la piedra, deletreando palabras, creando imágenes o dando forma a patrones. Los cambios duran 1 hora.- Si la tierra o piedra a la que apuntas está en el suelo, haces que se convierta en terreno difícil. Alternativamente, puedes hacer que el suelo se convierta en terreno normal si ya es terreno difícil. Este cambio dura 1 hora. Si lanzas este hechizo varias veces, no puedes tener más de dos de sus efectos no instantáneos activos a la vez, y puedes descartar tal efecto como una acción.', 'Instantaneous/1 hora', 'no', '1 acción', 'Truco', '30 pies', 'Druida, Hechicero, Mago', 'Transmutacion'),
(24, 'Rociada venenosa (Poison Spray)', 'Extiendes la mano hacia una criatura que puedas ver dentro del alcance y proyectas una bocanada de gas nocivo desde la palma. La criatura debe tener éxito en una tirada de salvación de Constitución o sufrir 1d12 puntos de daño por veneno.El daño de este conjuro aumenta en 1d12 cuando alcanzas el 5º nivel (2d12), 11º nivel (3d12) y 17º nivel (4d12).', 'Instantaneo', 'no', '1 acción', 'Truco', '10 pies', 'Hechicero, Brujo, Mago', 'Conjuracion'),
(25, 'Prestidigitación (Prestidigitation)', 'Este hechizo es un truco mágico menor que los hechiceros novatos utilizan para practicar. Creas uno de los siguientes efectos mágicos dentro del \"alcance\":Creas un efecto sensorial instantáneo e inofensivo, como una lluvia de chispas, una ráfaga de viento, tenues notas musicales o un olor extraño.Enciendes o apagas instantáneamente una vela, una antorcha o una pequeña hoguera.Limpias o ensucias instantáneamente un objeto no mayor de 1 pie cúbico.Enfrías, calientas o aromatizas hasta 1 pie cúbico de material no vivo durante 1 hora.Haces aparecer un color, una pequeña marca o un símbolo en un objeto o superficie durante 1 hora.Creas una baratija no mágica o una imagen ilusoria que quepa en tu mano y que dure hasta el final de tu siguiente turno.Si lanzas este hechizo varias veces, puedes tener hasta tres de sus efectos no instantáneos activos a la vez, y puedes descartar tal efecto como una acción.', '1 hora', 'no', '1 acción', 'Truco', '10 pies', 'Bardo, Hechicero, Brujo, Mago', 'Transmutacion'),
(26, 'Producir llama (Produce Flame)', 'Aparece una llama parpadeante en tu mano. La llama permanece allí mientras dura y no te daña ni a ti ni a tu equipo. La llama emite luz brillante en un radio de 3 metros y luz tenue en un radio adicional de 3 metros. El hechizo termina si lo descartas como acción o si lo lanzas de nuevo.También puedes atacar con la llama, aunque al hacerlo finaliza el hechizo. Cuando lanzas este conjuro, o como acción en un turno posterior, puedes lanzar la llama a una criatura en un radio de 30 pies de ti. Haz un ataque de hechizo a distancia. Si aciertas, el objetivo recibe 1d8 puntos de daño por fuego.El daño de este conjuro aumenta en 1d8 cuando alcanzas el 5º nivel (2d8), 11º nivel (3d8) y 17º nivel (4d8).', '10 minutos', 'no', '1 acción', 'Truco', 'Personal', 'Druida', 'Conjuracion'),
(27, 'Rayo de escarcha (Ray of Frost)', 'Un gélido rayo de luz blanquiazul se dirige hacia una criatura dentro del alcance. Realiza un ataque de conjuro a distancia contra el objetivo. Si aciertas, recibe 1d8 puntos de daño por frío y su velocidad se reduce en 3 metros hasta el inicio de tu siguiente turno.El daño del hechizo aumenta en 1d8 cuando alcanzas el 5º nivel (2d8), 11º nivel (3d8) y 17º nivel (4d8).', 'Instantaneo', 'no', '1 acción', 'Truco', '60 pies', 'Hechicero, Mago', 'Evocacion'),
(28, 'Resistencia (Resistance)', 'Tocas a una criatura dispuesta. Una vez antes de que termine el hechizo, el objetivo puede tirar un d4 y sumar el número obtenido a una tirada de salvación de su elección. Puede tirar el dado antes o después de realizar la tirada de salvación. El hechizo finaliza.', 'Hasta 1 minuto', 'si', '1 acción', 'Truco', 'Toque', 'Clerigo, Druida', 'Abjuracion'),
(29, 'Llama sagrada (Sacred Flame)', 'Un resplandor llameante desciende sobre una criatura que puedas ver dentro del alcance. El objetivo debe tener éxito en una tirada de salvación de destreza o recibe 1d8 puntos de daño radiante. El objetivo no se beneficia de la cobertura para esta tirada de salvación.El daño del conjuro aumenta en 1d8 cuando alcanzas el 5º nivel (2d8), 11º nivel (3d8) y 17º nivel (4d8).', 'Instantaneo', 'no', '1 acción', 'Truco', '60 pies', 'Clerigo', 'Evocacion'),
(30, 'Moldear agua (Shape Water)', 'Eliges un área de agua que puedas ver dentro de tu alcance y que quepa dentro de un cubo de 5 pies. La manipulas de una de las siguientes maneras:- Instantáneamente mueves o cambias el flujo del agua según tus instrucciones, hasta 5 pies en cualquier dirección. Este movimiento no tiene fuerza suficiente para causar daño.- Haces que el agua adopte formas simples y se anime según tus indicaciones. Este cambio dura 1 hora.- Cambias el color o la opacidad del agua. El agua debe cambiar de la misma forma en todo momento. Este cambio dura 1 hora.- Congelas el agua, siempre que no haya criaturas en ella. El agua se descongela en 1 hora. Si lanzas este hechizo varias veces, no puedes tener más de dos de sus efectos no instantáneos activos a la vez, y puedes descartar tal efecto como una acción.', 'Instantaneous/1 hora', 'no', '1 acción', 'Truco', '30 pies', 'Druida, Hechicero, Mago', 'Transmutacion'),
(31, 'Garrote (Shillelagh)', 'La madera de la maza o el báculo que empuñas está imbuida del poder de la naturaleza. Mientras dure, puedes utilizar tu habilidad de conjuro en lugar de Fuerza para las tiradas de ataque y daño de los ataques cuerpo a cuerpo con esa arma, y el dado de daño del arma se convierte en un d8. El arma también se vuelve mágica, si aún no lo es. El hechizo finaliza si vuelves a lanzarlo o si sueltas el arma.', '1 minuto', 'no', '1 acción adicional', 'Truco', 'Toque', 'Druida', 'Transmutacion'),
(32, 'Toque impactante (Shocking Grasp)', 'Un rayo brota de tu mano para provocar una descarga a una criatura que intentes tocar. Realiza un ataque de hechizo cuerpo a cuerpo contra el objetivo. Tienes ventaja en la tirada de ataque si el objetivo lleva una armadura de metal. Si aciertas, el objetivo recibe 1d8 puntos de daño por rayo y no puede reaccionar hasta el inicio de su siguiente turno.El daño del hechizo aumenta en 1d8 cuando alcanzas el 5º nivel (2d8), 11º nivel (3d8) y 17º nivel (4d8).', 'Instantaneo', 'no', '1 acción', 'Truco', 'Toque', 'Hechicero, Mago', 'Evocacion'),
(33, 'Salvar al moribundo (Spare the Dying)', 'Tocas a una criatura viva que tiene 0 puntos de golpe. La criatura se estabiliza. Este hechizo no tiene efecto sobre muertos vivientes o constructos.', 'Instantaneo', 'no', '1 acción', 'Truco', 'Toque', 'Clerigo', 'Nigromancia'),
(34, 'Explosión de espada (Sword Burst)', 'Creas un círculo momentáneo de cuchillas espectrales que te rodean. Cada criatura dentro del alcance, que no seas tú, debe tener éxito en una tirada de salvación de Destreza o recibir 1d6 puntos de daño de fuerza.El daño de este conjuro aumenta en 1d6 cuando alcanzas el 5º nivel (2d6), 11º nivel (3d6) y 17º nivel (4d6).', 'Instantaneo', 'no', '1 acción', 'Truco', '5 pies', 'Hechicero, Brujo, Mago', 'Conjuracion'),
(35, 'Taumaturgia (Thaumaturgy)', 'Manifiesta un prodigio menor, un signo de poder sobrenatural, dentro del alcance. Creas uno de los siguientes efectos mágicos dentro del alcance.- Tu voz retumba hasta tres veces más fuerte de lo normal durante 1 minuto.- Haces que las llamas parpadeen, se iluminen, se atenúen o cambien de color durante 1 minuto.- Causas temblores inofensivos en el suelo durante 1 minuto.- Creas un sonido instantáneo que se origina en un punto de tu elección dentro de tu alcance, como el retumbar de un trueno, el grito de un cuervo o susurros siniestros.- Haces que una puerta o ventana sin cerrar se abra o se cierre de golpe instantáneamente.- Alteras el aspecto de tus ojos durante 1 minuto.Si lanzas este hechizo varias veces, puedes tener hasta tres de sus efectos de 1 minuto activos a la vez, y puedes descartar tal efecto como acción.', '1 minuto', 'no', '1 acción', 'Truco', '30 pies', 'Clerigo', 'Transmutacion'),
(36, 'Látigo de espinas (Thorn Whip)', 'Creas un largo látigo en forma de enredadera cubierto de espinas que se lanza a tu orden hacia una criatura a tu alcance. Realiza un ataque de hechizo cuerpo a cuerpo contra el objetivo. Si el ataque impacta, la criatura recibe 1d6 puntos de daño perforante, y si la criatura es Grande o más pequeña, la atraes hasta 3 metros más cerca de ti.El daño de este conjuro aumenta en 1d6 cuando alcanzas el 5º nivel (2d6), 11º nivel (3d6) y 17º nivel (4d6).', 'Instantaneo', 'no', '1 acción', 'Truco', '30 pies', 'Druida', 'Transmutacion'),
(37, 'Aplauso atronador (Thunderclap)', 'Creas un estallido de sonido atronador, que puede oírse a 100 pies de distancia. Cada criatura que no seas tú en un radio de 1,5 m debe realizar una tirada de salvación de Constitución. Si falla, la criatura recibe 1d6 puntos de daño por trueno.El daño del hechizo aumenta en 1d6 cuando alcanzas el 5º nivel (2d6), 11º nivel (3d6) y 17º nivel (4d6).', 'Instantaneo', 'no', '1 acción', 'Truco', 'Self (5-foot radius)', 'Bardo, Druida, Hechicero, Brujo, Mago', 'Evocacion'),
(38, 'Golpe verdadero (True Strike)', 'Extiendes la mano y apuntas con un dedo a un objetivo a tu alcance. Tu magia te concede una breve visión de las defensas del objetivo. En tu siguiente turno, obtienes ventaja en tu primera tirada de ataque contra el objetivo, siempre que este hechizo no haya terminado.', 'Hasta 1 ronda', 'si', '1 acción', 'Truco', '30 pies', 'Bardo, Hechicero, Brujo, Mago', 'Adivinacion'),
(39, 'Burlas crueles (Vicious Mockery)', 'Sueltas una retahíla de insultos mezclados con sutiles encantamientos contra una criatura que puedas ver dentro de tu alcance. Si el objetivo puede oírte (aunque no es necesario que te entienda), debe tener éxito en una tirada de salvación de sabiduría o sufrir 1d4 puntos de daño psíquico y tener desventaja en la siguiente tirada de ataque que haga antes del final de su siguiente turno.El daño de este conjuro aumenta en 1d4 cuando alcanzas el 5º nivel (2d4), 11º nivel (3d4) y 17º nivel (4d4).', 'Instantaneo', 'no', '1 acción', 'Truco', '60 pies', 'Bard', 'Encantamiento'),
(40, 'Absorber elementos (Absorb Elements)', 'El hechizo captura parte de la energía entrante, disminuyendo su efecto sobre ti y almacenándola para tu siguiente ataque cuerpo a cuerpo. Tienes resistencia al tipo de daño desencadenante hasta el inicio de tu siguiente turno. Además, la primera vez que golpeas con un ataque cuerpo a cuerpo en tu siguiente turno, el objetivo recibe 1d6 puntos de daño adicionales del tipo desencadenante, y el hechizo termina.', '1 ronda', 'no', '1 acción', 'Nivel 1', 'Personal', 'Druida, Explorador, Mago, Lanzador de Rituales', 'Abjuracion'),
(41, 'Alarma (Alarm)', 'Activa una alarma contra intrusiones no deseadas. Elige una puerta, una ventana o un área dentro del alcance que no sea mayor que un cubo de 20 pies. Hasta que el hechizo termine, una alarma te avisa cada vez que una criatura Diminuta o mayor toca o entra en el área protegida. Cuando lanzas el hechizo, puedes designar criaturas que no activarán la alarma. También puedes elegir si la alarma es mental o sonora.Una alarma mental te alerta con un ping en tu mente si te encuentras en un radio de 1 milla del área protegida. Este ping te despierta si estás durmiendo.Una alarma audible produce el sonido de una campana de mano durante 10 segundos en un radio de 60 pies.', '8 horas', 'no', '1 minuto', 'Nivel 1', '30 pies', 'Explorador, Mago, Lanzador de Rituales', 'Abjuracion'),
(42, 'Amistad con los animales (Animal Friendship)', 'Este hechizo te permite convencer a una bestia de que no quieres hacerle daño. Elige una bestia que puedas ver dentro del alcance. Debe verte y oírte. Si la Inteligencia de la bestia es 4 o superior, el hechizo falla. De lo contrario, la bestia debe tener éxito en una tirada de salvación de sabiduría o ser encantada por ti durante la duración del hechizo. Si tú o uno de tus compañeros daña al objetivo, el hechizo termina.', '24 horas', 'no', '1 acción', 'Nivel 1', '30 pies', 'Bardo, Clérigo, Clerigo, Druida, Explorador', 'Encantamiento'),
(43, 'Armadura de Agathys (Armor of Agathys)', 'Una fuerza mágica protectora te rodea, manifestándose como una escarcha espectral que te cubre a ti y a tu equipo. Ganas 5 puntos de golpe temporales mientras dure el efecto. Si una criatura te golpea con un ataque cuerpo a cuerpo mientras tienes estos puntos de golpe, la criatura recibe 5 puntos de daño por frío.', '1 hora', 'no', '1 acción', 'Nivel 1', 'Personal', 'Brujo', 'Abjuracion'),
(44, 'Brazos de Hadar (Arms of Hadar)', 'Invocas el poder de Hadar, el Hambre Oscura. Zarcillos de energía oscura brotan de ti y golpean a todas las criaturas en un radio de 3 metros. Cada criatura en esa área debe hacer una tirada de salvación de fuerza. Con una salvación fallida, el objetivo recibe 2d6 puntos de daño necrótico y no puede reaccionar hasta su siguiente turno. Con una salvación exitosa, la criatura recibe la mitad del daño, pero no sufre ningún otro efecto.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', 'Personal', 'Brujo', 'Conjuracion'),
(45, 'Perdición (Bane)', 'Hasta tres criaturas de tu elección que puedas ver dentro del alcance deben realizar tiradas de salvación de carisma. Siempre que un objetivo que falle esta tirada de salvación haga una tirada de ataque o una tirada de salvación antes de que termine el hechizo, el objetivo debe tirar un d4 y restar el número obtenido de la tirada de ataque o de salvación.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 1', '30 pies', 'Bardo, Clérigo, Clerigo', 'Encantamiento'),
(46, 'Vínculo bestial (Beast Bond)', 'Estableces un vínculo telepático con una bestia que toques y que sea amiga tuya o esté encantada por ti. El hechizo falla si la Inteligencia de la bestia es 4 o superior. Hasta que el hechizo termine, el vínculo está activo mientras tú y la bestia estéis en la línea de visión el uno del otro. A través del vínculo, la bestia puede entender tus mensajes telepáticos, y puede comunicarte telepáticamente emociones y conceptos simples. Mientras el vínculo esté activo, la bestia obtiene ventaja en las tiradas de ataque contra cualquier criatura que esté a menos de 1,5 m de ti y que tú puedas ver.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 1', 'Toque', 'Druida, Explorador', 'Adivinacion'),
(47, 'Bendición (Bless)', 'Bendices hasta tres criaturas de tu elección dentro de tu alcance. Siempre que un objetivo haga una tirada de ataque o de salvación antes de que el hechizo termine, el objetivo puede tirar un d4 y sumar el número obtenido a la tirada de ataque o de salvación.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 1', '30 pies', 'Clérigo, Clerigo, Paladín, Paladin', 'Encantamiento'),
(48, 'Manos ardientes (Burning Hands)', 'Mientras mantienes las manos con los pulgares en contacto y los dedos separados, una fina capa de llamas sale disparada de las puntas de tus dedos extendidos. Cada criatura en un cono de 15 pies debe hacer una tirada de salvación de destreza. Una criatura recibe 3d6 puntos de daño por fuego si falla la tirada de salvación, o la mitad de daño si tiene éxito.El fuego prende todos los objetos inflamables de la zona que no se lleven puestos.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', 'Personal', 'Hechicero, Mago, Lanzador de Rituales', 'Evocacion'),
(49, 'Catapulta (Catapult)', 'Elige un objeto de entre 1 y 5 libras de peso que no lleves puesto. El objeto vuela en línea recta hasta 90 pies en la dirección que elijas antes de caer al suelo, deteniéndose antes si impacta contra una superficie sólida. Si el objeto golpea a una criatura, ésta debe realizar una tirada de salvación de Destreza. Si falla, el objeto golpea al objetivo y deja de moverse. En cualquier caso, tanto el objeto como la criatura o la superficie sólida reciben 3d8 puntos de daño contundente.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', '150 pies', 'Hechicero, Mago, Lanzador de Rituales', 'Transmutacion'),
(50, 'Hechizar persona (Charm Person)', 'Intentas encantar a un humanoide que veas a tu alcance. Debe realizar una tirada de salvación de sabiduría, y lo hace con ventaja si tú o tus compañeros estáis luchando contra él. Si falla la tirada de salvación, queda encantado por ti hasta que finalice el hechizo o hasta que tú o tus compañeros le hagáis algún daño. La criatura encantada te considera un conocido amistoso. Cuando el hechizo termina, la criatura sabe que la has encantado tú.', '1 hora', 'no', '1 acción', 'Nivel 1', '30 pies', 'Bardo, Druida, Hechicero, Mago, Brujo, Lanzador de Rituales', 'Encantamiento'),
(51, 'Orbe cromático (Chromatic Orb)', 'Lanzas una esfera de energía de 10 cm de diámetro a una criatura que puedas ver dentro de tu alcance. Eliges ácido, frío, fuego, relámpago, veneno o trueno para el tipo de esfera que creas y luego realizas un ataque de conjuro a distancia contra el objetivo. Si el ataque impacta, la criatura recibe 3d8 del tipo que hayas elegido.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', '90 pies', 'Hechicero, Mago, Lanzador de Rituales', 'Evocacion'),
(52, 'Rocío de colores (Color Spray)', 'De tu mano brota una deslumbrante serie de luces de colores parpadeantes. Tira 6d10; el total es cuántos puntos de golpe de criaturas puede afectar este hechizo. Las criaturas en un cono de 15 pies que se origina en ti se ven afectadas en orden ascendente de sus puntos de golpe actuales (ignorando criaturas inconscientes y criaturas que no pueden ver).Empezando por la criatura que tenga los puntos de golpe actuales más bajos, cada criatura afectada por este hechizo queda cegada hasta que el hechizo termine. Resta los puntos de golpe de cada criatura del total antes de pasar a la criatura con los siguientes puntos de golpe más bajos. Los puntos de golpe de una criatura deben ser iguales o inferiores al total restante para que dicha criatura se vea afectada.', '1 ronda', 'no', '1 acción', 'Nivel 1', 'Personal', 'Hechicero, Mago, Lanzador de Rituales', 'Ilusion'),
(53, 'Orden (Command)', 'Pronuncias una orden de una palabra a una criatura que puedas ver dentro de tu alcance. El objetivo debe tener éxito en una tirada de salvación de sabiduría o seguir la orden en su siguiente turno. El hechizo no tiene efecto si el objetivo no es un muerto viviente, si no entiende tu idioma o si tu orden es directamente dañina para él.A continuación, algunas órdenes típicas y sus efectos. Puedes dar una orden distinta a las descritas aquí. Si lo haces, el DM determinará cómo se comporta el objetivo. Si el objetivo no puede seguir tu orden, el hechizo termina.<b>Aproximación.</b> El objetivo se mueve hacia ti por la ruta más corta y directa, terminando su turno si se mueve a menos de 5 pies de ti.<b>Soltar</b> El objetivo suelta lo que tenga en la mano y termina su turno.<b>Huir.</b> El objetivo pasa su turno alejándose de ti por el medio más rápido disponible.<b>Arrodillarse.</b> El objetivo cae boca abajo y termina su turno.<b>Detenerse.</b> El objetivo no se mueve y no realiza ninguna acción. Una criatura voladora permanece en el aire, siempre que pueda hacerlo. Si debe moverse para mantenerse en el aire, vuela la distancia mínima necesaria para permanecer en el aire.', '1 ronda', 'no', '1 acción', 'Nivel 1', '60 pies', 'Clérigo, Clerigo, Paladín, Paladin', 'Encantamiento'),
(54, 'Duelo forzado (Compelled Duel)', 'Intentas obligar a una criatura a batirse en duelo. Una criatura que puedas ver dentro de tu alcance debe hacer una tirada de salvación de sabiduría. Si falla la tirada de salvación, la criatura es atraída hacia ti, obligada por tu demanda divina. Mientras dure, tiene desventaja en las tiradas de ataque contra criaturas que no seas tú, y debe hacer una tirada de salvación de sabiduría cada vez que intente moverse a un espacio que esté a más de 30 pies de ti; si tiene éxito en esta tirada de salvación, el conjuro no restringe el movimiento del objetivo durante ese turno.El conjuro termina si atacas a cualquier otra criatura, si lanzas un conjuro dirigido a una criatura hostil que no sea el objetivo, si una criatura amiga tuya daña al objetivo o lanza un conjuro dañino sobre él, o si terminas tu turno a más de 30 pies del objetivo.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 1', '30 pies', 'Paladín, Paladin', 'Encantamiento'),
(55, 'Comprender idiomas (Comprehend Languages)', 'Mientras dure, comprenderás el significado literal de cualquier lengua hablada que oigas. También entiendes cualquier lenguaje escrito que veas, pero debes estar tocando la superficie en la que están escritas las palabras. Tardas aproximadamente 1 minuto en leer una página de texto.Este hechizo no descifra mensajes secretos en un texto o un glifo, como un sigilo arcano, que no forme parte de un lenguaje escrito.', '1 hora', 'no', '1 acción', 'Nivel 1', 'Personal', 'Bardo, Hechicero, Mago, Brujo, Lanzador de Rituales', 'Adivinacion'),
(56, 'Crear o destruir agua (Create or Destroy Water)', 'Creas o destruyes agua.<b>Creas agua.</b> Creas hasta 10 galones de agua limpia dentro del alcance en un recipiente abierto. Alternativamente, el agua cae en forma de lluvia en un cubo de 30 pies dentro del alcance.<b>Destruir agua.</b> Destruyes hasta 10 galones de agua en un contenedor abierto dentro del alcance. Como alternativa, destruyes la niebla en un cubo de 30 pies dentro del alcance.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', '30 pies', 'Clérigo, Clerigo, Druida', 'Transmutacion'),
(57, 'Curar heridas (Cure Wounds)', 'Una criatura que toques recupera un número de puntos de golpe igual a 1d8 + tu modificador de habilidad de lanzamiento de conjuros. Este hechizo no tiene efecto sobre muertos vivientes o constructos.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', 'Toque', 'Bardo, Clérigo, Clerigo, Druida, Explorador, Paladín, Paladin, Artífice', 'Evocacion'),
(58, 'Detectar el bien y el mal (Detect Evil and Good)', 'Durante ese tiempo, sabes si hay una aberración, celestial, elemental, fey, fiend o no muerto a menos de 30 pies de ti, así como dónde se encuentra la criatura. Del mismo modo, sabes si hay un lugar u objeto a 30 pies de ti que ha sido mágicamente consagrado o profanado.El hechizo puede penetrar la mayoría de las barreras, pero queda bloqueado por 1 pie de piedra, 1 pulgada de metal común, una fina lámina de plomo o 3 pies de madera o tierra.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 1', 'Personal', 'Clérigo, Clerigo, Paladín, Paladin', 'Adivinacion'),
(59, 'Detectar magia (Detect Magic)', 'Mientras dure el efecto, percibes la presencia de magia en un radio de 30 pies. Si percibes la magia de este modo, puedes utilizar tu acción para ver un aura tenue alrededor de cualquier criatura u objeto visible en el área que sea portador de magia, y aprendes su escuela de magia, si la tiene.El hechizo puede penetrar la mayoría de las barreras, pero queda bloqueado por 1 pie de piedra, 1 pulgada de metal común, una fina lámina de plomo o 3 pies de madera o tierra.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 1', 'Personal', 'Bardo, Clérigo, Clerigo, Druida, Explorador, Hechicero, Mago, Paladín, Paladin, Lanzador de Rituales', 'Adivinacion'),
(60, 'Detectar veneno y enfermedad (Detect Poison and Disease)', 'Mientras dure el efecto, puedes detectar la presencia y ubicación de venenos, criaturas venenosas y enfermedades en un radio de 30 pies de ti. También identificas el tipo de veneno, criatura venenosa o enfermedad en cada caso.El conjuro puede atravesar la mayoría de las barreras, pero queda bloqueado por 1 pie de piedra, 1 pulgada de metal común, una fina lámina de plomo o 3 pies de madera o tierra.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 1', 'Personal', 'Clerigo, Druida, Paladin, Explorador, Lanzador de Rituales', 'Adivinacion'),
(61, 'Disfrazarse (Disguise Self)', 'Haces que tú mismo -incluyendo tu ropa, armadura, armas y otras pertenencias que lleves encima- parezcas diferente hasta que el hechizo termine o hasta que uses tu acción para desecharlo. Puedes parecer 1 pie más bajo o más alto y puedes parecer delgado, gordo o intermedio. No puedes cambiar tu tipo de cuerpo, por lo que debes adoptar una forma que tenga la misma disposición básica de extremidades. De lo contrario, el alcance de la ilusión depende de ti.Los cambios producidos por este hechizo no resisten la inspección física. Por ejemplo, si usas este hechizo para añadir un sombrero a tu atuendo, los objetos pasan a través del sombrero, y cualquiera que lo toque no sentiría nada o sentiría tu cabeza y tu pelo. Si utilizas este hechizo para parecer más delgado de lo que eres, la mano de alguien que extienda la suya para tocarte chocaría contigo mientras estuviera aparentemente en el aire.Para discernir que estás disfrazado, una criatura puede usar su acción para inspeccionar tu apariencia y debe tener éxito en un chequeo de Inteligencia (Investigación) contra tu DC de salvación del hechizo.', '1 hora', 'no', '1 acción', 'Nivel 1', 'Personal', 'Bardo, Clerigo, Hechicero, Mago', 'Ilusion'),
(62, 'Susurros disonantes (Dissonant Whispers)', 'Susurras una melodía discordante que sólo puede oír una criatura de tu elección dentro de tu alcance, causándole un terrible dolor. El objetivo debe realizar una tirada de salvación de sabiduría. Si falla la tirada de salvación, recibe 3d6 puntos de daño psíquico y debe utilizar inmediatamente su reacción, si dispone de ella, para alejarse de ti tanto como le permita su velocidad. La criatura no se mueve a un terreno obviamente peligroso, como un fuego o un pozo. Si la salvación tiene éxito, el objetivo recibe la mitad de daño y no tiene que alejarse. Una criatura ensordecida supera automáticamente la salvación.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', '60 pies', 'Bardo, Brujo', 'Encantamiento'),
(63, 'Favor divino (Divine Favor)', 'Tu plegaria te dota de resplandor divino. Hasta que el hechizo termine, tus ataques con armas infligen 1d4 puntos de daño radiante extra al impactar.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 1', 'Personal', 'Clerigo, Paladin', 'Evocacion'),
(64, 'Temblor de tierra (Earth Tremor)', 'Causas un temblor en el suelo en un radio de 3 metros. Cada criatura que no seas tú en esa zona debe realizar una tirada de salvación de Destreza. Si falla la tirada de salvación, la criatura recibe 1d6 puntos de daño contundente y queda tendida. Si el suelo de esa zona es tierra suelta o piedra, se convierte en terreno difícil hasta que se despeje.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', 'Self (10-foot radius)', 'Bardo, Druida, Hechicero, Mago', 'Evocacion'),
(65, 'Golpe atrapador (Ensnaring Strike)', 'La próxima vez que golpees a una criatura con un ataque de arma antes de que termine este hechizo, aparece una masa retorcida de enredaderas espinosas en el punto de impacto, y el objetivo debe tener éxito en una tirada de salvación de fuerza o quedar inmovilizado por las enredaderas mágicas hasta que termine el hechizo. Una criatura grande o mayor tiene ventaja en esta tirada de salvación. Si el objetivo supera la tirada de salvación, las enredaderas se marchitan.Mientras esté sujeto por este hechizo, el objetivo sufre 1d6 puntos de daño perforante al comienzo de cada turno. Una criatura inmovilizada por las enredaderas o que pueda tocar a una criatura puede utilizar su acción para realizar un chequeo de Fuerza contra la DC de salvación de tu hechizo. Si tiene éxito, el objetivo queda liberado.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 1', 'Personal', 'Paladin, Explorador', 'Conjuracion'),
(66, 'Enredar (Entangle)', 'Malas hierbas y enredaderas brotan del suelo en un cuadrado de 20 pies a partir de un punto dentro del alcance. Mientras duren, estas plantas convierten el suelo de la zona en terreno difícil.Una criatura en el área cuando lanzas el hechizo debe tener éxito en una tirada de salvación de fuerza o ser retenida por las plantas enredadoras hasta que el hechizo termine. Una criatura retenida por las plantas puede usar su acción para hacer un chequeo de Fuerza contra tu DC de salvación del hechizo. Si tiene éxito, se libera.Cuando el hechizo termina, las plantas conjuradas se marchitan.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 1', '90 pies', 'Druida', 'Conjuracion'),
(67, 'Retirada expedita (Expeditious Retreat)', 'Este hechizo te permite moverte a una velocidad increíble. Cuando lanzas este hechizo, y luego como acción adicional en cada uno de tus turnos hasta que el hechizo termine, puedes realizar la acción de Correr.', 'Hasta 10 minutos', 'si', '1 acción adicional', 'Nivel 1', 'Personal', 'Hechicero, Brujo, Mago', 'Transmutacion'),
(68, 'Fuego feérico (Faerie Fire)', 'Cada objeto en un cubo de 20 pies dentro del alcance se ilumina con luz azul, verde o violeta (a tu elección). Cualquier criatura que se encuentre en el área cuando se lanza el conjuro también se ilumina si falla una tirada de salvación de destreza. Mientras dure el conjuro, los objetos y criaturas afectados desprenden una luz tenue en un radio de 3 metros.Cualquier tirada de ataque contra una criatura u objeto afectado tiene ventaja si el atacante puede verlo, y la criatura u objeto afectado no puede beneficiarse de ser invisible.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 1', '60 pies', 'Bardo, Clerigo, Druida, Brujo', 'Evocacion'),
(69, 'Falsa vida (False Life)', 'Al reforzarte con un facsímil nigromántico de vida, ganas 1d4 + 4 puntos de golpe temporales mientras dure el efecto.', '1 hora', 'no', '1 acción', 'Nivel 1', 'Personal', 'Hechicero, Mago', 'Nigromancia'),
(70, 'Caída de pluma (Feather Fall)', 'Elige hasta cinco criaturas que caigan dentro del alcance. La velocidad de caída de una criatura disminuye a 60 pies por asalto hasta que finaliza el hechizo. Si la criatura aterriza antes de que termine el hechizo, no recibe daño de caída y puede caer de pie, y el hechizo termina para esa criatura.', '1 minuto', 'no', '1 reacción', 'Nivel 1', '60 pies', 'Bardo, Hechicero, Mago', 'Transmutacion'),
(71, 'Encontrar familiar (Find Familiar)', 'Tu familiar actúa independientemente de ti, pero siempre obedece tus órdenes. En combate, tira su propia iniciativa y actúa en su propio turno. Un familiar no puede atacar, pero puede realizar otras acciones con normalidad.Cuando el familiar queda a 0 puntos de vida, desaparece sin dejar forma física. Reaparece cuando vuelves a lanzar este hechizo.Mientras tu familiar esté a menos de 100 pies de ti, puedes comunicarte con él telepáticamente. Además, como acción, puedes ver a través de los ojos de tu familiar y oír lo que oye hasta el comienzo de tu siguiente turno, obteniendo los beneficios de cualquier sentido especial que tenga el familiar. Durante este tiempo, eres sordo y ciego con respecto a tus propios sentidos.Como acción, puedes despedir temporalmente a tu familiar. Desaparece en una dimensión de bolsillo donde espera tu llamada. Alternativamente, puedes despedirlo para siempre. Como acción, puedes hacer que reaparezca en cualquier espacio desocupado a menos de 30 pies de ti.No puedes tener más de un familiar a la vez. Si lanzas este hechizo cuando ya tienes un familiar, haces que adopte una nueva forma. Elige una de las formas de la lista anterior. Tu familiar se transforma en la criatura elegida.Por último, cuando lanzas un conjuro con un alcance de toque, tu familiar puede lanzar el conjuro como si lo hubiera lanzado él mismo. Tu familiar debe estar a menos de 100 pies de ti, y debe usar su reacción para lanzar el hechizo cuando lo lanzas. Si el hechizo requiere una tirada de ataque, utilizas tu modificador de acción para la tirada.', 'Instantaneo', 'no', '1 hora', 'Nivel 1', '10 pies', 'Lanzador de Rituales, Mago', 'Conjuracion'),
(72, 'Nube de niebla (Fog Cloud)', 'Creas una esfera de niebla de 20 pies de radio centrada en un punto dentro del alcance. La esfera se extiende por las esquinas y su área queda muy oscurecida. Dura lo que dura o hasta que un viento de velocidad moderada o superior (al menos 10 millas por hora) la dispersa.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 1', '120 pies', 'Clerigo, Druida, Explorador, Hechicero, Mago', 'Conjuracion'),
(73, 'Baya buena (Goodberry)', 'Hasta diez bayas aparecen en tu mano y se infunden con magia mientras duren. Una criatura puede utilizar su acción para comer una baya. Comer una baya restaura 1 punto de golpe, y la baya proporciona suficiente alimento para mantener a una criatura durante un día.Las bayas pierden su potencia si no se han consumido en las 24 horas siguientes al lanzamiento de este hechizo.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', 'Toque', 'Druida, Explorador', 'Transmutacion'),
(74, 'Grasa (Grease)', 'La grasa resbaladiza cubre el suelo en un cuadrado de 10 pies centrado en un punto dentro del alcance y lo convierte en terreno difícil mientras dure el efecto.Cuando la grasa aparece, cada criatura que se encuentre en su área debe tener éxito en una tirada de salvación de destreza o caer boca abajo. Una criatura que entre en el área o termine su turno allí también debe tener éxito en una tirada de salvación de destreza o caer boca abajo.', '1 minuto', 'no', '1 acción', 'Nivel 1', '60 pies', 'Mago', 'Conjuracion'),
(75, 'Rayo guiador (Guiding Bolt)', 'Un destello de luz se dirige hacia una criatura de tu elección dentro de tu alcance. Realiza un ataque de hechizo a distancia contra el objetivo. Si aciertas, el objetivo recibe 4d6 puntos de daño radiante, y la siguiente tirada de ataque que hagas contra él antes del final de tu siguiente turno tiene ventaja, gracias a la tenue luz mística que brilla sobre el objetivo hasta entonces.', '1 ronda', 'no', '1 acción', 'Nivel 1', '120 pies', 'Clerigo', 'Evocacion');
INSERT INTO `conjuros` (`id_spell`, `name`, `descr`, `duracion`, `concentracion`, `casteo`, `level`, `rango`, `clases`, `escuela`) VALUES
(76, 'Granizo de espinas (Hail of Thorns)', 'La próxima vez que golpees a una criatura con un ataque de arma a distancia antes de que este conjuro termine, este conjuro crea una lluvia de espinas que brotan de tu arma a distancia o munición. Además de los efectos normales del ataque, el objetivo del ataque y cada criatura en un radio de 1,5 m deben realizar una tirada de salvación de destreza. Una criatura recibe 1d10 puntos de daño perforante si falla la tirada de salvación, o la mitad de daño si tiene éxito.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 1', 'Personal', 'Explorador', 'Conjuracion'),
(77, 'Palabra curativa (Healing Word)', 'Una criatura de tu elección que puedas ver dentro del alcance recupera puntos de golpe igual a 1d4 + tu modificador de habilidad de conjuro. Este hechizo no tiene efecto sobre muertos vivientes o constructos.', 'Instantaneo', 'no', '1 acción adicional', 'Nivel 1', '60 pies', 'Bardo, Clerigo, Druida', 'Evocacion'),
(78, 'Reprensión infernal (Hellish Rebuke)', 'Apuntas con el dedo y la criatura que te ha dañado se ve momentáneamente rodeada de llamas infernales. La criatura debe realizar una tirada de salvación de destreza. Si falla la tirada de salvación, recibe 2d10 puntos de daño por fuego, o la mitad de daño si tiene éxito.', 'Instantaneo', 'no', '1 reacción', 'Nivel 1', '60 pies', 'Brujo', 'Evocacion'),
(79, 'Heroísmo (Heroism)', 'Una criatura dispuesta que toques queda imbuida de valentía. Hasta que el hechizo termine, la criatura es inmune a ser asustada y gana puntos de golpe temporales iguales a tu modificador de habilidad de lanzamiento de hechizos al comienzo de cada uno de sus turnos. Cuando el hechizo termina, el objetivo pierde los puntos de golpe temporales que le queden de este hechizo.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 1', 'Toque', 'Bardo, Paladin', 'Encantamiento'),
(80, 'Hex (Hex)', 'Lanzas una maldición sobre una criatura que puedas ver dentro de tu alcance. Hasta que el hechizo termine, infliges 1d6 puntos de daño necrótico adicionales al objetivo cada vez que lo golpeas con un ataque. Elige también una habilidad cuando lances el hechizo. El objetivo tiene desventaja en los chequeos de habilidad realizados con la habilidad elegida.Si el objetivo cae a 0 puntos de vida antes de que este hechizo termine, puedes usar una acción adicional en un turno posterior para maldecir a una nueva criatura.Eliminar maldición sobre el objetivo termina este hechizo antes de tiempo.', 'Hasta 1 hora', 'si', '1 acción adicional', 'Nivel 1', '90 pies', 'Brujo', 'Encantamiento'),
(81, 'Marca del cazador (Hunter\'s Mark)', 'Eliges una criatura que puedas ver dentro de tu alcance y la marcas místicamente como tu presa. Hasta que el conjuro termine, infliges 1d6 puntos de daño extra al objetivo siempre que lo golpees con un ataque de arma, y tienes ventaja en cualquier chequeo de Sabiduría (Percepción) o Sabiduría (Supervivencia) que hagas para encontrarlo. Si el objetivo cae a 0 puntos de golpe antes de que termine este hechizo, puedes utilizar una acción adicional en un turno posterior tuyo para marcar una nueva criatura.', 'Hasta 1 hora', 'si', '1 acción adicional', 'Nivel 1', '90 pies', 'Paladin, Explorador', 'Adivinacion'),
(82, 'Cuchillo de hielo (Ice Knife)', 'Creas un fragmento de hielo y lo lanzas contra una criatura a tu alcance. Realiza un ataque de hechizo a distancia contra el objetivo. Si aciertas, el objetivo recibe 1d10 puntos de daño perforante. Tanto si aciertas como si fallas, el fragmento explota. El objetivo y cada criatura en un radio de 1,5 m del punto donde explotó el trozo de hielo deben superar una tirada de salvación de Destreza o recibir 2d6 puntos de daño por frío.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', '60 pies', 'Druida, Hechicero, Mago', 'Conjuracion'),
(83, 'Identificar (Identify)', 'Eliges un objeto que debes tocar durante el lanzamiento del hechizo. Si se trata de un objeto mágico o de algún otro objeto mágico, aprendes sus propiedades y cómo utilizarlas, si requiere sintonización para su uso y cuántas cargas tiene, si las tiene. Sabes si hay algún hechizo que afecte al objeto y cuál es. Si el objeto fue creado por un hechizo, aprendes qué hechizo lo creó.Si por el contrario tocas a una criatura durante el lanzamiento, sabrás qué hechizos, si los hay, la están afectando en ese momento.', 'Instantaneo', 'no', '1 minuto', 'Nivel 1', 'Toque', 'Bardo, Clerigo, Lanzador de Rituales, Mago', 'Adivinacion'),
(84, 'Escritura ilusoria (Illusory Script)', 'Escribes en pergamino, papel o cualquier otro material de escritura adecuado y lo imbuyes con una potente ilusión que dura lo que dura el hechizo.Para ti y para las criaturas que designes al lanzar el conjuro, la escritura parece normal, escrita con tu mano, y transmite el significado que pretendías cuando escribiste el texto. Para todos los demás, la escritura aparece como si estuviera escrita en una escritura desconocida o mágica que es ininteligible. Alternativamente, puedes hacer que la escritura parezca ser un mensaje completamente diferente, escrito en una mano y lenguaje diferentes, aunque el lenguaje debe ser uno que conozcas.Si el hechizo se disipa, tanto la escritura original como la ilusión desaparecen.Una criatura con visión verdadera puede leer el mensaje oculto.', '10 days', 'no', '1 minuto', 'Nivel 1', 'Toque', 'Bardo, Lanzador de Rituales, Brujo, Mago', 'Ilusion'),
(85, 'Infligir heridas (Inflict Wounds)', 'Realiza un ataque de hechizo cuerpo a cuerpo contra una criatura que puedas alcanzar. Si aciertas, el objetivo recibe 3d10 puntos de daño necrótico.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', 'Toque', 'Clerigo', 'Nigromancia'),
(86, 'Saltar (Jump)', 'Tocas a una criatura. La distancia de salto de la criatura se triplica hasta que termina el hechizo.', '1 minuto', 'no', '1 acción', 'Nivel 1', 'Toque', 'Druida, Explorador, Hechicero, Mago', 'Transmutacion'),
(87, 'Zancada prolongada (Longstrider)', 'Tocas a una criatura. La velocidad del objetivo aumenta 3 metros hasta que termina el hechizo.', '1 hora', 'no', '1 acción', 'Nivel 1', 'Toque', 'Bardo, Druida, Explorador, Mago', 'Transmutacion'),
(88, 'Armadura de mago (Mage Armor)', 'Tocas a una criatura dispuesta que no lleve armadura y una fuerza mágica protectora la rodea hasta que finaliza el hechizo. La CA base del objetivo pasa a ser 13 + su modificador de Destreza. El conjuro finaliza si el objetivo se pone una armadura o si descartas el conjuro como acción.', '8 horas', 'no', '1 acción', 'Nivel 1', 'Toque', 'Hechicero, Mago', 'Abjuracion'),
(89, 'Misil mágico (Magic Missile)', 'Creas tres dardos brillantes de fuerza mágica. Cada dardo alcanza a una criatura de tu elección que puedas ver dentro de su alcance. Un dardo inflige 1d4 + 1 puntos de daño de fuerza a su objetivo. Todos los dardos golpean simultáneamente, y puedes dirigirlos para golpear a una o varias criaturas.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', '120 pies', 'Hechicero, Mago', 'Evocacion'),
(90, 'Protección contra el bien y el mal (Protection from Evil and Good)', 'Hasta que el hechizo termine, una criatura que toques queda protegida contra ciertos tipos de criaturas: aberraciones, celestiales, elementales, fey, fiends y no muertos.La protección otorga varios beneficios. Las criaturas de esos tipos tienen desventaja en las tiradas de ataque contra el objetivo. El objetivo tampoco puede ser encantado, asustado o poseído por ellos. Si el objetivo ya está encantado, asustado o poseído por una criatura de este tipo, tiene ventaja en cualquier nueva tirada de salvación contra el efecto en cuestión.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 1', 'Toque', 'Clerigo, Paladin, Brujo, Mago', 'Abjuracion'),
(91, 'Purificar comida y bebida (Purify Food and Drink)', 'Toda la comida y bebida no mágica dentro de una esfera de 5 pies de radio centrada en un punto de tu elección dentro del alcance se purifica y queda libre de veneno y enfermedad.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', '10 pies', 'Clerigo, Druida, Paladin, Lanzador de Rituales', 'Transmutacion'),
(92, 'Rayo de enfermedad (Ray of Sickness)', 'Un rayo de enfermiza energía verdosa se lanza hacia una criatura dentro del alcance. Realiza un ataque de hechizo a distancia contra el objetivo. Si acierta, el objetivo recibe 2d8 puntos de daño por veneno y debe realizar una tirada de salvación de Constitución. Si falla, también queda envenenado hasta el final de tu siguiente turno.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', '60 pies', 'Hechicero, Mago', 'Nigromancia'),
(93, 'Santuario (Sanctuary)', 'Proteges a una criatura a tu alcance contra un ataque. Hasta que el hechizo termine, cualquier criatura que ataque a la criatura protegida con un ataque o hechizo dañino debe hacer primero una tirada de salvación de sabiduría. Si falla, la criatura debe elegir un nuevo objetivo o perder el ataque o conjuro. Este conjuro no protege a la criatura protegida de los efectos de área, como la explosión de una bola de fuego.Si la criatura protegida realiza un ataque o lanza un conjuro que afecta a una criatura enemiga, este conjuro termina.', '1 minuto', 'no', '1 acción adicional', 'Nivel 1', '30 pies', 'Clerigo, Paladin', 'Abjuracion'),
(94, 'Golpe ardiente (Searing Smite)', 'La próxima vez que golpees a una criatura con un ataque de arma cuerpo a cuerpo durante la duración del hechizo, tu arma se enciende con una intensidad de fuego blanco, y el ataque inflige 1d6 puntos extra de daño de fuego al objetivo y hace que éste arda en llamas. Al comienzo de cada turno hasta que finalice el hechizo, el objetivo debe realizar una tirada de salvación de Constitución. Si falla, recibe 1d6 puntos de daño por fuego. Si tiene éxito, el hechizo termina. Si el objetivo o una criatura en un radio de 5 pies utiliza una acción para apagar las llamas, o si algún otro efecto apaga las llamas (como sumergir al objetivo en agua), el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 1', 'Personal', 'Paladin', 'Evocacion'),
(95, 'Escudo (Shield)', 'Una barrera invisible de fuerza mágica aparece y te protege. Hasta el inicio de tu siguiente turno, tienes un bonificador +5 a la CA, incluso contra el ataque desencadenante, y no recibes daño de proyectil mágico.', '1 ronda', 'no', '1 reacción', 'Nivel 1', 'Personal', 'Hechicero, Mago', 'Abjuracion'),
(96, 'Escudo de fe (Shield of Faith)', 'Aparece un campo resplandeciente que rodea a una criatura de tu elección dentro de tu alcance y le otorga un bonificador +2 a la CA mientras dure el efecto.', 'Hasta 10 minutos', 'si', '1 acción adicional', 'Nivel 1', '60 pies', 'Clerigo, Paladin', 'Abjuracion'),
(97, 'Imagen silenciosa (Silent Image)', 'Creas la imagen de un objeto, una criatura o algún otro fenómeno visible que no sea mayor que un cubo de 15 pies. La imagen aparece en un punto dentro del alcance y dura lo que dura el efecto. La imagen es puramente visual; no va acompañada de sonido, olor u otros efectos sensoriales.Puedes usar tu acción para hacer que la imagen se mueva a cualquier punto dentro del alcance. A medida que la imagen cambia de lugar, puedes alterar su apariencia para que sus movimientos parezcan naturales para la imagen. Por ejemplo, si creas una imagen de una criatura y la mueves, puedes alterar la imagen para que parezca que está caminando.La interacción física con la imagen revela que es una ilusión, porque las cosas pueden pasar a través de ella. Una criatura que use su acción para examinar la imagen puede determinar que es una ilusión con un chequeo de Inteligencia (Investigación) con éxito contra tu DC de salvación de conjuro. Si una criatura discierne la ilusión por lo que es, la criatura puede ver a través de la imagen.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 1', '60 pies', 'Bardo, Hechicero, Mago', 'Ilusion'),
(98, 'Dormir (Sleep)', 'Este hechizo sume a las criaturas en un sueño mágico. Tira 5d8; el total es cuántos puntos de golpe de criaturas puede afectar este hechizo. Las criaturas en un radio de 6 metros de un punto que elijas dentro del alcance se ven afectadas en orden ascendente de sus puntos de golpe actuales (ignorando a las criaturas inconscientes).Empezando por la criatura que tenga los puntos de golpe actuales más bajos, cada criatura afectada por este hechizo cae inconsciente hasta que el hechizo termine, el durmiente reciba daño o alguien use una acción para sacudir o abofetear al durmiente para despertarlo. Resta los puntos de golpe de cada criatura del total antes de pasar a la criatura con los siguientes puntos de golpe más bajos. Los puntos de golpe de una criatura deben ser iguales o inferiores al total restante para que dicha criatura se vea afectada.Los no muertos y las criaturas inmunes a ser encantadas no se ven afectadas por este hechizo.', '1 minuto', 'no', '1 acción', 'Nivel 1', '90 pies', 'Bardo, Hechicero, Brujo, Mago', 'Encantamiento'),
(99, 'Hablar con los animales (Speak with Animals)', 'Obtienes la capacidad de comprender y comunicarte verbalmente con las bestias durante el tiempo que dure la habilidad. El conocimiento y la conciencia de muchas bestias están limitados por su inteligencia, pero como mínimo, las bestias pueden darte información sobre lugares cercanos y monstruos, incluyendo cualquier cosa que puedan percibir o hayan percibido en el último día. Podrías persuadir a una bestia para que te haga un pequeño favor, a discreción del DM.', '10 minutos', 'no', '1 acción', 'Nivel 1', 'Personal', 'Bardo, Clerigo, Druida, Paladin, Explorador, Lanzador de Rituales', 'Adivinacion'),
(100, 'Risa horrible de Tasha (Tasha\'s Hideous Laughter)', 'Una criatura de tu elección que puedas ver dentro del alcance percibe todo como hilarantemente divertido y cae en ataques de risa si este hechizo le afecta. El objetivo debe tener éxito en una tirada de salvación de sabiduría o caer tendido, quedando incapacitado e incapaz de levantarse mientras dure el hechizo. Una criatura con una puntuación de Inteligencia de 4 o menos no se ve afectada.Al final de cada turno, y cada vez que reciba daño, el objetivo puede realizar otra tirada de salvación de sabiduría. El objetivo tiene ventaja en la tirada de salvación si es provocada por daño. Si tiene éxito, el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 1', '30 pies', 'Bardo, Brujo, Mago', 'Encantamiento'),
(101, 'Disco flotante de Tenser (Tenser\'s Floating Disk)', 'Este conjuro crea un plano de fuerza horizontal circular de 3 pies de diámetro y 1 pulgada de grosor que flota a 3 pies del suelo en un espacio desocupado de tu elección que puedas ver dentro de su alcance. El disco permanece durante todo el tiempo, y puede soportar hasta 500 libras. Si se coloca más peso sobre él, el hechizo termina, y todo lo que hay en el disco cae al suelo.El disco permanece inmóvil mientras estés a menos de 6 metros de él. Si te alejas de él más de 6 metros, el disco te sigue para permanecer a menos de 6 metros de ti. Puede moverse por terrenos irregulares, subiendo o bajando escaleras, pendientes y similares, pero no puede atravesar un desnivel de 3 metros o más. Por ejemplo, el disco no puede atravesar un pozo de 3 metros de profundidad, ni salir de él si se ha creado en el fondo.Si te alejas más de 100 pies del disco (normalmente porque no puede moverse alrededor de un obstáculo para seguirte), el hechizo termina.', '1 hora', 'no', '1 acción', 'Nivel 1', '30 pies', 'Lanzador de Rituales, Mago', 'Conjuracion'),
(102, 'Golpe atronador (Thunderous Smite)', 'La primera vez que golpeas con un ataque de arma cuerpo a cuerpo durante la duración de este hechizo, tu arma suena con un trueno que es audible a 300 pies de ti, y el ataque inflige 2d6 puntos de daño de trueno adicionales al objetivo. Además, si el objetivo es una criatura, debe tener éxito en una tirada de salvación de fuerza o ser empujada a 3 metros de ti y quedar tendida.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 1', 'Personal', 'Paladin', 'Evocacion'),
(103, 'Ola atronadora (Thunderwave)', 'Una ola de fuerza atronadora sale de ti. Cada criatura en un cubo de 15 pies que parta de ti debe realizar una tirada de salvación de Constitución. Si fallas la tirada de salvación, la criatura recibe 2d8 puntos de daño por trueno y es empujada a 3 metros de ti. Con una salvación exitosa, la criatura recibe la mitad de daño y no es empujada.Además, los objetos no asegurados que estén completamente dentro del área de efecto son automáticamente empujados a 10 pies de distancia de ti por el efecto del hechizo, y el hechizo emite un estruendo atronador audible a 300 pies.', 'Instantaneo', 'no', '1 acción', 'Nivel 1', 'Personal', 'Bardo, Clerigo, Druida, Hechicero, Mago', 'Evocacion'),
(104, 'Sirviente invisible (Unseen Servant)', 'Este hechizo crea una fuerza invisible, sin mente y sin forma que realiza tareas sencillas a tus órdenes hasta que finaliza el hechizo. El siervo surge en un espacio desocupado del suelo dentro de su alcance. Tiene CA 10, 1 punto de golpe y una Fuerza de 2, y no puede atacar. Si baja a 0 puntos de vida, el hechizo termina.Una vez en cada turno, como acción adicional, puedes ordenar mentalmente al sirviente que se mueva hasta 15 pies e interactúe con un objeto. El sirviente puede realizar tareas sencillas que podría hacer un sirviente humano, como ir a buscar cosas, limpiar, remendar, doblar ropa, encender fuego, servir comida y verter viento. Una vez que le das la orden, el siervo realiza la tarea lo mejor que puede hasta que la completa, y luego espera tu siguiente orden.Si ordenas al sirviente que realice una tarea que lo alejaría de ti más de 60 pies, el hechizo termina.', '1 hora', 'no', '1 acción', 'Nivel 1', '60 pies', 'Bardo, Lanzador de Rituales, Brujo, Mago', 'Conjuracion'),
(105, 'Rayo de bruja', 'Un rayo de energía azul y crepitante se lanza hacia una criatura dentro del alcance, formando un arco de relámpagos sostenido entre el objetivo y tú. Realiza un ataque de hechizo a distancia contra esa criatura. Si aciertas, el objetivo recibe 1d12 puntos de daño por rayo y, en cada uno de tus turnos mientras dure el hechizo, puedes usar tu acción para infligir 1d12 puntos de daño por rayo al objetivo automáticamente. El hechizo termina si utilizas tu acción para hacer cualquier otra cosa. El hechizo también termina si el objetivo se encuentra fuera del alcance del hechizo o si está totalmente a cubierto de ti.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 1', '30 pies', 'Hechicero, Brujo, Mago', 'Evocacion'),
(106, 'Golpe iracundo', 'La próxima vez que golpees con un ataque de arma cuerpo a cuerpo durante la duración de este conjuro, tu ataque inflige 1d6 puntos de daño psíquico adicionales. Además, si el objetivo es una criatura, debe hacer una tirada de salvación de Sabiduría o asustarse de ti hasta que el conjuro termine. Como acción, la criatura puede hacer un chequeo de Sabiduría contra tu DC de salvación de conjuro para acertar su resolución y terminar este conjuro.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 1', 'Personal', 'Paladin', 'Evocacion'),
(107, 'Ráfaga abrasadora de Aganazzar (Aganazzar\'s Scorcher)', 'Una línea de llamas rugientes de 30 pies de largo y 5 pies de ancho emana de ti en la dirección que elijas. Cada criatura en la línea debe hacer una tirada de salvación de Destreza. Una criatura recibe 3d8 puntos de daño por fuego si falla la tirada de salvación, o la mitad de daño si tiene éxito.', 'Instantaneo', 'no', '1 acción', 'Nivel 2', '30 pies', 'Hechicero, Mago, Lanzador de Rituales', 'Evocacion'),
(108, 'Auxilio (Aid)', 'Tu hechizo refuerza a tus aliados con dureza y determinación. Elige hasta tres criaturas dentro del alcance. Los puntos de vida máximos y actuales de cada objetivo aumentan en 5 mientras dure el hechizo.', '8 horas', 'no', '1 acción', 'Nivel 2', '30 pies', 'Clérigo, Clerigo, Paladín, Paladin', 'Abjuracion'),
(109, 'Alterar el ser (Alter Self)', 'Adoptas una forma diferente. Cuando lanzas el hechizo, eliges una de las siguientes opciones, cuyos efectos duran mientras dure el hechizo. Mientras dure el hechizo, puedes finalizar una opción como acción para obtener los beneficios de otra diferente.<b>Adaptación Acuática.</b> Adaptas tu cuerpo al medio acuático, te salen branquias y te crecen telarañas entre los dedos. Puedes respirar bajo el agua y ganar una velocidad de nado igual a tu velocidad al caminar.<b>Cambio de apariencia.</b> Transformas tu apariencia. Tú decides tu aspecto, incluyendo tu altura, peso, rasgos faciales, sonido de tu voz, longitud del pelo, coloración y características distintivas, si las hay. Puedes hacerte pasar por un miembro de otra raza, aunque ninguna de tus estadísticas cambia. Tampoco puedes aparecer como una criatura de tamaño diferente al tuyo, y tu forma básica permanece igual; si eres bípedo, no puedes usar este hechizo para convertirte en cuadrúpedo, por ejemplo. En cualquier momento mientras dure el hechizo, puedes usar tu acción para volver a cambiar tu apariencia de esta forma.<b>Armas naturales.</b> Te crecen garras, colmillos, espinas, cuernos o cualquier otra arma natural que elijas. Tus golpes desarmados infligen 1d6 puntos de daño contundente, perforante o cortante, según el arma natural que hayas elegido, y eres competente con tus golpes desarmados. Por último, el arma natural es mágica y tienes un bonificador +1 a las tiradas de ataque y daño que hagas con ella.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', 'Personal', 'Hechicero, Mago, Lanzador de Rituales', 'Transmutacion'),
(110, 'Mensajero animal (Animal Messenger)', 'Mediante este hechizo, utilizas un animal para entregar un mensaje. Elige una bestia diminuta que puedas ver dentro del alcance, como una ardilla, un arrendajo azul o un murciélago. Especificas un lugar, que debes haber visitado, y un destinatario que coincida con una descripción general, como \"un hombre o una mujer vestidos con el uniforme de la guardia de la ciudad\" o \"un enano pelirrojo con un sombrero puntiagudo\". También pronuncias un mensaje de hasta veinticinco palabras. La bestia objetivo viaja durante la duración del hechizo hacia el lugar especificado, cubriendo unas 50 millas por 24 horas para un mensajero volador, o 25 millas para otros animales.Cuando el mensajero llega, entrega tu mensaje a la criatura que has descrito, replicando el sonido de tu voz. El mensajero sólo habla con una criatura que coincida con la descripción que le diste. Si el mensajero no llega a su destino antes de que termine el hechizo, el mensaje se pierde, y la bestia regresa al lugar donde lanzaste este hechizo.', '24 horas', 'no', '1 acción', 'Nivel 2', '30 pies', 'Bardo, Druida, Explorador', 'Encantamiento'),
(111, 'Cerradura arcana (Arcane Lock)', 'Tocas una puerta, ventana, verja, cofre u otra entrada cerrada y queda bloqueada mientras dure el hechizo. Tú y las criaturas que designes al lanzar este hechizo podéis abrir el objeto normalmente. También puedes establecer una contraseña que, cuando se pronuncia a menos de 1,5 m del objeto, suprime este hechizo durante 1 minuto. De lo contrario, queda infranqueable hasta que se rompa o se disipe o suprima el hechizo. Lanzar golpear sobre el objeto suprime el bloqueo arcano durante 10 minutos.Mientras esté afectado por este hechizo, el objeto es más difícil de romper o abrir por la fuerza; la CD para romperlo o forzar cualquier cerradura que tenga aumenta en 10.', 'Hasta que se disipe', 'no', '1 acción', 'Nivel 2', 'Toque', 'Mago, Lanzador de Rituales', 'Abjuracion'),
(112, 'Augurio (Augury)', 'Al lanzar palos con gemas incrustadas, rodar huesos de dragón, colocar cartas ornamentadas o emplear alguna otra herramienta de adivinación, recibes un presagio de una entidad de otro mundo sobre los resultados de un curso de acción específico que planeas tomar en los próximos 30 minutos. El DM elige entre los siguientes presagios posibles:- Bien, para buenos resultados- Ay, para malos resultados- Bueno y malo, para resultados tanto buenos como malos- Nada, para resultados que no sean especialmente buenos o malosEl hechizo no tiene en cuenta posibles circunstancias que puedan cambiar el resultado, como el lanzamiento de hechizos adicionales o la pérdida o ganancia de un compañero.Si lanzas el hechizo dos o más veces antes de completar tu siguiente descanso largo, hay una probabilidad acumulativa del 25% por cada lanzamiento después del primero de que obtengas una lectura aleatoria. El DM hace esta tirada en secreto.', 'Instantaneo', 'no', '1 minuto', 'Nivel 2', 'Personal', 'Clérigo, Clerigo', 'Adivinacion'),
(113, 'Piel de corteza (Barkskin)', 'Tocas a una criatura dispuesta. Hasta que el hechizo termine, la piel del objetivo adquiere un aspecto áspero, como de corteza, y su CA no puede ser inferior a 16, independientemente del tipo de armadura que lleve.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', 'Toque', 'Druida, Explorador', 'Transmutacion'),
(114, 'Sentido de bestia (Beast Sense)', 'Tocas a una bestia dispuesta. Mientras dure el conjuro, puedes utilizar tu acción para ver a través de los ojos de la bestia y oír lo que oye, y continuar haciéndolo hasta que utilices tu acción para volver a tus sentidos normales. Mientras percibes a través de los sentidos de la bestia, obtienes los beneficios de cualquier sentido especial poseído por esa criatura, aunque estás cegado y ensordecido a tu propio entorno.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', 'Toque', 'Druida, Explorador', 'Adivinacion'),
(115, 'Ceguera/Sordera (Blindness/Deafness)', 'Puedes cegar o ensordecer a un enemigo. Elige una criatura que puedas ver dentro de tu alcance para realizar una tirada de salvación de Constitución. Si falla, el objetivo queda cegado o ensordecido (a tu elección) mientras dure el ataque. Al final de cada turno, el objetivo puede realizar una tirada de salvación de Constitución. Si tiene éxito, el hechizo termina.', '1 minuto', 'no', '1 acción', 'Nivel 2', '30 pies', 'Bardo, Clérigo, Clerigo, Hechicero, Mago, Brujo, Lanzador de Rituales', 'Nigromancia'),
(116, 'Distorsión (Blur)', 'Tu cuerpo se vuelve borroso, cambiante y vacilante para todos los que puedan verte. Mientras dure, cualquier criatura tiene desventaja en las tiradas de ataque contra ti. Un atacante es inmune a este efecto si no depende de la vista, como ocurre con la vista ciega, o si puede ver a través de ilusiones, como ocurre con la vista verdadera.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', 'Personal', 'Hechicero, Mago, Lanzador de Rituales', 'Ilusion'),
(117, 'Golpe revelador (Branding Smite)', 'La próxima vez que golpees a una criatura con un ataque de arma antes de que termine este conjuro, el arma brilla con resplandor astral mientras golpeas. El ataque inflige 2d6 puntos de daño radiante adicionales al objetivo, que se vuelve visible si es invisible, y el objetivo desprende una luz tenue en un radio de 1,5 m y no puede volverse invisible hasta que finalice el hechizo.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 2', 'Personal', 'Paladín, Paladin', 'Evocacion'),
(118, 'Calmar emociones (Calm Emotions)', 'Intentas suprimir las emociones fuertes en un grupo de personas. Cada humanoide en una esfera de 20 pies de radio centrada en un punto que elijas dentro del alcance debe realizar una tirada de salvación de carisma; una criatura puede elegir fallar esta tirada de salvación si lo desea. Si una criatura falla su tirada de salvación, elige uno de los dos efectos siguientes. Puedes suprimir cualquier efecto que cause que un objetivo esté encantado o asustado. Cuando este conjuro termina, cualquier efecto suprimido se reanuda, siempre que su duración no haya expirado mientras tanto.Alternativamente, puedes hacer que un objetivo se vuelva indiferente hacia criaturas de tu elección hacia las que sea hostil. Esta indiferencia termina si el objetivo es atacado o dañado por un hechizo o si es testigo de cómo alguno de sus amigos es dañado. Cuando el hechizo termina, la criatura vuelve a ser hostil, a menos que el DM decida lo contrario.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Clérigo, Clerigo', 'Encantamiento'),
(119, 'Nube de dagas (Cloud of Daggers)', 'Llenas el aire de dagas giratorias en un cubo de 5 pies de lado, centrado en un punto que elijas dentro del alcance. Una criatura recibe 4d4 puntos de daño cortante cuando entra en el área del hechizo por primera vez en un turno o comienza su turno allí.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Hechicero, Mago, Brujo, Lanzador de Rituales', 'Conjuracion'),
(120, 'Llama continua (Continual Flame)', 'Una llama, equivalente en brillo a una antorcha, brota de un objeto que tocas. El efecto se parece al de una llama normal, pero no genera calor y no utiliza oxígeno. Una llama continua puede cubrirse u ocultarse, pero no sofocarse ni apagarse.', 'Hasta que se disipe', 'no', '1 acción', 'Nivel 2', 'Toque', 'Clérigo, Clerigo, Mago, Lanzador de Rituales', 'Evocacion'),
(121, 'Cordón de flechas (Cordon of Arrows)', 'Plantas cuatro piezas de munición no mágica -flechas o virotes de ballesta- en el suelo dentro de tu alcance y depositas magia sobre ellas para proteger un área. Hasta que el hechizo termine, siempre que una criatura que no seas tú se acerque a menos de 30 pies de la munición por primera vez en un turno o termine su turno allí, una pieza de munición vuela hacia arriba para golpearla. La criatura debe tener éxito en una tirada de salvación de destreza o sufrir 1d6 puntos de daño perforante. La munición se destruye. El hechizo termina cuando no queda munición.Cuando lanzas este conjuro, puedes designar a las criaturas que quieras, y el conjuro las ignora.', '8 horas', 'no', '1 acción', 'Nivel 2', '5 pies', 'Explorador', 'Transmutacion'),
(122, 'Corona de locura (Crown of Madness)', 'Un humanoide de tu elección que puedas ver dentro de tu alcance debe tener éxito en una tirada de salvación de sabiduría o queda hechizado por ti mientras dure el hechizo. Mientras el objetivo esté hechizado de este modo, aparece una corona retorcida de hierro dentado en su cabeza y una locura brilla en sus ojos.El objetivo encantado debe utilizar su acción antes de moverse en cada uno de sus turnos para realizar un ataque cuerpo a cuerpo contra una criatura que no sea él mismo y que elijas mentalmente.El objetivo puede actuar normalmente en su turno si no eliges ninguna criatura o si no hay ninguna a su alcance.En tus turnos siguientes, debes usar tu acción para mantener el control sobre el objetivo, o el hechizo termina. Además, el objetivo puede realizar una tirada de salvación de sabiduría al final de cada uno de sus turnos. Si tiene éxito, el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '120 pies', 'Bardo, Hechicero, Mago, Brujo, Lanzador de Rituales', 'Encantamiento'),
(123, 'Oscuridad (Darkness)', 'La oscuridad mágica se extiende desde un punto que elijas dentro del alcance para llenar una esfera de 15 pies de radio mientras dure el efecto. La oscuridad se extiende alrededor de las esquinas. Una criatura con visión oscura no puede ver a través de esta oscuridad, y la luz no mágica no puede iluminarla.Si el punto que eliges está en un objeto que sostienes o en uno que no llevas puesto o transportas, la oscuridad emana del objeto y se mueve con él. Cubrir completamente la fuente de la oscuridad con un objeto opaco, como un cuenco o un yelmo, bloquea la oscuridad.Si cualquier área de este hechizo se solapa con un área de luz creada por un hechizo de 2º nivel o inferior, el hechizo que creó la luz se disipa.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 2', '60 pies', 'Hechicero, Mago, Brujo, Lanzador de Rituales', 'Evocacion'),
(124, 'Visión en la oscuridad (Darkvision)', 'Tocas a una criatura dispuesta y le concedes la capacidad de ver en la oscuridad. Mientras dure el efecto, la criatura tendrá visión en la oscuridad hasta un alcance de 60 pies.', '8 horas', 'no', '1 acción', 'Nivel 2', 'Toque', 'Druida, Explorador, Hechicero, Mago, Lanzador de Rituales', 'Transmutacion'),
(125, 'Detectar pensamientos (Detect Thoughts)', 'Mientras dure el hechizo, puedes leer los pensamientos de algunas criaturas. Mientras lanzas el conjuro y en tu acción en cada asalto hasta que finalice el conjuro, puedes concentrar tu mente en una criatura que puedas ver a 30 pies de ti. Si la criatura elegida tiene una Inteligencia de 3 o menos, o si no habla ningún idioma, la criatura no se ve afectada.Primero lees los pensamientos superficiales de la criatura, lo que ocupa su mente en ese momento. En una acción, puedes dirigir tu atención a los pensamientos de otra criatura o intentar profundizar tu lectura de los pensamientos de la misma criatura. Si profundizas tu lectura, el objetivo debe hacer un respaldo de Sabiduría, de lo contrario obtienes acceso a su argumento (si lo hay), en su estado emocional y el pensamiento que ocupa su mente en un espectro más amplio Tal una preocupación, el amor o el odio. Si tiene éxito, el hechizo termina. En todos los casos, el objetivo es consciente de que su mente está bajo tus ojos. A menos que estés dirigiendo tu atención a los pensamientos de otra criatura, el objetivo puede usar su turno de acción para tirar Inteligencia frente a tu tirada de Inteligencia. Si tiene ventaja, el hechizo termina.Las preguntas dirigidas verbalmente al objetivo guían el tren del pensamiento. Este hechizo es especialmente efectivo durante un interrogatorio.También puedes utilizar este hechizo para detectar la presencia de criaturas pensantes que sean invisibles para ti. Cuando lanzas este hechizo, o en una acción durante la duración del hechizo, puedes encontrar pensamientos a 30 pies de ti. El hechizo puede anular la mayoría de los obstáculos, pero es bloqueado por 2 pies de piedra 2 pulgadas de metal precioso, o una fina lámina de plomo. No puedes detectar a una criatura con una Inteligencia de 3 o menos o que hable cualquier idioma.Después de detectar la presencia de una criatura de esta forma, puedes leer sus pensamientos durante el resto de la duración del conjuro como se ha descrito anteriormente, incluso si no puedes verla, pero sólo si permanece dentro del alcance del conjuro.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', 'Personal', 'Bardo, Hechicero, Brujo, Mago', 'Adivinacion'),
(126, 'Diablillo de polvo (Dust Devil)', 'Elige un cubo de aire desocupado de 5 pies que puedas ver dentro del alcance. Una fuerza elemental parecida a un demonio de polvo aparece en el cubo y dura lo que dura el hechizo.Cualquier criatura que termine su turno a menos de 5 pies del demonio de polvo debe hacer una tirada de salvación de Fuerza. Si falla, la criatura recibe 1d8 puntos de daño contundente y es empujada a 3 metros de distancia. Con una salvación exitosa, la criatura recibe la mitad de daño y no es empujada.Como acción adicional, puedes mover al demonio de polvo hasta 9 metros en cualquier dirección. Si el demonio del polvo se mueve sobre arena, polvo, tierra suelta o grava pequeña, absorbe el material y forma una nube de escombros de 10 pies de radio a su alrededor que dura hasta el comienzo de tu siguiente turno. La nube oscurece mucho su área.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '60 pies', 'Druida, Hechicero, Mago', 'Conjuracion'),
(127, 'Vínculo con la tierra (Earthbind)', 'Elige una criatura que puedas ver dentro del alcance. Tiras amarillas de energía mágica rodean a la criatura. El objetivo debe tener éxito en una tirada de salvación de Fuerza o su velocidad de vuelo (si la tiene) se reduce a 0 pies durante la duración del hechizo. Una criatura en el aire afectada por este hechizo desciende a 60 pies por asalto hasta que llega al suelo o el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '300 pies', 'Druida, Hechicero, Brujo, Mago', 'Transmutacion'),
(128, 'Mejorar habilidad (Enhance Ability)', 'Tocas a una criatura y le otorgas una mejora mágica. Elige uno de los siguientes efectos; el objetivo obtiene ese efecto hasta que finaliza el hechizo.<b>Resistencia del Oso.</b> El objetivo tiene ventaja en los chequeos de Constitución. También gana 2d6 puntos de golpe temporales, que se pierden cuando finaliza el hechizo. <b>Fuerza del Toro.</b> El objetivo tiene ventaja en los chequeos de fuerza y su capacidad de carga se duplica.<b>Gracia de Gato.</b> El objetivo tiene ventaja en los chequeos de destreza. Además, no recibe daño al caer desde 6 metros o menos si no está incapacitado.<b>Esplendor del Águila.</b> El objetivo tiene ventaja en los chequeos de Carisma.<b>Astucia del zorro.</b> El objetivo tiene ventaja en los chequeos de Inteligencia.<b>Sabiduría de búho.</b> El objetivo tiene ventaja en los chequeos de sabiduría.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', 'Toque', 'Bardo, Clerigo, Druida, Hechicero', 'Transmutacion'),
(129, 'Agrandar/Reducir (Enlarge/Reduce)', 'Aumenta o reduce el tamaño de una criatura u objeto que puedas ver y esté dentro del alcance durante la duración del hechizo. Elige una criatura u objeto que no se lleve encima. Si el objetivo no da su consentimiento, puede realizar una tirada de salvación de Constitución. Si tiene éxito, el hechizo no tiene efecto.Si el objetivo es una criatura, todo lo que lleva y viste cambia de tamaño. Cualquier objeto que deje caer la criatura afectada vuelve a su tamaño normal.<b>Aumento.</b> El objetivo doble en todas las dimensiones, y su peso se multiplica por ocho. Esto aumenta el tamaño de una clase de M a G, por ejemplo. Si no hay espacio suficiente en la habitación para el tamaño del objetivo doble, la criatura u objeto alcanza el tamaño máximo posible en el espacio disponible. Hasta el final del hechizo, el objetivo también tiene la ventaja de sus chorros de Fuerza y salvaciones de Fuerza. Las armas del objetivo también crecen. Mientras estas armas estén agrandadas, los ataques del objetivo causan 1d4 puntos de daño adicionales.<b>Reducción.</b> El tamaño del objetivo se reduce a la mitad en todas las dimensiones, y su peso se divide por ocho. Esta reducción disminuye el tamaño de una clase de M a P, por ejemplo. Hasta el final del hechizo, el objetivo tiene desventaja a sus chorros de Fuerza y a sus salvaciones de Fuerza. Las armas del objetivo también se reducen. Mientras estas armas estén reducidas, los ataques del objetivo causan menos daño 1d4 (mínimo 1 punto de daño). ', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '30 pies', 'Hechicero, Mago', 'Transmutacion'),
(130, 'Fascinar (Enthrall)', 'Tejes una retahíla de palabras que distraen, provocando que las criaturas a tu elección que puedas ver dentro de tu alcance y que puedan oírte realicen una tirada de salvación de sabiduría. Cualquier criatura que no pueda ser encantada tiene éxito en esta tirada de salvación automáticamente, y si tú o tus compañeros estáis luchando contra una criatura, ésta tiene ventaja en la salvación. Si falla la tirada de salvación, el objetivo tiene desventaja en los chequeos de Sabiduría (Percepción) realizados para percibir a cualquier criatura que no seas tú hasta que el hechizo termine o hasta que el objetivo ya no pueda oírte. El hechizo termina si estás incapacitado o ya no puedes hablar.', '1 minuto', 'no', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Brujo', 'Encantamiento'),
(131, 'Encontrar corcel (Find Steed)', 'Invocas a un espíritu que adopta la forma de un corcel inusualmente inteligente, fuerte y leal, creando un vínculo duradero con él. Aparece en un espacio desocupado dentro de su alcance y adopta la forma que elijas, como un caballo de guerra, un poni, un camello, un alce o un mastín. (El corcel tiene las estadísticas de la forma elegida, aunque es celestial, feérico o demonio (a tu elección) en lugar de su tipo normal. Además, si tu corcel tiene una Inteligencia de 5 o menos, su Inteligencia pasa a ser de 6 y adquiere la capacidad de entender un idioma de tu elección que tú hables.Tu corcel te sirve como montura, tanto en combate como fuera de él, y tienes un vínculo instintivo con él que os permite luchar como una unidad sin fisuras. Mientras estás montado en tu corcel, puedes hacer que cualquier hechizo que lances y que sólo te tenga a ti como objetivo también se dirija a tu corcel.Cuando el corcel queda a 0 puntos de vida, desaparece sin dejar tras de sí ninguna forma física. También puedes despedir a tu corcel en cualquier momento como acción, haciendo que desaparezca. En cualquier caso, al lanzar este hechizo de nuevo invocas al mismo corcel, restaurado a su máximo de puntos de vida.Mientras tu corcel esté a menos de 1 milla de ti, puedes comunicarte con él telepáticamente.No puedes tener más de un corcel unido por este hechizo a la vez. Como acción, puedes liberar al corcel de su vínculo en cualquier momento, haciendo que desaparezca.', 'Instantaneo', 'no', '10 minutos', 'Nivel 2', '30 pies', 'Paladin', 'Conjuracion'),
(132, 'Encontrar trampas (Find Traps)', 'Percibes la presencia de cualquier trampa dentro del alcance que esté dentro de la línea de visión. Una trampa, a efectos de este hechizo, incluye cualquier cosa que pueda infligir un efecto repentino o inesperado que consideres dañino o indeseable, y que haya sido específicamente concebido como tal por su creador. Por lo tanto, el hechizo detectaría un área afectada por el hechizo de alarma, un glifo de protección o una trampa mecánica, pero no revelaría una debilidad natural en el suelo, un techo inestable o un sumidero oculto.Este hechizo sólo revela la existencia de una trampa. No aprendes la ubicación de cada trampa, pero sí la naturaleza general del peligro que supone una trampa que detectas.', 'Instantaneo', 'no', '1 acción', 'Nivel 2', '120 pies', 'Clerigo, Druida, Explorador', 'Adivinacion'),
(133, 'Espada de llamas (Flame Blade)', 'Evocas una hoja ardiente en tu mano libre. La hoja es similar en tamaño y forma a una cimitarra, y dura lo que dura. Si la sueltas, desaparece, pero puedes evocarla de nuevo como acción adicional.Puedes utilizar tu acción para realizar un ataque de conjuro cuerpo a cuerpo con la hoja ardiente. Si aciertas, el objetivo recibe 3d6 puntos de daño por fuego.La hoja ardiente arroja luz brillante en un radio de 3 metros y luz tenue en un radio adicional de 3 metros.', 'Hasta 10 minutos', 'si', '1 acción adicional', 'Nivel 2', 'Personal', 'Druida', 'Evocacion'),
(134, 'Esfera llameante (Flaming Sphere)', 'Aparece una esfera de fuego de 1,5 m de diámetro en un espacio desocupado de tu elección dentro del alcance y dura lo que dure el efecto. Cualquier criatura que termine su turno a menos de 1,5 m de la esfera debe realizar una tirada de salvación de destreza. La criatura sufre 2d6 puntos de daño por fuego si falla la tirada de salvación, o la mitad de daño si tiene éxito.Como acción adicional, puedes mover la esfera hasta 30 pies. Si embistes la esfera contra una criatura, esa criatura debe hacer la tirada de salvación contra el daño de la esfera, y la esfera deja de moverse este turno.Cuando mueves la esfera, puedes dirigirla por encima de barreras de hasta 5 pies de altura y hacerla saltar a través de fosos de hasta 10 pies de ancho. La esfera prende fuego a los objetos inflamables que no se lleven encima, y emite luz brillante en un radio de 6 metros y luz tenue en un radio adicional de 6 metros.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '60 pies', 'Clerigo, Druida, Mago', 'Conjuracion'),
(135, 'Reposo gentil (Gentle Repose)', 'Tocas un cadáver u otros restos. Mientras dure, el objetivo estará protegido de la putrefacción y no podrá convertirse en no muerto.El hechizo también amplía el límite de tiempo para resucitar al objetivo, ya que los días que pasas bajo la influencia de este hechizo no cuentan para el límite de tiempo de hechizos como resucitar muertos.', '10 days', 'no', '1 acción', 'Nivel 2', 'Toque', 'Clerigo, Lanzador de Rituales, Mago', 'Nigromancia'),
(136, 'Ráfaga de viento (Gust of Wind)', 'Una línea de fuerte viento de 60 pies de largo y 10 pies de ancho sale de ti en la dirección que elijas durante la duración del hechizo. Cada criatura que comience su turno en la línea debe tener éxito en una tirada de salvación de fuerza o ser empujada 15 pies lejos de ti en una dirección que siga la línea.Cualquier criatura en la línea debe gastar 2 pies de movimiento por cada 1 pie que mueva al acercarse a ti.La ráfaga dispersa gas o vapor, y apaga velas, antorchas y llamas similares sin protección en la zona. Provoca que las llamas protegidas, como las de los faroles, bailen salvajemente y tiene un 50% de probabilidades de extinguirlas.Como acción adicional en cada uno de tus turnos antes de que termine el hechizo, puedes cambiar la dirección en la que la línea sale disparada de ti.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', 'Personal', 'Clerigo, Druida, Hechicero, Mago', 'Evocacion'),
(137, 'Metal ardiente (Heat Metal)', 'Elige un objeto metálico fabricado, como un arma de metal o una armadura de metal pesado o medio, que puedas ver dentro del alcance. Haces que el objeto brille al rojo vivo. Cualquier criatura en contacto físico con el objeto recibe 2d8 puntos de daño por fuego cuando lanzas el hechizo. Hasta que el hechizo termine, puedes usar una acción adicional en cada uno de tus turnos siguientes para causar este daño de nuevo.Si una criatura sujeta o lleva puesto el objeto y recibe el daño, debe tener éxito en una tirada de salvación de Constitución o soltar el objeto si puede. Si no lo suelta, tiene desventaja en las tiradas de ataque y los chequeos de habilidad hasta el inicio de tu siguiente turno.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Druida', 'Transmutacion'),
(138, 'Inmovilizar persona (Hold Person)', 'Elige un humanoide que puedas ver dentro del alcance. El objetivo debe tener éxito en una tirada de salvación o quedará paralizado mientras dure el efecto. Al final de cada turno, el objetivo puede realizar otra tirada de salvación de sabiduría. Si tiene éxito, el hechizo termina para el objetivo.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Clerigo, Druida, Paladin, Hechicero, Brujo, Mago', 'Encantamiento'),
(139, 'Invisibilidad (Invisibility)', 'Una criatura que toques se vuelve invisible hasta que finaliza el hechizo. Todo lo que el objetivo lleve puesto es invisible mientras lo lleve encima. El hechizo termina para un objetivo que ataque o lance un hechizo.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', 'Toque', 'Bardo, Druida, Hechicero, Brujo, Mago', 'Ilusion'),
(140, 'Golpe (Knock)', 'Elige un objeto que puedas ver dentro de tu alcance. El objeto puede ser una puerta, una caja, un cofre, un juego de manillas, un candado u otro objeto que contenga un medio mundano o mágico que impida el acceso.Un objetivo que esté cerrado por una cerradura mundana o que esté atascado o enrejado se desbloquea, se desatasca o se desenreja. Si el objeto tiene varias cerraduras, sólo se desbloquea una de ellas.Si eliges un objetivo que está cerrado con cerradura arcana, ese hechizo se suprime durante 10 minutos, tiempo durante el cual el objetivo puede abrirse y cerrarse normalmente.Cuando lanzas el hechizo, un fuerte golpe, audible desde una distancia de hasta 300 pies, emana del objeto objetivo.', 'Instantaneo', 'no', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Hechicero, Mago', 'Transmutacion'),
(141, 'Restauración menor (Lesser Restoration)', 'Tocas a una criatura y puedes acabar con una enfermedad o una condición que la aflija. La condición puede ser ceguera, sordera, parálisis o envenenamiento.', 'Instantaneo', 'no', '1 acción', 'Nivel 2', 'Toque', 'Bardo, Clerigo, Druida, Paladin, Explorador', 'Abjuracion'),
(142, 'Levitar (Levitate)', 'Una criatura u objeto de tu elección que puedas ver dentro del alcance se eleva verticalmente, hasta 6 metros, y permanece suspendido allí mientras dura el hechizo. El hechizo puede levitar un objetivo que pese hasta 500 libras. Una criatura no dispuesta que tenga éxito en una tirada de salvación de Constitución no se ve afectada.El objetivo sólo puede moverse empujando o tirando contra un objeto fijo o una superficie a su alcance (como una pared o un techo), lo que le permite moverse como si estuviera trepando. Puedes cambiar la altitud del objetivo hasta 6 metros en cualquier dirección en tu turno. Si tú eres el objetivo, puedes moverte hacia arriba o hacia abajo como parte de tu movimiento. De lo contrario, puedes usar tu acción para mover al objetivo, que debe permanecer dentro del alcance del hechizo.Cuando el hechizo termina, el objetivo flota suavemente hasta el suelo si aún está en el aire.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 2', '60 pies', 'Hechicero, Mago', 'Transmutacion'),
(143, 'Localizar animales o plantas (Locate Animals or Plants)', 'Describe o nombra un tipo específico de bestia o planta. Concentrándote en la voz de la naturaleza de tu entorno, aprendes la dirección y la distancia a la criatura o planta de ese tipo más cercana en un radio de 8 km, si hay alguna.', 'Instantaneo', 'no', '1 acción', 'Nivel 2', 'Personal', 'Bardo, Druida, Explorador, Lanzador de Rituales', 'Adivinacion'),
(144, 'Localizar objeto (Locate Object)', 'Describe o nombra un objeto que te resulte familiar. Percibes la dirección en la que se encuentra el objeto, siempre que esté a menos de 300 metros de ti. Si el objeto está en movimiento, conoces la dirección de su movimiento.El hechizo puede localizar un objeto específico conocido por ti, siempre y cuando lo hayas visto de cerca -a menos de 30 pies- al menos una vez. Alternativamente, el hechizo puede localizar el objeto más cercano de un tipo particular, como un cierto tipo de ropa, joyas, muebles, herramientas o armas.Este hechizo no puede localizar un objeto si cualquier grosor de plomo, incluso una fina lámina, bloquea un camino directo entre tú y el objeto.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 2', 'Personal', 'Bardo, Clerigo, Druida, Paladin, Explorador, Mago', 'Adivinacion');
INSERT INTO `conjuros` (`id_spell`, `name`, `descr`, `duracion`, `concentracion`, `casteo`, `level`, `rango`, `clases`, `escuela`) VALUES
(145, 'Boca mágica (Magic Mouth)', 'Transmites un mensaje a un objeto dentro del alcance del hechizo. El mensaje se verbaliza cuando se cumplen las condiciones de activación. Elige un objeto que veas y que no lleve ni porte otra criatura. A continuación, verbaliza el mensaje, que no debe exceder de 25 palabras, pero la escucha puede durar hasta 10 minutos. Por último, establece las circunstancias que desencadenan el hechizo para entregar tu mensaje.Cuando se cumplen estas condiciones, aparece una boca mágica en el objeto y éste articula el mensaje imitando tu voz, el mismo tono utilizado durante la implantación del mensaje. Si el objeto seleccionado tiene boca o algo que se le aproxime, como la boca de una estatua, la boca mágica cobra vida en este momento, dando la ilusión de que las palabras salen de la boca del objeto.Cuando lanzas este hechizo, puedes decidir que el hechizo termine cuando el mensaje es entregado o puede persistir y repetir el mensaje cuando las circunstancias ocurran.La circunstancia desencadenante puede ser tan general o tan detallada como quieras, aunque debe basarse en condiciones visuales o audibles que ocurran a menos de 30 pies del objeto. Por ejemplo, puedes ordenar a la boca que hable cuando cualquier criatura se mueva a menos de 30 pies del objeto o cuando suene una campana de plata a menos de 30 pies de él.', 'Hasta que se disipe', 'no', '1 minuto', 'Nivel 2', '30 pies', 'Bardo, Lanzador de Rituales, Mago', 'Ilusion'),
(146, 'Arma mágica (Magic Weapon)', 'Tocas un arma no mágica. Hasta que el hechizo termine, esa arma se convierte en un arma mágica con un bonificador +1 a las tiradas de ataque y daño.', 'Hasta 1 hora', 'si', '1 acción adicional', 'Nivel 2', 'Toque', 'Clerigo, Paladin, Mago', 'Transmutacion'),
(147, 'Garra terrestre de Maximilian (Maximilian\'s Earthen Grasp)', 'Eliges un espacio desocupado de 5 pies cuadrados en el suelo que puedas ver dentro de tu alcance. Una mano mediana hecha de tierra compactada se eleva allí y alcanza a una criatura que puedas ver en un radio de 5 pies. El objetivo debe realizar una tirada de salvación de Fuerza. Si falla la tirada de salvación, el objetivo recibe 2d6 puntos de daño contundente y queda inmovilizado durante la duración del hechizo.Como acción, puedes hacer que la mano aplaste al objetivo inmovilizado, que debe realizar una tirada de salvación de Fuerza. Recibe 2d6 puntos de daño contundente si falla la tirada de salvación, o la mitad de daño si tiene éxito. Para escapar, el objetivo inmovilizado puede realizar un chequeo de Fuerza contra la CC de salvación de tu hechizo. Si tiene éxito, el objetivo escapa y deja de estar sujeto por la mano.Como acción, puedes hacer que la mano alcance a otra criatura o que se mueva a otro espacio desocupado dentro de su alcance. La mano libera al objetivo inmovilizado si haces cualquiera de las dos cosas.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '30 pies', 'Hechicero, Mago', 'Transmutacion'),
(148, 'Flecha ácida de Melf (Melf\'s Acid Arrow)', 'Una brillante flecha verde se dirige hacia un objetivo dentro del alcance y estalla en un chorro de ácido. Realiza un ataque de conjuro a distancia contra el objetivo. Si acierta, el objetivo recibe 4d4 puntos de daño ácido inmediatamente y 2d4 puntos de daño ácido al final de su siguiente turno. En caso de fallo, la flecha salpica al objetivo con ácido la mitad del daño inicial y ningún daño al final de su siguiente turno.', 'Instantaneo', 'no', '1 acción', 'Nivel 2', '90 pies', 'Mago, Lanzador de Rituales', 'Evocacion'),
(149, 'Imagen especular (Mirror Image)', 'Tres duplicados ilusorios de ti mismo aparecen en tu espacio. Hasta el final del hechizo, los duplicados se mueven contigo e imitan tus acciones, intercambiando su posición de modo que es imposible determinar qué imagen es la real. Puedes utilizar tu acción para disipar los duplicados ilusorios.Siempre que una criatura te apunte con un ataque durante la duración del hechizo, tira 1d20 para determinar si el ataque no apunta más bien a uno de tus duplicados.Si tienes tres duplicados, necesitas 6 o más en tu tirada para que el objetivo del ataque sea un duplicado. Con dos duplicados, necesitas 8 o más. Con un duplicado, necesitas 11 o más.La CA de un duplicado es 10 + tu modificador de Destreza. Si un ataque impacta en un duplicado, éste es destruido. Un duplicado puede ser destruido no sólo un ataque en clave. Ignora otros daños y efectos. El hechizo termina si los tres duplicados son destruidos.Una criatura no se ve afectada por este destino si ella no puede ver si se basa en un significado diferente como la visión, como la visión ciega, o si puede percibir las ilusiones como falsas, como con la visión clara.', '1 minuto', 'no', '1 acción', 'Nivel 2', 'Personal', 'Clerigo, Druida, Hechicero, Brujo, Mago', 'Ilusion'),
(150, 'Paso brumoso (Misty Step)', 'Rodeado brevemente por una niebla plateada, te teletransportas hasta 9 metros a un espacio desocupado que puedas ver.', 'Instantaneo', 'no', '1 acción adicional', 'Nivel 2', 'Personal', 'Druida, Paladin, Hechicero, Brujo, Mago', 'Conjuracion'),
(151, 'Rayo lunar (Moonbeam)', 'Un haz plateado de luz pálida brilla en un cilindro de 5 pies de radio y 40 pies de altura centrado en un punto dentro del alcance. Hasta que el hechizo termina, una luz tenue llena el cilindro.Cuando una criatura entra en el área del hechizo por primera vez en un turno o comienza su turno allí, se ve envuelta en llamas fantasmales que causan un dolor abrasador, y debe hacer una tirada de salvación de Constitución. Recibe 2d10 puntos de daño radiante si falla la tirada de salvación, o la mitad de daño si tiene éxito.Un cambiaformas realiza su tirada de salvación con desventaja. Si falla, también vuelve instantáneamente a su forma original y no puede adoptar una forma diferente hasta que abandone la luz del hechizo.En cada uno de tus turnos después de lanzar este conjuro, puedes usar una acción para mover el rayo 60 pies en cualquier dirección.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '120 pies', 'Druida, Paladin', 'Evocacion'),
(152, 'Aura mágica de Nystul (Nystul\'s Magic Aura)', 'Colocas una ilusión sobre una criatura o un objeto que tocas para que los conjuros de adivinación revelen información falsa sobre él. El objetivo puede ser una criatura dispuesta o un objeto que no esté siendo transportado o llevado por otra criatura.Cuando lances el hechizo, elige uno o ambos de los siguientes efectos. El efecto dura lo que dure el hechizo. Si lanzas este conjuro sobre la misma criatura u objeto todos los días durante 30 días, aplicándole el mismo efecto cada vez, la ilusión dura hasta que se disipa.<b>Aura falsa.</b> Cambias la apariencia del objetivo a los conjuros y efectos mágicos, como detectar magia, que detectan auras mágicas. Puedes hacer que un objeto no mágico parezca mágico, que un objeto mágico parezca no mágico o cambiar el aura mágica del objeto para que parezca pertenecer a una escuela de magia específica que tú elijas. Cuando utilizas este efecto sobre un objeto, puedes hacer que la falsa magia sea aparente para cualquier criatura que manipule el objeto.<b>Máscara.</b> Cambias la apariencia del objetivo ante hechizos y efectos mágicos que detectan tipos de criatura, como el Sentido Divino de un paladín o el desencadenante de un hechizo de símbolo. Eliges un tipo de criatura y otros conjuros y efectos mágicos tratan al objetivo como si fuera una criatura de ese tipo o de ese alineamiento.', '24 horas', 'no', '1 acción', 'Nivel 2', 'Toque', 'Mago', 'Ilusion'),
(153, 'Paso sin rastro (Pass without Trace)', 'Un velo de sombras y silencio irradia de ti, ocultándote a ti y a tus compañeros de ser detectados. Mientras dure, cada criatura que elijas en un radio de 30 pies (incluyéndote a ti) tiene un bonificador +10 a los chequeos de Destreza (Sigilo) y no puede ser rastreada salvo por medios mágicos. Una criatura que recibe este bonificador no deja huellas ni otros rastros de su paso.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', 'Personal', 'Clerigo, Druida, Explorador', 'Abjuracion'),
(154, 'Fuerza fantasmal (Phantasmal Force)', 'Creas una ilusión que arraiga en la mente de una criatura que puedas ver dentro de tu alcance. El objetivo debe realizar una tirada de salvación de Inteligencia. Si falla la tirada de salvación, creas un objeto fantasmal, criatura u otro fenómeno visible de tu elección que no sea mayor que un cubo de 3 metros y que sólo sea perceptible para el objetivo mientras dure el hechizo. Este conjuro no tiene efecto sobre muertos vivientes o constructos.El fantasma incluye sonido, temperatura y otros estímulos, también evidentes sólo para la criatura.El objetivo puede usar su acción para examinar el fantasma con un chequeo de Inteligencia (Investigación) contra tu DC de salvación del hechizo. Si el chequeo tiene éxito, el objetivo se da cuenta de que el fantasma es una ilusión y el hechizo termina.Mientras el objetivo esté afectado por el hechizo, tratará al fantasma como si fuera real. El objetivo racionaliza cualquier resultado ilógico de la interacción con el fantasma. Por ejemplo, un objetivo que intenta cruzar un puente fantasmal que salva un abismo cae en cuanto pisa el puente. Si el objetivo sobrevive a la caída, sigue creyendo que el puente existe e inventa alguna otra explicación para su caída: fue empujado, resbaló o un fuerte viento pudo haberlo derribado.El objetivo afectado está tan convencido de la realidad del fantasma que incluso puede sufrir daños a causa de la ilusión. Un fantasma creado para aparecer como una criatura puede atacar al objetivo. Del mismo modo, un fantasma creado para aparecer como fuego, un charco de ácido o lava puede quemar al objetivo. En cada asalto de tu turno, el fantasma puede infligir 1d6 puntos de daño psíquico al objetivo si éste se encuentra en el área del fantasma o a menos de 1,5 m del fantasma, siempre que la ilusión sea de una criatura o peligro que lógicamente pudiera infligir daño, como por ejemplo atacando. El objetivo percibe el daño como un tipo apropiado a la ilusión.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Hechicero, Brujo, Mago', 'Ilusion'),
(155, 'Oración de curación (Prayer of Healing)', 'Hasta seis criaturas de tu elección que puedas ver dentro de tu alcance recuperan cada una puntos de golpe iguales a 2d8 + tu modificador de habilidad de lanzamiento de conjuros. Este hechizo no tiene efecto sobre muertos vivientes o constructos.', 'Instantaneo', 'no', '10 minutos', 'Nivel 2', '30 pies', 'Clerigo', 'Evocacion'),
(156, 'Protección contra veneno (Protection from Poison)', 'Tocas a una criatura. Si está envenenada, neutralizas el veneno. Si el objetivo está envenenado con más de un veneno, neutralizas un veneno que sepas que está presente o neutralizas uno al azar.Mientras dure el efecto, el objetivo tiene ventaja en las tiradas de salvación contra el envenenamiento y resistencia al daño por veneno.', '1 hora', 'no', '1 acción', 'Nivel 2', 'Toque', 'Clerigo, Druida, Paladin, Explorador', 'Abjuracion'),
(157, 'Pirotecnia (Pyrotechnics)', 'Elige un área de llamas que puedas ver y que quepa dentro de un cubo de 5 pies dentro del alcance. Puedes extinguir el fuego en esa área y crear fuegos artificiales o humo.Fuegos artificiales. El objetivo explota con un deslumbrante despliegue de colores. Cada criatura en un radio de 3 metros del objetivo debe tener éxito en una tirada de salvación de Constitución o queda cegada hasta el final de tu siguiente turno.Humo. Un espeso humo negro se extiende desde el objetivo en un radio de 20 pies, moviéndose por las esquinas. El área del humo queda muy oscurecida. El humo persiste durante 1 minuto o hasta que un viento fuerte lo dispersa.', 'Instantaneo', 'no', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Hechicero, Mago', 'Transmutacion'),
(158, 'Rayo debilitador (Ray of Enfeeblement)', 'Un rayo negro de energía enervante brota de tu dedo hacia una criatura dentro del alcance. Realiza un ataque de hechizo a distancia contra el objetivo. Si aciertas, el objetivo sólo inflige la mitad de daño con ataques de arma que usen Fuerza hasta que finalice el hechizo.Al final de cada turno del objetivo, puede realizar una tirada de salvación de Constitución contra el hechizo. Si tiene éxito, el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 2', '60 pies', 'Brujo, Mago', 'Nigromancia'),
(159, 'Truco de cuerda (Rope Trick)', 'Toca una cuerda de hasta 60 pies de longitud. Un extremo de la cuerda se eleva en el aire hasta que toda la cuerda cuelga perpendicular al suelo. En el extremo superior de la cuerda, se abre una entrada invisible a un espacio extradimensional que dura hasta que finaliza el hechizo.Se puede acceder al espacio extradimensional subiendo a la parte superior de la cuerda. El espacio puede albergar hasta ocho criaturas medianas o más pequeñas. Se puede tirar de la cuerda hacia el interior del espacio, haciendo que la cuerda desaparezca de la vista fuera del espacio.Los ataques y hechizos no pueden atravesar la entrada ni la salida del espacio extradimensional, pero los que están dentro pueden ver fuera de él como si lo hicieran a través de una ventana de 3 por 5 pies centrada en la cuerda.Cualquier cosa dentro del espacio extradimensional sale cuando el hechizo termina.', '1 hora', 'no', '1 acción', 'Nivel 2', 'Toque', 'Mago', 'Transmutacion'),
(160, 'Rayo abrasador (Scorching Ray)', 'Generas tres rayos de fuego y los lanzas a objetivos en el radio de acción del hechizo. Puedes proyectarlos sobre uno o varios objetivos.Realiza un hechizo de ataque a distancia por cada departamento. Si impacta, el objetivo recibe 2d6 puntos de daño de fuego.', 'Instantaneo', 'no', '1 acción', 'Nivel 2', '120 pies', 'Clerigo, Hechicero, Brujo, Mago', 'Evocacion'),
(161, 'Ver lo invisible (See Invisibility)', 'Mientras dure el hechizo, ves criaturas y objetos invisibles como si fueran visibles, y puedes ver a través de Etéreo. Los objetos y criaturas etéreos aparecen fantasmagóricamente translúcidos.', '1 hora', 'no', '1 acción', 'Nivel 2', 'Personal', 'Bardo, Hechicero, Mago', 'Adivinacion'),
(162, 'Estallido (Shatter)', 'Un fuerte sonido resonante sonidos dolorosamente intensos de un punto deseado en el rango del hechizo. Cada criatura con una esfera de 10 pies de radio centrada en ese punto debe hacer una tirada de salvación de Constitución o sufre 3d8 puntos de daño por trueno. Si tiene éxito, el daño se reduce a la mitad. Una criatura hecha de materiales inorgánicos como piedra, cristal o metal, hace su tirada de salvación con desventaja.Un objeto no mágico que no se lleve encima también sufre daño si se encuentra en el área del hechizo.', 'Instantaneo', 'no', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Clerigo, Hechicero, Brujo, Mago', 'Evocacion'),
(163, 'Silencio (Silence)', 'Mientras dure el efecto, no se puede crear ningún sonido dentro de una esfera de 20 pies de radio centrada en un punto que elijas dentro del alcance. Cualquier criatura u objeto que se encuentre completamente dentro de la esfera es inmune al daño por trueno, y las criaturas quedan ensordecidas mientras se encuentren completamente dentro de ella.Es imposible lanzar un hechizo que incluya un componente verbal.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 2', '120 pies', 'Bardo, Clerigo, Druida, Explorador, Lanzador de Rituales', 'Ilusion'),
(164, 'Escribir en el cielo (Skywrite)', 'Haces que se formen hasta diez palabras en una parte del cielo que puedas ver. Las palabras parecen estar hechas de nubes y permanecen en su lugar mientras dura el hechizo. Las palabras se disipan cuando finaliza el hechizo. Un viento fuerte puede dispersar las nubes y poner fin al hechizo antes de tiempo.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', 'Sight', 'Bardo, Druida, Lanzador de Rituales, Mago', 'Transmutacion'),
(165, 'Avalancha de bolas de nieve de Snilloc (Snilloc\'s Snowball Swarm)', 'Una ráfaga de bolas de nieve mágicas surge de un punto que eliges dentro del alcance. Cada criatura en una esfera de 5 pies de radio centrada en ese punto debe hacer una tirada de salvación de Destreza. Una criatura recibe 3d6 puntos de daño por frío si falla la tirada de salvación, o la mitad de daño si tiene éxito.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', '90 pies', 'Hechicero, Mago', 'Evocacion'),
(166, 'Trepar como araña (Spider Climb)', 'Hasta que el hechizo termine, una criatura voluntaria que toques gana la habilidad de moverse hacia arriba, hacia abajo y a través de superficies verticales y boca abajo a lo largo de techos, mientras deja sus manos libres. El objetivo también obtiene una velocidad de escalada igual a su velocidad al caminar.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', 'Toque', 'Druida, Hechicero, Brujo, Mago', 'Transmutacion'),
(167, 'Crecimiento de espinas (Spike Growth)', 'El suelo en un radio de 20 pies centrado en un punto dentro del alcance se retuerce y brotan duros pinchos y espinas. La zona se convierte en terreno difícil mientras dure el efecto. Cuando una criatura se mueve hacia la zona o dentro de ella, sufre 2d4 puntos de daño perforante por cada 5 pies que recorre.El desarrollo del terreno se camufla para parecer natural. Cualquier criatura que no ve la zona cuando el hechizo se lanza debe hacer una Sabiduría (Percepción) frente a la copia de seguridad DD su destino o no reconoce la peligrosa naturaleza del terreno antes de entrar.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 2', '150 pies', 'Clerigo, Druida, Explorador', 'Transmutacion'),
(168, 'Arma espiritual (Spiritual Weapon)', 'Creas un arma espectral flotante a tu alcance que dura lo que dure el hechizo o hasta que vuelvas a lanzarlo. Cuando lanzas el conjuro, puedes realizar un ataque de conjuro cuerpo a cuerpo contra una criatura que se encuentre a 1,5 m del arma. Si aciertas, el objetivo sufre un daño de fuerza igual a 1d8 + tu modificador de habilidad de conjuro.Como acción adicional en tu turno, puedes mover el arma hasta 20 pies y repetir el ataque contra una criatura a 5 pies de ella.El arma puede adoptar cualquier forma que elijas. Los clérigos de deidades que están asociadas con un arma en particular (como San Cuthbert es conocido por su maza y Thor por su martillo) hacen que el efecto de este hechizo se parezca a esa arma.', '1 minuto', 'no', '1 acción adicional', 'Nivel 2', '60 pies', 'Clerigo', 'Evocacion'),
(169, 'Sugerencia (Suggestion)', 'Sugieres un curso de actividad (limitado a una o dos frases) e influyes mágicamente en una criatura que puedas ver dentro del alcance y que pueda oírte y entenderte. Las criaturas que no pueden ser encantadas son inmunes a este efecto. La sugerencia debe ser redactada de tal manera que el curso de acción suene razonable. Pedirle a la criatura que se apuñale a sí misma, que se lance a una lanza, que se inmolé o que haga algún otro acto obviamente dañino acaba con el hechizo.El objetivo debe realizar una tirada de salvación de sabiduría. Si falla la tirada de salvación, sigue el curso de acción que has descrito lo mejor que puede. La acción sugerida puede continuar durante todo el hechizo. Si la actividad sugerida puede completarse en menos tiempo, el hechizo termina cuando el sujeto termina lo que se le pidió que hiciera.También puedes especificar condiciones que desencadenen una actividad especial durante la duración. Por ejemplo, puedes sugerir que un caballero entregue su caballo de guerra al primer mendigo que encuentre. Si la condición no se cumple antes de que expire el hechizo, la actividad no se realiza.Si tú o alguno de tus compañeros dañáis al objetivo, el hechizo termina.', 'Hasta 8 horas', 'si', '1 acción', 'Nivel 2', '30 pies', 'Bardo, Clerigo, Hechicero, Brujo, Mago', 'Encantamiento'),
(170, 'Vínculo protector (Warding Bond)', 'Este hechizo protege a una criatura que toques y crea una conexión mística entre tú y el objetivo hasta que el hechizo termina. Mientras el objetivo esté a 60 pies de ti, gana un bonificador +1 a la CA y a las tiradas de salvación, y tiene resistencia a todo el daño. Además, cada vez que recibe daño, tú recibes la misma cantidad de daño.El hechizo termina si te quedas a 0 puntos de vida o si tú y el objetivo os separáis más de 60 pies.También termina si el hechizo se lanza de nuevo sobre cualquiera de las criaturas conectadas. También puedes descartar el hechizo como acción.', '1 hora', 'no', '1 acción', 'Nivel 2', 'Toque', 'Clerigo', 'Abjuracion'),
(171, 'Viento protector (Warding Wind)', 'Un fuerte viento (20 millas por hora) sopla a tu alrededor en un radio de 10 pies y se mueve contigo, permaneciendo centrado en ti. El viento dura lo que dura el hechizo. El viento tiene los siguientes efectos:- Te ensordece a ti y a otras criaturas en su área.- Apaga las llamas desprotegidas en su área que sean del tamaño de una antorcha o más pequeñas.- El área es terreno difícil para las criaturas que no seas tú.- Las tiradas de ataque de los ataques con armas a distancia tienen desventaja si pasan dentro o fuera del viento.- Cubre el vapor, el gas y la niebla que pueden ser dispersados por el viento fuerte.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 2', 'Personal', 'Bardo, Druida, Hechicero', 'Evocacion'),
(172, 'Telaraña (Web)', 'Conjuras una masa de telarañas gruesas y pegajosas en un punto de tu elección dentro de tu alcance. Las telarañas llenan un cubo de 6 metros desde ese punto mientras duran. Las telarañas son terreno difícil y oscurecen ligeramente su área.Si las telarañas no están ancladas entre dos masas sólidas (como paredes o árboles) o colocadas en capas sobre un suelo, pared o techo, la telaraña conjurada se derrumba sobre sí misma y el hechizo termina al inicio de tu siguiente turno. Las telarañas colocadas sobre una superficie plana tienen una profundidad de 1,5 metros.Cada criatura que comience su turno en las telarañas o que entre en ellas durante su turno debe realizar una tirada de salvación de destreza. Si falla la tirada de salvación, la criatura queda inmovilizada mientras permanezca en las telarañas o hasta que se libere.Una criatura retenida por las telarañas puede usar su acción para hacer un chequeo de Fuerza contra tu DC de salvación de hechizo. Si lo consigue, deja de estar atrapada.Las telarañas son inflamables. Cualquier cubo de telaraña de 1,5 m expuesto al fuego arde en 1 asalto, infligiendo 2d4 puntos de daño por fuego a cualquier criatura que comience su turno en el fuego.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 2', '60 pies', 'Druida, Hechicero, Mago', 'Conjuracion'),
(173, 'Zona de verdad', 'Creas una zona mágica que protege contra el engaño en una esfera de 15 pies de radio centrada en un punto de tu elección dentro del alcance. Hasta que el conjuro termine, una criatura que entre en el área del conjuro por primera vez en un turno o comience su turno allí debe hacer una tirada de salvación de Carisma. En una salvación fallida, una criatura no puede decir una mentira deliberada mientras esté en el radio. Sabes si cada criatura tiene éxito o fracasa en su tirada de salvación.Una criatura afectada es consciente del destino y puede evitar responder a preguntas que normalmente habría respondido con una mentira. Dicha criatura puede seguir siendo evasiva en sus respuestas mientras permanezcan dentro de los límites de la verdad.', '10 minutos', 'no', '1 acción', 'Nivel 2', '60 pies', 'Bardo, Clerigo, Paladin', 'Encantamiento'),
(174, 'Animar a los muertos (Animate Dead)', 'Este hechizo crea un sirviente no muerto. Elige una pila de huesos o un cadáver de un humanoide mediano o pequeño dentro del alcance. Tu hechizo imbuye al objetivo con una sucia imitación de la vida, elevándolo como criatura no muerta. El objetivo se convierte en un esqueleto si elegiste huesos o en un zombi si elegiste un cadáver (el DM tiene las estadísticas de juego de la criatura).En cada uno de tus turnos, puedes usar una acción de bonificación para ordenar mentalmente a cualquier criatura que hayas creado con este conjuro si la criatura está a menos de 60 pies de ti (si controlas múltiples criaturas, puedes ordenar a cualquiera o a todas ellas al mismo tiempo, emitiendo la misma orden a cada una). Tú decides qué acción realizará la criatura y a dónde se moverá durante su siguiente turno, o puedes dar una orden general, como vigilar una cámara o un pasillo en particular. Si no das ninguna orden, la criatura sólo se defiende de las criaturas hostiles. Una vez dada una orden, la criatura sigue cumpliéndola hasta completar su tarea.La criatura está bajo tu control durante 24 horas, tras las cuales deja de obedecer cualquier orden que le hayas dado. Para mantener el control de la criatura durante otras 24 horas, debes volver a lanzar este hechizo sobre la criatura antes de que termine el periodo de 24 horas actual. Este uso del hechizo reafirma tu control sobre hasta cuatro criaturas que hayas animado con este hechizo, en lugar de animar una nueva.', 'Instantaneo', 'no', '1 minuto', 'Nivel 3', '10 pies', 'Clérigo, Clerigo, Mago, Lanzador de Rituales', 'Nigromancia'),
(175, 'Aura de vitalidad (Aura of Vitality)', 'La energía curativa irradia de ti en un aura con un radio de 30 pies. Hasta que el hechizo termina, el aura se mueve contigo, centrada en ti. Puedes usar una acción de bonificación para hacer que una criatura en el aura (incluyéndote a ti) recupere 2d6 puntos de golpe.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', 'Personal', 'Paladín, Paladin', 'Evocacion'),
(176, 'Faro de esperanza (Beacon of Hope)', 'Este hechizo otorga esperanza y vitalidad. Elige cualquier número de criaturas dentro del alcance. Mientras dure, cada objetivo tiene ventaja en las tiradas de salvación de sabiduría y de muerte, y recupera el máximo número posible de puntos de golpe de cualquier curación.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', '30 pies', 'Clérigo, Clerigo', 'Abjuracion'),
(177, 'Imponer maldición (Bestow Curse)', 'Tocas a una criatura, y esa criatura debe tener éxito en una tirada de salvación de sabiduría o queda maldita mientras dure el hechizo. Cuando lances este conjuro, elige la naturaleza de la maldición entre las siguientes opciones:- Elige una puntuación de habilidad. Mientras esté maldito, el objetivo tiene desventaja en los chequeos de habilidad y tiradas de salvación hechas con esa puntuación de habilidad.- Mientras esté maldito, el objetivo tiene desventaja en las tiradas de ataque contra ti.- Mientras esté maldito, el objetivo debe realizar una tirada de salvación de sabiduría al comienzo de cada uno de sus turnos. Si falla, pierde su acción de ese turno sin hacer nada.- Mientras el objetivo esté maldito, tus ataques y hechizos le infligen 1d8 puntos de daño necrótico adicionales.Un hechizo de eliminar maldición acaba con este efecto. A elección del DM, puedes elegir un efecto de maldición alternativo, pero no debe ser más poderoso que los descritos anteriormente. El DM tiene la última palabra sobre el efecto de dicha maldición.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', 'Toque', 'Bardo, Clérigo, Clerigo, Mago, Lanzador de Rituales', 'Nigromancia'),
(178, 'Golpe cegador (Blinding Smite)', 'La próxima vez que golpees a una criatura con un ataque de arma cuerpo a cuerpo durante la duración de este hechizo, tu arma emite una luz brillante y el ataque inflige 3d8 puntos de daño radiante adicionales al objetivo. Además, el objetivo debe tener éxito en una tirada de salvación de Constitución o quedar cegado hasta que termine el hechizo.Una criatura cegada por este hechizo realiza otra tirada de salvación de Constitución al final de cada uno de sus turnos. Si tiene éxito, deja de estar cegada.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 3', 'Personal', 'Paladín, Paladin', 'Evocacion'),
(179, 'Parpadeo (Blink)', 'Tira un d20 al final de cada uno de tus turnos mientras dure el hechizo. Con una tirada de 11 o más, desapareces de tu plano de existencia actual y apareces en el Plano Etéreo (el hechizo falla y el lanzamiento se desperdicia si ya estabas en ese plano). Al comienzo de tu siguiente turno, y cuando el conjuro termina si estás en el Plano Etéreo, vuelves a un espacio desocupado de tu elección que puedas ver en un radio de 3 metros del espacio del que desapareciste. Si no hay ningún espacio desocupado disponible dentro de ese rango, apareces en el espacio desocupado más cercano (elegido al azar si hay más de un espacio igualmente cerca). Puedes descartar este hechizo como acción.Mientras estás en el Plano Etéreo, puedes ver y oír el plano del que procedes, que se proyecta en tonos grises, y no puedes ver nada allí a más de 60 pies de distancia. Sólo puedes afectar y ser afectado por otras criaturas en el Plano Etéreo. Las criaturas que no están allí no pueden percibirte ni interactuar contigo, a menos que tengan la habilidad para hacerlo.', '1 minuto', 'no', '1 acción', 'Nivel 3', 'Personal', 'Hechicero, Mago, Lanzador de Rituales', 'Transmutacion'),
(180, 'Invocar relámpagos (Call Lightning)', 'Una nube de tormenta aparece en la forma de un cilindro de 10 pies de alto con un radio de 60 pies, centrado en un punto que puedas ver 100 pies directamente sobre ti. El hechizo falla si no puedes ver un punto en el aire en el que pueda aparecer la nube de tormenta (por ejemplo, si estás en una habitación en la que no cabe la nube).Cuando lances el hechizo, elige un punto que puedas ver dentro del alcance. Un rayo cae desde la nube hasta ese punto. Cada criatura en un radio de 1,5 m de ese punto debe realizar una tirada de salvación de destreza. Una criatura recibe 3d10 puntos de daño por rayo si falla la tirada de salvación, o la mitad de daño si tiene éxito. En cada uno de tus turnos hasta que el hechizo termine, puedes usar tu acción para lanzar un rayo de esta forma de nuevo, apuntando al mismo punto o a uno diferente.Si estás al aire libre en condiciones de tormenta cuando lanzas este hechizo, el hechizo te da el control sobre la tormenta existente en lugar de crear una nueva. En tales condiciones, el daño del hechizo aumenta en 1d10.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 3', '120 pies', 'Druida', 'Conjuracion'),
(181, 'Clarividencia (Clairvoyance)', 'Creas un sensor invisible dentro del alcance en un lugar que te resulte familiar (un lugar que hayas visitado o visto antes) o en un lugar obvio que no te resulte familiar (como detrás de una puerta, a la vuelta de una esquina o en una arboleda). El sensor permanece en su lugar mientras dure el hechizo y no puede ser atacado ni se puede interactuar con él de ninguna otra forma.Cuando lanzas el hechizo, eliges ver u oír. Puedes utilizar el sentido elegido a través del sensor como si estuvieras en su espacio. Como acción, puedes cambiar entre ver y oír.Una criatura que pueda ver el sensor (como una criatura que se beneficie de ver invisibilidad o truesight) ve un orbe luminoso e intangible del tamaño de tu puño.', 'Hasta 10 minutos', 'si', '10 minutos', 'Nivel 3', '1 mile', 'Bardo, Clérigo, Clerigo, Hechicero, Mago, Lanzador de Rituales', 'Adivinacion'),
(182, 'Invocar animales (Conjure Animals)', 'Invocas espíritus feéricos que adoptan la forma de bestias y aparecen en espacios desocupados que puedes ver dentro de su alcance. Elige una de las siguientes opciones para lo que aparece:- Una bestia de nivel de desafío 2 o inferior- Dos bestias de nivel de desafío 1 o inferior- Cuatro bestias de nivel de desafío 1/2 o inferior- Ocho bestias de nivel de desafío 1/4 o inferior- Cada bestia también se considera fey, y desaparece cuando cae a 0 puntos de golpe o cuando el hechizo termina.Las criaturas invocadas son amistosas contigo y tus compañeros. Tira iniciativa para las criaturas invocadas como grupo, que tiene sus propios turnos. Obedecen cualquier orden verbal que les des (no requieren ninguna acción por tu parte). Si no les das ninguna orden, se defienden de las criaturas hostiles, pero por lo demás no realizan ninguna acción.El DM tiene las estadísticas de las criaturas.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 3', '60 pies', 'Druida, Explorador', 'Conjuracion'),
(183, 'Invocar descarga (Conjure Barrage)', 'Lanzas un arma no mágica o disparas una munición no mágica al aire para crear un cono de armas idénticas que salen disparadas hacia delante y luego desaparecen. Cada criatura en un cono de 60 pies debe tener éxito en una tirada de salvación de destreza. Una criatura recibe 3d8 puntos de daño si falla la tirada de salvación, o la mitad si tiene éxito. El tipo de daño es el mismo que el del arma o munición utilizada como componente.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', 'Personal', 'Explorador', 'Conjuracion'),
(184, 'Contraconjuro (Counterspell)', 'Intentas interrumpir a una criatura que está lanzando un hechizo. Si la criatura está lanzando un hechizo de 3er nivel o inferior, su hechizo falla y no tiene efecto. Si está lanzando un conjuro de 4º nivel o superior, realiza un chequeo de habilidad utilizando tu habilidad de lanzamiento de conjuros. La CD es igual a 10 + el nivel del hechizo. Si tiene éxito, el hechizo de la criatura falla y no tiene efecto.', 'Instantaneo', 'no', '1 reacción', 'Nivel 3', '60 pies', 'Hechicero, Mago, Brujo, Lanzador de Rituales', 'Abjuracion'),
(185, 'Crear comida y agua (Create Food and Water)', 'Creas 45 libras de comida y 30 galones de agua en el suelo o en contenedores a tu alcance, suficiente para mantener hasta quince humanoides o cinco corceles durante 24 horas. La comida es insípida pero nutritiva, y se echa a perder si no se come después de 24 horas. El agua está limpia y no se estropea.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', '30 pies', 'Clérigo, Clerigo, Paladín, Paladin', 'Conjuracion'),
(186, 'Manto del cruzado (Crusader\'s Mantle)', 'El poder sagrado irradia de ti en un aura con un radio de 30 pies, despertando la audacia en criaturas amistosas. Hasta que el hechizo termine, el aura se mueve contigo, centrada en ti. Mientras está en el aura, cada criatura no hostil en el aura (incluyéndote a ti) inflige 1d4 puntos de daño radiante extra cuando impacta con un ataque de arma.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', 'Personal', 'Paladín, Paladin', 'Evocacion'),
(187, 'Luz del día (Daylight)', 'Una esfera de luz de 60 pies de radio se extiende desde un punto que elijas dentro del alcance. La esfera es de luz brillante y arroja luz tenue durante 60 pies adicionales.Si eliges un punto en un objeto que sostienes o que no llevas puesto, la luz brilla desde el objeto y se mueve con él. Cubrir completamente el objeto afectado con un objeto opaco, como un cuenco o un yelmo, bloquea la luz.Si cualquier área de este hechizo se solapa con un área de oscuridad creada por un hechizo de 3er nivel o inferior, el hechizo que creó la oscuridad se disipa.', '1 hora', 'no', '1 acción', 'Nivel 3', '60 pies', 'Clérigo, Clerigo, Druida, Explorador, Paladín, Paladin', 'Evocacion'),
(188, 'Disipar magia (Dispel Magic)', 'Elige una criatura, objeto o efecto mágico dentro del alcance. Cualquier hechizo de 3er nivel o inferior sobre el objetivo termina. Por cada hechizo de 4º nivel o superior sobre el objetivo, realiza un chequeo de habilidad utilizando tu habilidad de lanzamiento de hechizos. La CD es igual a 10 + el nivel del hechizo. Si el chequeo tiene éxito, el hechizo termina.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', '120 pies', 'Bardo, Clerigo, Druida, Paladin, Hechicero, Brujo, Mago', 'Abjuracion'),
(189, 'Arma elemental (Elemental Weapon)', 'Un arma no mágica que toques se convierte en un arma mágica. Elige uno de los siguientes tipos de daño: ácido, frío, fuego, relámpago o trueno. Mientras dure, el arma tiene un bonificador +1 a las tiradas de ataque e inflige 1d4 puntos de daño adicionales del tipo elegido cuando impacta.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 3', 'Toque', 'Paladin', 'Transmutacion'),
(190, 'Tierra en erupción (Erupting Earth)', 'Elige un punto que puedas ver en el suelo dentro del alcance. Una fuente de tierra y piedra revueltas brota en un cubo de 6 metros centrado en ese punto. Cada criatura de la zona debe realizar una tirada de salvación de Destreza. Una criatura recibe 3d12 puntos de daño contundente si falla la tirada de salvación, o la mitad de daño si tiene éxito. Además, el suelo de esa zona se convierte en terreno difícil hasta que se despeje. Cada porción de 5 pies cuadrados del área requiere al menos 1 minuto para limpiarla a mano.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', '120 pies', 'Druida, Hechicero, Mago', 'Transmutacion'),
(191, 'Miedo (Fear)', 'Proyectas una imagen fantasmal de los peores miedos de una criatura. Cada criatura en un cono de 30 pies debe tener éxito en una tirada de salvación de sabiduría o soltar lo que esté sujetando y asustarse mientras dure el hechizo.Mientras esté asustada por este conjuro, una criatura debe realizar la acción de Pérdida y alejarse de ti por la ruta más segura disponible en cada uno de sus turnos, a menos que no haya ningún lugar al que moverse. Si la criatura termina su turno en un lugar donde no tiene línea de visión hacia ti, puede hacer una tirada de salvación de sabiduría. Si tiene éxito, el hechizo termina para esa criatura.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', 'Personal', 'Bardo, Hechicero, Brujo, Mago', 'Ilusion'),
(192, 'Fingir muerte (Feign Death)', 'Tocas a una criatura dispuesta y la pones en un estado cataléptico que es indistinguible de la muerte.Durante la duración del hechizo, o hasta que uses una acción para tocar al objetivo y descartar el hechizo, el objetivo parece muerto a todas las miradas externas y a los hechizos utilizados para determinar su estado. El objetivo está cegado e incapacitado, y su velocidad baja a 0. El objetivo tiene resistencia a todo el daño excepto al daño psíquico. Si el objetivo está enfermo o envenenado cuando lanzas el hechizo, o se enferma o envenena mientras está bajo el efecto del hechizo, la enfermedad y el veneno no tienen efecto hasta que el hechizo termina.', '1 hora', 'no', '1 acción', 'Nivel 3', 'Toque', 'Bardo, Clerigo, Druida, Lanzador de Rituales, Mago', 'Nigromancia'),
(193, 'Bola de fuego (Fireball)', 'Un rayo brillante parpadea desde el dedo que señalas hasta un punto que eliges dentro del alcance y luego florece con un rugido grave en una explosión de llamas. Cada criatura en una esfera de 20 pies de radio centrada en ese punto debe realizar una tirada de salvación de destreza. Un objetivo recibe 8d6 puntos de daño por fuego si falla la tirada de salvación, o la mitad de daño si tiene éxito.El fuego se propaga por las esquinas. Enciende los objetos inflamables de la zona que no se lleven encima.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', '150 pies', 'Clerigo, Hechicero, Brujo, Mago', 'Evocacion'),
(194, 'Flechas de fuego (Flame Arrows)', 'Tocas un carcaj que contiene flechas o virotes. Cuando un objetivo es alcanzado por un ataque de arma a distancia con una munición extraída del carcaj, el objetivo recibe 1d6 puntos de daño de fuego adicionales. La magia del conjuro termina en la pieza de munición cuando impacta o falla, y el conjuro termina cuando se han extraído doce piezas de munición del carcaj.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 3', 'Toque', 'Druida, Explorador, Hechicero, Mago', 'Transmutacion'),
(195, 'Volar (Fly)', 'Tocas a una criatura dispuesta. El objetivo obtiene una velocidad de vuelo de 60 pies mientras dure el hechizo. Cuando el hechizo termina, el objetivo cae si aún está en el aire, a menos que pueda detener la caída.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 3', 'Toque', 'Hechicero, Brujo, Mago', 'Transmutacion'),
(196, 'Forma gaseosa (Gaseous Form)', 'Transformas a una criatura que toques, junto con todo lo que lleve puesto, en una nube de niebla mientras dure el hechizo. El hechizo termina si la criatura cae a 0 puntos de golpe. Las criaturas incorpóreas no se ven afectadas.Mientras está en esta forma, el único método de movimiento del objetivo es una velocidad de vuelo de 10 pies. El objetivo puede entrar y ocupar el espacio de otra criatura. El objetivo tiene resistencia al daño no mágico y tiene ventaja en las tiradas de salvación de Fuerza, Destreza y Constitución. El objetivo puede atravesar pequeños agujeros, aberturas estrechas e incluso meras grietas, aunque trata los líquidos como si fueran superficies sólidas. El objetivo no puede caer y permanece suspendido en el aire incluso cuando está aturdido o incapacitado de algún otro modo.Mientras esté en forma de nube de niebla, el objetivo no puede hablar ni manipular objetos, y los objetos que lleve o sostenga no se pueden dejar caer, utilizar ni interactuar con ellos de ninguna otra forma. El objetivo no puede atacar ni lanzar hechizos.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 3', 'Toque', 'Druida, Hechicero, Brujo, Mago', 'Transmutacion'),
(197, 'Glifo de protección (Glyph of Warding)', 'Cuando lanzas este conjuro, introduces un glifo que hiere a otras criaturas, ya sea en una superficie (como una mesa o una porción de suelo o pared) o dentro de un objeto que pueda cerrarse (como un libro un pergamino o un armario) para ocultar el glifo. Si optas por una superficie, el glifo puede cubrir un área de 3 metros o menos de diámetro. Si seleccionas un objeto, éste debe permanecer en su lugar. Si el objeto se mueve a más de 10 pies del lugar donde se lanzó el hechizo, el glifo se desvanece y el hechizo expira sin activarse.El glifo es prácticamente invisible y rollo de Inteligencia (Investigación) contra el destino de su DC de ahorro se requiere para averiguarlo.Determinas el glifo del obturador mientras lanzas el conjuro. Para los glifos inscritos en una superficie, los desencadenantes suelen ser golpear o pararse sobre un glifo, retirar un objeto colocado sobre el glifo, acercarse a cierta distancia del glifo o manipular un objeto en el que esté inscrito el glifo. En el caso de los glifos inscritos en un objeto, los activadores suelen ser abrir el objeto, acercarse a cierta distancia del objeto, ver o leer el glifo. Una vez disparado el glifo, el hechizo finaliza.Puedes refinar las condiciones de activación para que el hechizo sólo funcione en determinadas circunstancias o atributos físicos (altura o peso), el tipo de criatura (por ejemplo, sólo las aberraciones o los Elfos Oscuros activan el glifo) o el alineamiento. También puedes determinar las condiciones para que ciertas criaturas no activen el glifo, mediante una contraseña, por ejemplo.Cuando firmes el glifo, elige entre las runas explosivas o el glifo destino.<b>Runas explosivas.</b> Cuando se activan, brota energía mágica del glifo en una esfera de 6 metros de radio centrada en el glifo. La esfera evita las esquinas. Cada criatura en el área debe realizar una tirada de salvación de destreza o sufre 5d8 puntos de daño por ácido, rayo, fuego, frío o trueno (a determinar durante la creación del glifo). Si tiene éxito, el daño se reduce a la mitad.<b>Glifo de ordenación.</b> Puedes almacenar un hechizo preparado de nivel 3 o inferior en el glifo para cantarlo durante la creación del glifo. El hechizo debe tener como objetivo una criatura o área. El hechizo almacenado no tiene efecto inmediato cuando se lanza así. Cuando se activa el glifo, el hechizo almacenado se lanza. Si el hechizo afecta a un objetivo, afectará a la criatura que activó el glifo. Si el hechizo afecta a un área, el área se centra en esa criatura. Si el hechizo invoca criaturas hostiles o crea objetos punzantes o trampas, éstas también aparecen lo más cerca posible del intruso y atacan. Si el hechizo requiere concentración, ésta persiste mientras dura el hechizo.', 'Hasta que se disipe', 'no', '1 hora', 'Nivel 3', 'Toque', 'Bardo, Clerigo, Mago', 'Abjuracion'),
(198, 'Celeridad (Haste)', 'Elige una criatura dispuesta que puedas ver dentro del alcance. Hasta que el hechizo termine, la velocidad del objetivo se duplica, gana un bonificador +2 a la CA, tiene ventaja en las tiradas de salvación de destreza y gana una acción adicional en cada uno de sus turnos. Esa acción sólo puede usarse para realizar las acciones Atacar (sólo un ataque de arma), Correr, Desengancharse, Esconderse o Usar un objeto.Cuando el hechizo termina, el objetivo no puede moverse ni realizar acciones hasta después de su siguiente turno, ya que una oleada de letargo lo invade.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', '30 pies', 'Druida, Paladin, Hechicero, Mago', 'Transmutacion'),
(199, 'Hambre de Hadar (Hunger of Hadar)', 'Abres un portal a la oscuridad entre las estrellas, una región infestada de horrores desconocidos. Aparece una esfera de negrura y frío intenso de 20 pies de radio, centrada en un punto con alcance y que dura lo que dura. Este vacío está lleno de una cacofonía de susurros suaves y ruidos de sorbos que pueden oírse hasta 30 pies de distancia. Ninguna luz, mágica o de otro tipo, puede iluminar la zona, y las criaturas que se encuentren completamente dentro de ella quedan cegadas.El vacío crea una deformación en el tejido del espacio, y la zona es terreno difícil. Cualquier criatura que comience su turno en la zona sufre 2d6 puntos de daño por frío. Cualquier criatura que termine su turno en la zona debe tener éxito en una tirada de salvación de destreza o sufrirá 2d6 puntos de daño por ácido al rozarse con tentáculos lechosos de otro mundo.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', '150 pies', 'Brujo', 'Conjuracion'),
(200, 'Patrón hipnótico (Hypnotic Pattern)', 'Creas un patrón retorcido de colores que teje en el aire dentro de un cubo de 30 pies dentro de tu alcance. El patrón aparece un instante y desaparece. Cada criatura del área que vea el patrón debe realizar una tirada de salvación de sabiduría. Si falla, la criatura queda hechizada mientras dure el hechizo. Mientras está encantada por este hechizo, la criatura está incapacitada y tiene una velocidad de 0. El hechizo termina para la criatura afectada.El hechizo termina para la criatura afectada si recibe algún daño o si alguien utiliza una acción para sacarla de su estupor.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', '120 pies', 'Bardo, Hechicero, Brujo, Mago', 'Ilusion'),
(201, 'Cabaña diminuta de Leomund (Leomund\'s Tiny Hut)', 'Una cúpula de fuerza inmóvil de 3 metros de radio surge a tu alrededor y sobre ti y permanece inmóvil mientras dure el hechizo. El hechizo termina si abandonas su área.Nueve criaturas de tamaño mediano o inferior caben dentro de la cúpula contigo. El hechizo falla si su área incluye una criatura mayor o más de nueve criaturas. Las criaturas y objetos dentro de la cúpula cuando lanzas este hechizo pueden moverse libremente a través de ella. Todas las demás criaturas y objetos tienen prohibido atravesarla. Los hechizos y otros efectos mágicos no pueden extenderse a través de la cúpula ni ser lanzados a través de ella. La atmósfera dentro del espacio es confortable y seca, independientemente del tiempo que haga fuera.Hasta que finalice el hechizo, puedes ordenar que el interior se ilumine tenuemente o se oscurezca. La cúpula es opaca desde el exterior, del color que elijas, pero es transparente desde el interior.', '8 horas', 'no', '1 minuto', 'Nivel 3', 'Personal', 'Bardo, Lanzador de Rituales, Mago', 'Evocacion'),
(202, 'Flecha relámpago (Lightning Arrow)', 'La próxima vez que realices un ataque con un arma a distancia durante la duración del hechizo, la munición del arma, o el arma misma si es un arma arrojadiza, se transforma en un rayo. Realiza la tirada de ataque de forma normal. El objetivo recibe 4d8 puntos de daño por rayo si acierta, o la mitad si falla, en lugar del daño normal del arma.Tanto si aciertas como si fallas, cada criatura en un radio de 3 m del objetivo debe realizar una tirada de salvación de destreza. Cada una de estas criaturas recibe 2d8 puntos de daño de rayo si falla la tirada de salvación, o la mitad de daño si tiene éxito.El arma o munición vuelve a su forma normal.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 3', 'Personal', 'Explorador', 'Transmutacion'),
(203, 'Rayo relámpago (Lightning Bolt)', 'Un rayo que forma una línea de 100 pies de largo y 5 pies de ancho sale de ti en la dirección que elijas. Cada criatura de la línea debe realizar una tirada de salvación de destreza. Una criatura recibe 8d6 puntos de daño por rayo si falla la tirada de salvación, o la mitad de daño si tiene éxito.El rayo enciende los objetos inflamables de la zona que no se lleven puestos.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', 'Personal', 'Hechicero, Mago, Lanzador de Rituales', 'Evocacion'),
(204, 'Círculo mágico (Magic Circle)', 'Elige uno o más de los siguientes tipos de criaturas: celestiales, elementales, fey, fiends o no muertos. El círculo afecta a una criatura del tipo elegido de las siguientes maneras:- La criatura no puede entrar voluntariamente en el cilindro por medios no mágicos. Si la criatura intenta utilizar el teletransporte o el viaje interplanar para hacerlo, primero debe tener éxito en una tirada de salvación de carisma.- La criatura tiene desventaja en las tiradas de ataque contra objetivos dentro del cilindro.- Los objetivos dentro del cilindro no pueden ser encantados, asustados o poseídos por la criatura.Cuando lanzas este conjuro, puedes elegir que su magia actúe en sentido inverso, impidiendo que una criatura del tipo especificado abandone el cilindro y protegiendo a los objetivos fuera de él.', '1 hora', 'no', '1 minuto', 'Nivel 3', '10 pies', 'Clerigo, Paladin, Brujo, Mago', 'Abjuracion');
INSERT INTO `conjuros` (`id_spell`, `name`, `descr`, `duracion`, `concentracion`, `casteo`, `level`, `rango`, `clases`, `escuela`) VALUES
(205, 'Imagen mayor (Major Image)', 'Creas la imagen de un objeto, una criatura o algún otro fenómeno visible que no sea mayor que un cubo de 20 pies. La imagen aparece en un punto que puedes ver dentro del alcance y dura lo que dura. Parece completamente real, incluyendo los sonidos, olores y temperatura apropiados a la cosa representada. No puedes crear suficiente calor o frío como para causar daño, un sonido lo suficientemente fuerte como para causar daño por trueno o ensordecer a una criatura, o un olor que pueda enfermar a una criatura (como el hedor de un troglodita).Mientras estés dentro del alcance de la ilusión, puedes usar tu acción para hacer que la imagen se mueva a cualquier otro lugar dentro del alcance. A medida que la imagen cambia de lugar, puedes alterar su apariencia para que sus movimientos parezcan naturales para la imagen. Por ejemplo, si creas una imagen de una criatura y la mueves, puedes alterar la imagen para que parezca que camina. Del mismo modo, puedes hacer que la ilusión emita diferentes sonidos en diferentes momentos, incluso que mantenga una conversación, por ejemplo.La interacción física con la imagen revela que es una ilusión, porque las cosas pueden pasar a través de ella. Una criatura que utilice su acción para examinar la imagen puede determinar que se trata de una ilusión con un chequeo de Inteligencia (Investigación) con éxito contra su DC de salvación de conjuro. Si una criatura discierne la ilusión por lo que es, la criatura puede ver a través de la imagen, y sus otras cualidades sensoriales se vuelven débiles para la criatura.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 3', '120 pies', 'Bardo, Hechicero, Brujo, Mago', 'Ilusion'),
(206, 'Palabra curativa en masa (Mass Healing Word)', 'Mientras pronuncias palabras de restauración, hasta seis criaturas de tu elección que puedas ver dentro de tu alcance recuperan puntos de golpe igual a 1d4 + tu modificador de habilidad de conjuro. Este hechizo no tiene efecto sobre muertos vivientes o constructos.', 'Instantaneo', 'no', '1 acción adicional', 'Nivel 3', '60 pies', 'Clerigo', 'Evocacion'),
(207, 'Fundirse con la piedra (Meld into Stone)', 'Te introduces en un objeto o superficie de piedra lo suficientemente grande como para contener todo tu cuerpo, fundiéndote tú y todo el equipo que lleves con la piedra mientras dure la acción. Utilizando tu movimiento, te introduces en la piedra en un punto que puedas tocar. Nada de tu presencia permanece visible o detectable por sentidos no mágicos.Mientras estás fusionado con la piedra, no puedes ver lo que ocurre fuera de ella, y cualquier chequeo de Sabiduría (Percepción) que hagas para oír sonidos fuera de ella se hace con desventaja. Sigues siendo consciente del paso del tiempo y puedes lanzarte conjuros mientras estás fusionado con la piedra. Puedes utilizar tu movimiento para salir de la piedra por donde entraste, lo que pone fin al hechizo. Por lo demás, no puedes moverte.Un daño físico menor a la piedra no te daña, pero su destrucción parcial o un cambio en su forma (hasta el punto de que ya no quepas en ella) te expulsa y te inflige 6d6 puntos de daño contundente. La destrucción completa de la piedra (o su transmutación en una sustancia diferente) te expulsa y te inflige 50 puntos de daño contundente. Si eres expulsado, caes tendido en el espacio desocupado más cercano al lugar por el que entraste.', '8 horas', 'no', '1 acción', 'Nivel 3', 'Toque', 'Clerigo, Druida, Lanzador de Rituales', 'Transmutacion'),
(208, 'Meteoritos diminutos de Melf (Melf\'s Minute Meteors)', 'Creas seis meteoritos diminutos en tu espacio. Flotan en el aire y te orbitan durante la duración del hechizo. Cuando lanzas el hechizo -y como acción adicional en cada uno de tus turnos posteriores- puedes gastar uno o dos de los meteoros, enviándolos a toda velocidad hacia un punto o puntos que elijas en un radio de 120 pies de ti. Una vez que el meteoro alcanza su destino o impacta contra una superficie sólida, explota. Cada criatura en un radio de 1,5 m del punto donde explota el meteoro debe realizar una tirada de salvación de Destreza. Una criatura recibe 2d6 puntos de daño por fuego si falla la tirada de salvación, o la mitad de daño si tiene éxito.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 3', 'Personal', 'Hechicero, Mago, Lanzador de Rituales', 'Transmutacion'),
(209, 'No detección (Nondetection)', 'Mientras dure, ocultas un objetivo que toques de la magia de adivinación. El objetivo puede ser una criatura dispuesta o un lugar u objeto que no supere los 3 metros en cualquier dimensión. El objetivo no puede ser apuntado por ninguna magia de adivinación ni percibido a través de sensores mágicos de adivinación.', '8 horas', 'no', '1 acción', 'Nivel 3', 'Toque', 'Bardo, Clerigo, Explorador, Mago', 'Abjuracion'),
(210, 'Corcel fantasma (Phantom Steed)', 'Una criatura grande, casi real, parecida a un caballo aparece en el suelo en un espacio desocupado de tu elección dentro de tu alcance. Tú decides el aspecto de la criatura, pero está equipada con silla de montar, bocado y brida. Todo el equipo creado por el hechizo se desvanece en una nube de humo si se aleja más de 3 metros del corcel.Mientras dure el hechizo, tú o la criatura que elijas podéis montar el corcel. La criatura utiliza las estadísticas de un caballo de montar, excepto que tiene una velocidad de 100 pies y puede recorrer 10 millas en una hora, o 13 millas a paso rápido. Cuando el hechizo termina, el corcel se desvanece gradualmente, dando al jinete 1 minuto para desmontar. El hechizo termina si utilizas una acción para desecharlo o si el corcel sufre algún daño.', '1 hora', 'no', '1 minuto', 'Nivel 3', '30 pies', 'Lanzador de Rituales, Mago', 'Ilusion'),
(211, 'Crecimiento de plantas (Plant Growth)', 'Este hechizo canaliza la vitalidad hacia las plantas dentro de un área específica. Hay dos usos posibles para el hechizo, que otorgan beneficios inmediatos o a largo plazo.Si lanzas este hechizo utilizando 1 acción, elige un punto dentro del alcance. Todas las plantas normales en un radio de 100 pies centrado en ese punto se vuelven espesas y crecen demasiado. Una criatura que se mueva a través del área debe gastar 4 pies de movimiento por cada 1 pie que se mueva.Puedes excluir una o más áreas de cualquier tamaño dentro del área del hechizo para que no se vean afectadas.Si lanzas este hechizo durante más de 8 horas, enriqueces la tierra. Todas las plantas en un radio de media milla centrado en un punto dentro del alcance se enriquecen durante 1 año. Las plantas rinden el doble de lo normal cuando se cosechan.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', '150 pies', 'Bardo, Clerigo, Druida, Paladin, Explorador, Brujo', 'Transmutacion'),
(212, 'Protección contra la energía (Protection from Energy)', 'Mientras dure, la criatura dispuesta que toques tiene resistencia a un tipo de daño a tu elección: ácido, frío, fuego, relámpago o trueno.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 3', 'Toque', 'Clerigo, Druida, Paladin, Explorador, Hechicero, Mago', 'Abjuracion'),
(213, 'Eliminar maldición (Remove Curse)', 'Al tocarte, todas las maldiciones que afecten a una criatura u objeto terminan. Si el objeto es un objeto mágico maldito, su maldición permanece, pero el hechizo rompe la sintonía de su propietario con el objeto para que pueda retirarlo o desecharlo.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', 'Toque', 'Clerigo, Paladin, Brujo, Mago', 'Abjuracion'),
(214, '', 'Tocas a una criatura que ha muerto en el último minuto. Esa criatura vuelve a la vida con 1 punto de golpe. Este hechizo no puede devolver la vida a una criatura que haya muerto de vejez, ni puede restaurar ninguna parte del cuerpo que le falte.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', 'Toque', 'Clerigo, Paladin', 'Conjuracion'),
(215, 'Envío (Sending)', 'Envías un mensaje corto de veinticinco palabras o menos a una criatura con la que estás familiarizado. La criatura escucha el mensaje en su mente, te reconoce como remitente si te conoce y puede responder de forma similar inmediatamente. El hechizo permite a las criaturas con una puntuación de Inteligencia de al menos 1 comprender el significado de tu mensaje.Puedes enviar el mensaje a cualquier distancia e incluso a otros planos de existencia, pero si el objetivo está en un plano diferente al tuyo, hay un 5% de posibilidades de que el mensaje no llegue.', '1 ronda', 'no', '1 acción', 'Nivel 3', 'Unlimited', 'Bardo, Clerigo, Brujo, Mago', 'Evocacion'),
(216, 'Tormenta de aguanieve (Sleet Storm)', 'Hasta que el hechizo termine, la lluvia helada y el aguanieve caen en un cilindro de 20 pies de altura con un radio de 40 pies centrado en un punto que elijas dentro del alcance. El área queda muy oscurecida y las llamas expuestas se apagan.El suelo de la zona está cubierto de hielo resbaladizo, lo que lo convierte en un terreno difícil. Cuando una criatura entra en el área del hechizo por primera vez en un turno o comienza su turno allí, debe realizar una tirada de salvación de destreza. Si falla la tirada de salvación, cae boca abajo.Si una criatura se está concentrando en el área del hechizo, debe realizar con éxito una tirada de salvación de Constitución contra la CC de salvación del hechizo o perderá la concentración.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', '150 pies', 'Clerigo, Druida, Hechicero, Mago', 'Conjuracion'),
(217, 'Lentitud (Slow)', 'Alteras el tiempo alrededor de hasta seis criaturas de tu elección en un cubo de 40 pies dentro de tu alcance. Cada objetivo debe tener éxito en una tirada de salvación de sabiduría o se verá afectado por este hechizo mientras dure.La velocidad de un objetivo afectado se reduce a la mitad, sufre un penalizador -2 a la CA y a las tiradas de salvación de destreza, y no puede usar reacciones. En su turno, puede utilizar una acción o una acción adicional, pero no ambas. Independientemente de las habilidades u objetos mágicos de la criatura, no puede realizar más de un ataque cuerpo a cuerpo o a distancia durante su turno.Si la criatura intenta lanzar un hechizo con un tiempo de lanzamiento de 1 acción, tira un d20. Con un 11 o más, el hechizo no surtirá efecto hasta el siguiente turno de la criatura, que deberá utilizar su acción de ese turno para completar el hechizo. Si no puede, el hechizo se pierde.Una criatura afectada por este hechizo realiza otra tirada de salvación de sabiduría al final de su turno. Si tiene éxito, el efecto termina para ella.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', '120 pies', 'Druida, Hechicero, Mago', 'Transmutacion'),
(218, 'Hablar con los muertos (Speak with Dead)', 'Concedes apariencia de vida e inteligencia a un cadáver de tu elección dentro de tu alcance, permitiéndole responder a las preguntas que le plantees. El cadáver debe tener boca y no puede ser un no muerto. El hechizo falla si el cadáver ha sido objeto de este hechizo en los últimos 10 días.Hasta que termine el hechizo, puedes hacer hasta cinco preguntas al cadáver. El cadáver sólo sabe lo que sabía en vida, incluidos los idiomas que conocía. Las respuestas suelen ser breves, crípticas o repetitivas, y el cadáver no está obligado a ofrecer una respuesta sincera si le eres hostil o te reconoce como enemigo. Este hechizo no devuelve el alma de la criatura a su cuerpo, sólo su espíritu animador. Por lo tanto, el cadáver no puede aprender nueva información, no comprende nada de lo que ha sucedido desde que murió y no puede especular sobre acontecimientos futuros.', '10 minutos', 'no', '1 acción', 'Nivel 3', '10 pies', 'Bardo, Clerigo', 'Nigromancia'),
(219, 'Hablar con las plantas (Speak with Plants)', 'Imbuyes a las plantas situadas a menos de 30 pies de ti una sensibilidad y animación limitadas, lo que les da la capacidad de comunicarse contigo y seguir tus órdenes sencillas. Puedes interrogar a las plantas sobre los acontecimientos ocurridos en el área del hechizo en el último día, obteniendo información sobre las criaturas que han pasado, el clima y otras circunstancias.También puedes convertir terrenos difíciles causados por el crecimiento de las plantas (como matorrales y maleza) en terrenos ordinarios durante el tiempo que dure el hechizo. O puedes convertir un terreno ordinario en el que haya plantas en un terreno difícil que dure lo que dure, haciendo que las enredaderas y ramas obstaculicen a los perseguidores, por ejemplo.Las plantas pueden ser capaces de realizar otras tareas en tu nombre, a discreción del DM. El hechizo no permite a las plantas desarraigarse y desplazarse, pero pueden mover libremente ramas, zarcillos y tallos.Si hay una criatura vegetal en la zona, puedes comunicarte con ella como si compartierais un idioma común, pero no obtienes ninguna habilidad mágica para influir en ella.Este hechizo puede hacer que las plantas creadas por el hechizo Enredar liberen a una criatura retenida.', '10 minutos', 'no', '1 acción', 'Nivel 3', 'Personal', 'Bardo, Druida, Explorador', 'Transmutacion'),
(220, 'Guardianes espirituales (Spirit Guardians)', 'Invocas a los espíritus para que te protejan. Revolotean a tu alrededor a una distancia de 15 pies mientras dura la invocación. Si eres bueno o neutral, su forma espectral parece angelical o feérica (a tu elección). Si eres malvado, su aspecto es diabólico.Cuando lanzas este hechizo, puedes designar cualquier número de criaturas que puedas ver para que no se vean afectadas por él. La velocidad de una criatura afectada se reduce a la mitad en el área, y cuando la criatura entra en el área por primera vez en un turno o comienza su turno allí, debe hacer una tirada de salvación de sabiduría. Con una salvación fallida, la criatura recibe 3d8 puntos de daño radiante (si eres bueno o neutral) o 3d8 puntos de daño necrótico (si eres malvado). Con una salvación exitosa, la criatura recibe la mitad de daño.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 3', 'Personal', 'Clerigo', 'Conjuracion'),
(221, 'Nube apestosa (Stinking Cloud)', 'Creas una esfera de 20 pies de radio de gas amarillo nauseabundo centrada en un punto dentro del alcance. La nube se extiende por las esquinas y su área queda muy oscurecida. La nube permanece en el aire mientras dura.Cada criatura que se encuentre completamente dentro de la nube al inicio de su turno debe realizar una tirada de salvación de Constitución contra el veneno. Si falla la tirada de salvación, la criatura gasta su acción de ese turno en dar arcadas y tambalearse. Las criaturas que no necesiten respirar o sean inmunes al veneno tienen éxito automáticamente en esta tirada de salvación.Un viento moderado (al menos 10 millas por hora) dispersa la nube tras 4 asaltos. Un viento fuerte (al menos 20 millas por hora) la dispersa tras 1 asalto.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', '90 pies', 'Bardo, Druida, Hechicero, Brujo, Mago', 'Conjuracion'),
(222, 'Ola gigante (Tidal Wave)', 'Conjuras una ola de agua que cae sobre un área dentro de tu alcance. El área puede medir hasta 30 pies de largo, 10 pies de ancho y 10 pies de alto. Cada criatura en esa área debe hacer una tirada de salvación de Destreza. Si falla, la criatura recibe 4d8 puntos de daño contundente y queda tendida. En caso de éxito, la criatura recibe la mitad de daño y no es derribada. El agua se extiende por el suelo en todas direcciones, extinguiendo las llamas desprotegidas en su área y en un radio de 30 pies.', 'Instantaneo', 'no', '1 acción', 'Nivel 3', '120 pies', 'Druida, Mago', 'Conjuracion'),
(223, 'Lenguas (Tongues)', 'Este hechizo otorga a la criatura que toques la capacidad de comprender cualquier idioma hablado que oiga. Además, cuando el objetivo habla, cualquier criatura que conozca al menos un idioma y pueda oírlo entiende lo que dice.', '1 hora', 'no', '1 acción', 'Nivel 3', 'Toque', 'Bardo, Clerigo, Hechicero, Brujo, Mago', 'Adivinacion'),
(224, 'Toque vampírico (Vampiric Touch)', 'El toque de tu mano envuelta en sombras puede desviar fuerza vital de otros para curar tus heridas. Haz un ataque de hechizo cuerpo a cuerpo contra una criatura a tu alcance. Si aciertas, el objetivo recibe 3d6 puntos de daño necrótico y tú recuperas puntos de golpe equivalentes a la mitad del daño necrótico infligido. Hasta que el hechizo termine, puedes realizar el ataque de nuevo en cada uno de tus turnos como acción.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', 'Personal', 'Brujo, Mago', 'Nigromancia'),
(225, 'Muro de arena (Wall of Sand)', 'Conjuras un muro de arena arremolinada en el suelo en un punto que puedas ver dentro de tu alcance. Puedes hacer el muro de hasta 30 pies de largo, 10 pies de alto y 10 pies de grosor, y desaparece cuando termina el hechizo. Bloquea la línea de visión pero no el movimiento. Una criatura queda cegada mientras esté en el espacio del muro y debe gastar 3 pies de movimiento por cada 1 pie que se mueva allí.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 3', '90 pies', 'Mago', 'Evocacion'),
(226, 'Muro de agua (Wall of Water)', 'Conjuras un muro de agua en el suelo en un punto que puedas ver dentro de tu alcance. Puedes hacer el muro de hasta 30 pies de largo, 10 pies de alto y 1 pie de grosor, o puedes hacer un muro anillado de hasta 20 pies de diámetro, 20 pies de alto y 1 pie de grosor. El muro desaparece cuando finaliza el hechizo. El espacio del muro es terreno difícil.Cualquier ataque con arma a distancia que entre en el espacio del muro tiene desventaja en la tirada de ataque, y el daño de fuego se reduce a la mitad si el efecto de fuego atraviesa el muro para alcanzar a su objetivo. Los hechizos que infligen daño de frío y atraviesan la muralla provocan que el área de la muralla que atraviesan se congele (se congela al menos una sección de 5 pies cuadrados). Cada sección congelada de 5 pies cuadrados tiene CA 5 y 15 puntos de golpe. Reducir una sección congelada a 0 puntos de vida la destruye. Cuando se destruye una sección, el agua del muro no la llena.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 3', '60 pies', 'Druida, Hechicero, Mago', 'Evocacion'),
(227, 'Respirar bajo el agua (Water Breathing)', 'Este hechizo otorga a un máximo de diez criaturas dispuestas dentro del alcance y que puedas ver, la capacidad de respirar bajo el agua hasta el final de su duración. Las criaturas afectadas también conservan su patrón de respiración normal.', '24 horas', 'no', '1 acción', 'Nivel 3', '30 pies', 'Druida, Explorador, Lanzador de Rituales, Hechicero, Mago', 'Transmutacion'),
(228, 'Caminar sobre el agua (Water Walk)', 'Este hechizo otorga la capacidad de moverse por cualquier superficie líquida -como agua, ácido, barro, nieve, arenas movedizas o lava- como si fuera tierra firme inofensiva (las criaturas que atraviesen lava fundida pueden sufrir daño por el calor). Hasta diez criaturas voluntarias que puedas ver dentro del alcance obtienen esta habilidad mientras dure el efecto.Si tu objetivo es una criatura sumergida en un líquido, el conjuro lleva al objetivo a la superficie del líquido a una velocidad de 60 pies por asalto.', '1 hora', 'no', '1 acción', 'Nivel 3', '30 pies', 'Clerigo, Druida, Explorador, Lanzador de Rituales, Hechicero', 'Transmutacion'),
(229, 'Muro de viento (Wind Wall)', 'Un muro de fuerte viento se eleva desde el suelo en un punto que elijas dentro del alcance. Puedes crear un muro de hasta 15 metros de largo, 15 metros de alto y 30 cm de grosor. Puedes dar al muro la forma que quieras, siempre que siga una trayectoria continua a lo largo del suelo. El muro dura lo que dura.Cuando aparece el muro, cada criatura dentro de su área debe hacer una tirada de salvación de fuerza. Una criatura recibe 3d8 puntos de daño contundente si falla la tirada de salvación, o la mitad de daño si tiene éxito.El fuerte viento mantiene a raya la niebla, el humo y otros gases. Las criaturas u objetos voladores pequeños o de menor tamaño no pueden atravesar el muro. Los materiales sueltos y ligeros introducidos en el muro vuelan hacia arriba. Las flechas, virotes y otros proyectiles ordinarios lanzados contra objetivos situados detrás de la muralla son desviados hacia arriba y fallan automáticamente. (Las rocas lanzadas por gigantes o máquinas de asedio, y proyectiles similares, no se ven afectados). Las criaturas en estado gaseoso no pueden atravesarlo.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 3', '120 pies', 'Clerigo, Druida, Explorador', 'Evocacion'),
(230, 'Ojo arcano (Arcane Eye)', 'Creas un ojo mágico invisible dentro de tu alcance que flota en el aire mientras dura el efecto.Recibes mentalmente información visual del ojo, que tiene visión normal y visión en la oscuridad hasta 9 metros. El ojo puede mirar en todas direcciones.Como acción, puedes mover el ojo hasta 9 metros en cualquier dirección. No hay límite a la distancia que el ojo puede alejarse de ti, pero no puede entrar en otro plano de existencia. Una barrera sólida bloquea el movimiento del ojo, pero éste puede atravesar una abertura de tan sólo 2,5 cm de diámetro.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 4', '30 pies', 'Mago, Lanzador de Rituales', 'Adivinacion'),
(231, 'Aura de vida (Aura of Life)', 'Una energía que preserva la vida irradia de ti en un aura con un radio de 30 pies. Hasta que el hechizo termina, el aura se mueve contigo, centrada en ti. Cada criatura no hostil en el aura (incluyéndote a ti) tiene resistencia al daño necrótico, y su máximo de puntos de golpe no puede reducirse. Además, una criatura viva no hostil recupera 1 punto de golpe cuando comienza su turno en el aura con 0 puntos de golpe.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 4', 'Personal', 'Paladín, Paladin', 'Abjuracion'),
(232, 'Aura de pureza (Aura of Purity)', 'La energía purificadora irradia de ti en un aura con un radio de 30 pies. Hasta que el hechizo termine, el aura se mueve contigo, centrada en ti. Cada criatura no hostil en el aura (incluyéndote a ti) no puede enfermar, tiene resistencia al daño por veneno y tiene ventaja en las tiradas de salvación contra efectos que causen cualquiera de las siguientes condiciones: cegado, encantado, ensordecido, asustado, paralizado, envenenado y aturdido.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 4', 'Personal', 'Paladín, Paladin', 'Abjuracion'),
(233, 'Destierro (Banishment)', 'Intentas enviar a otro plano de existencia a una criatura que puedas ver dentro de tu alcance. El objetivo debe tener éxito en una tirada de salvación de Carisma o ser desterrado.Si el objetivo es nativo del plano de existencia en el que te encuentras, lo destierras a un semiplano inofensivo. Mientras está allí, el objetivo queda incapacitado. El objetivo permanece allí hasta que el hechizo finaliza, momento en el que el objetivo reaparece en el espacio que dejó o en el espacio desocupado más cercano si ese espacio está ocupado.Si el objetivo es nativo de un plano de existencia distinto de aquel en el que te encuentras, el objetivo es desterrado con un débil ruido de estallido, volviendo a su plano de origen. Si el hechizo termina antes de 1 minuto, el objetivo reaparece en el espacio que dejó o en el espacio desocupado más cercano si ese espacio está ocupado. De lo contrario, el objetivo no regresa.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '60 pies', 'Clérigo, Clerigo, Hechicero, Mago, Paladín, Paladin, Brujo, Lanzador de Rituales', 'Abjuracion'),
(234, 'Plaga (Blight)', 'La energía nigromántica inunda a una criatura de tu elección que puedas ver dentro de tu alcance, drenándole humedad y vitalidad. El objetivo debe realizar una tirada de salvación de Constitución. Si falla la tirada de salvación, el objetivo recibe 8d8 puntos de daño necrótico, o la mitad si tiene éxito. El hechizo no tiene efecto sobre muertos vivientes o constructos.Si tu objetivo es una criatura vegetal o una planta mágica, realiza la tirada de salvación con desventaja y el hechizo le inflige el máximo daño.Si tu objetivo es una planta no mágica que no es una criatura, como un árbol o un arbusto, no hace tirada de salvación; simplemente se marchita y muere.', 'Instantaneo', 'no', '1 acción', 'Nivel 4', '30 pies', 'Druida, Hechicero, Mago, Brujo, Lanzador de Rituales', 'Nigromancia'),
(235, 'Compulsión (Compulsion)', 'Las criaturas de tu elección que puedas ver dentro de tu alcance y que puedan oírte deben hacer una tirada de salvación de sabiduría. Un objetivo tiene éxito automáticamente en esta tirada de salvación si no puede ser encantado. Si falla la tirada de salvación, el objetivo queda afectado por este hechizo. Hasta que el hechizo termine, puedes usar una acción de bonificación en cada uno de tus turnos para designar una dirección que sea horizontal a ti. Cada objetivo afectado debe utilizar la mayor parte posible de su movimiento para moverse en esa dirección en su siguiente turno. Puede realizar cualquier acción antes de moverse. Tras moverse de este modo, puede realizar otra salvación de Sabiduría para intentar poner fin al efecto.Un objetivo no está obligado a moverse hacia un peligro mortal evidente, como un fuego o un pozo, pero provocará ataques de oportunidad para moverse en la dirección designada.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '30 pies', 'Bardo', 'Encantamiento'),
(236, 'Confusión (Confusion)', 'Este conjuro asalta y distorsiona las mentes de las criaturas, generando ilusiones y provocando acciones incontroladas. Cada criatura en una esfera de 10 pies de radio centrada en un punto elegido en el alcance del hechizo debe hacer una tirada de salvación de sabiduría, de lo contrario se verá afectada por el hechizo.Un objetivo afectado puede reaccionar y debe comenzar al principio de 1d10 cada una de sus rondas de juego para determinar su comportamiento para esa ronda.Al final de cada turno, una criatura afectada puede hacer una tirada de salvación de Sabiduría. Si tiene éxito, el efecto del hechizo termina para este objetivo.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '90 pies', 'Bardo, Druida, Hechicero, Mago, Lanzador de Rituales', 'Encantamiento'),
(237, 'Invocar elementales menores (Conjure Minor Elementals)', 'Invocas elementales que aparecen en espacios desocupados que puedes ver dentro de tu alcance. Eliges una de las siguientes opciones para lo que aparezca:- Un elemental de nivel de desafío 2 o inferior- Dos elementales de dificultad 1 o inferior- Cuatro elementales de dificultad 1/2 o inferior- Ocho elementales de dificultad 1/4 o inferior.Un elemental invocado por este hechizo desaparece cuando cae a 0 puntos de vida o cuando el hechizo termina.Las criaturas invocadas son amistosas contigo y tus compañeros. Tira iniciativa para las criaturas invocadas como grupo, que tiene sus propios turnos. Obedecen cualquier orden verbal que les des (no requieren ninguna acción por tu parte). Si no les das ninguna orden, se defienden de las criaturas hostiles, pero por lo demás no realizan ninguna acción.El DM tiene las estadísticas de las criaturas.', 'Hasta 1 hora', 'si', '1 minuto', 'Nivel 4', '90 pies', 'Druida, Mago, Lanzador de Rituales', 'Conjuracion'),
(238, 'Invocar seres del bosque (Conjure Woodland Beings)', 'Invocas criaturas feéricas que aparecen en espacios desocupados que puedes ver dentro de tu alcance. Elige una de las siguientes opciones para lo que aparezca:- Una criatura feérica de nivel de desafío 2 o inferior.- Dos criaturas feéricas de nivel de desafío 1 o inferior- Cuatro criaturas feéricas de nivel de desafío 1/2 o inferior- Ocho criaturas feéricas de nivel de desafío 1/4 o inferiorUna criatura invocada desaparece cuando baja a 0 puntos de vida o cuando termina el hechizo.Las criaturas invocadas son amistosas contigo y tus compañeros. Tira iniciativa por las criaturas invocadas como grupo, que tienen sus propios turnos. Obedecen cualquier orden verbal que les des (no requieren ninguna acción por tu parte). Si no les das ninguna orden, se defienden de las criaturas hostiles, pero por lo demás no realizan ninguna acción.El DM tiene las estadísticas de las criaturas.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 4', '60 pies', 'Druida', 'Conjuracion'),
(239, 'Controlar agua (Control Water)', 'Hasta que el hechizo termine, controlas cualquier agua libre dentro de un área que elijas que sea un cubo de hasta 100 pies de lado. Puedes elegir entre cualquiera de los siguientes efectos cuando lances este hechizo. Como acción en tu turno, puedes repetir el mismo efecto o elegir uno diferente.<b>Inundación.</b> Haces que el nivel de todas las aguas estancadas de la zona aumente hasta 6 metros. Si el área incluye una orilla, el agua de la inundación se derrama sobre tierra firme.En su lugar, creas una ola de 6 metros de altura que viaja de un lado a otro de la zona y luego se desploma. Los vehículos grandes o pequeños que se encuentren en la trayectoria de la ola son arrastrados por ella hacia el otro lado. Los vehículos enormes o más pequeños golpeados por la ola tienen un 25% de probabilidades de volcar.El nivel del agua permanece elevado hasta que finaliza el hechizo o hasta que eliges un efecto diferente. Si este efecto produjo una ola, ésta se repite al inicio de tu siguiente turno mientras dure el efecto de inundación.<b>Parte el Agua.</b> Haces que el agua de la zona se separe y cree una zanja. La zanja se extiende por el área del hechizo y el agua separada forma un muro a cada lado. La zanja permanece hasta que finaliza el hechizo o eliges un efecto diferente. A continuación, el agua se llena lentamente en la zanja en el transcurso de la siguiente ronda hasta que se restablece el nivel normal del agua.<b>Redirigir flujo.</b> Haces que el agua que fluye en el área se mueva en la dirección que elijas, incluso si el agua tiene que fluir por encima de obstáculos, muros o en otras direcciones poco probables. El agua del área se mueve en la dirección que le indiques, pero una vez que sale del área del hechizo, reanuda su flujo en función de las condiciones del terreno. El agua sigue moviéndose en la dirección que elegiste hasta que el hechizo termina o eliges un efecto diferente.<b>Remolino.</b> Este efecto requiere una masa de agua de al menos 50 pies cuadrados y 25 pies de profundidad. Haces que se forme un remolino en el centro del área. El remolino forma un vórtice de 5 pies de ancho en la base, hasta 50 pies de ancho en la parte superior y 25 pies de alto. Cualquier criatura u objeto que se encuentre en el agua y a menos de 25 pies del vórtice es arrastrado 10 pies hacia él. Una criatura puede nadar lejos del vórtice haciendo un chequeo de Fuerza (Atletismo) contra su DC de salvación de hechizo.Cuando una criatura entra en el vórtice por primera vez en un turno o comienza su turno allí, debe hacer una tirada de salvación de Fuerza. Si falla, la criatura recibe 2d8 puntos de daño contundente y queda atrapada en el vórtice hasta que finalice el hechizo. Si la salvación tiene éxito, la criatura recibe la mitad de daño y no queda atrapada en el vórtice. Una criatura atrapada en el vórtice puede utilizar su acción para intentar alejarse nadando del vórtice como se describe más arriba, pero tiene desventaja en el chequeo de Fuerza (Atletismo) para hacerlo.La primera vez en cada turno que un objeto entra en el vórtice, el objeto recibe 2d8 puntos de daño contundente; este daño se produce cada ronda que permanece en el vórtice.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 4', '300 pies', 'Clérigo, Clerigo, Druida, Mago, Lanzador de Rituales', 'Transmutacion'),
(240, 'Protección contra la muerte (Death Ward)', 'Tocas a una criatura y le concedes cierta protección contra la muerte.La primera vez que el objetivo caiga a 0 puntos de vida como resultado de recibir daño, el objetivo cae a 1 punto de vida, y el hechizo termina.Si el hechizo sigue vigente cuando el objetivo sufre un efecto que lo mataría instantáneamente sin infligirle daño, dicho efecto se anula contra el objetivo y el hechizo finaliza.', '8 horas', 'no', '1 acción', 'Nivel 4', 'Toque', 'Clérigo, Clerigo, Paladín, Paladin', 'Abjuracion'),
(241, 'Puerta dimensional (Dimension Door)', 'Te teletransportas desde tu ubicación actual a cualquier otro punto dentro de tu alcance. Llegas exactamente al lugar deseado. Puede ser un lugar que puedas ver, uno que puedas visualizar o uno que puedas describir indicando la distancia y la dirección, como \"200 pies en línea recta hacia abajo\" o \"hacia el noroeste en un ángulo de 45 grados, 300 pies\".Puedes llevar objetos siempre que su peso no exceda de lo que puedes cargar. También puedes traer una criatura dispuesta de tu tamaño o menor que lleve equipo hasta su capacidad de carga. La criatura debe estar a menos de 5 pies de ti cuando lances este hechizo.Si llegaras a un lugar ya ocupado por un objeto o una criatura, tú y cualquier criatura que viaje contigo recibís cada uno 4d6 puntos de daño de fuerza, y el hechizo falla al teletransportarte.', 'Instantaneo', 'no', '1 acción', 'Nivel 4', '500 pies', 'Bardo, Clerigo, Paladin, Hechicero, Brujo, Mago', 'Conjuracion'),
(242, 'Adivinación (Adivinacion)', 'Tu magia y una ofrenda te ponen en contacto con un dios o sus servidores. Haces una única pregunta relativa a un objetivo, acontecimiento o actividad específica que tendrá lugar en un plazo de 7 días. El DM ofrece una respuesta sincera. La respuesta puede ser una frase corta, una rima críptica o un presagio.El hechizo no tiene en cuenta ninguna circunstancia posible que pueda cambiar el resultado, como el lanzamiento de hechizos adicionales o la pérdida o ganancia de un compañero.Si lanzas el hechizo dos o más veces antes de terminar tu siguiente descanso largo, hay una probabilidad acumulativa del 25% por cada lanzamiento después del primero de que obtengas una lectura aleatoria. El DM hace esta tirada en secreto.', 'Instantaneo', 'no', '1 acción', 'Nivel 4', 'Personal', 'Clerigo, Druida, Lanzador de Rituales', 'Adivinacion'),
(243, 'Dominar bestia (Dominate Beast)', 'Intentas hechizar a una criatura que veas dentro de tu alcance. Debe tener éxito en una tirada de salvación de sabiduría o quedará hechizada por ti mientras dure el hechizo. Si tú o criaturas amigas tuyas estáis luchando contra ella, tiene ventaja en la tirada de salvación.Mientras la criatura esté encantada, tienes un vínculo telepático con ella mientras estéis en el mismo plano de existencia. Puedes utilizar este vínculo telepático para dar órdenes a la criatura mientras estás consciente (no requiere acción), que hará todo lo posible por obedecer. Puedes especificar un curso de acción simple y general, como \"Ataca a esa criatura\", \"Corre hacia allí\" o \"Busca ese objeto\". Si la criatura cumple la orden y no recibe más indicaciones tuyas, se defiende y se preserva lo mejor que puede.Puedes utilizar tu acción para tomar el control total y preciso del objetivo. Hasta el final de tu siguiente turno, la criatura sólo realiza las acciones que tú elijas y no hace nada que tú no le permitas hacer. Durante este tiempo, también puedes hacer que la criatura utilice una reacción, pero esto requiere que utilices también tu propia reacción. Cada vez que el objetivo recibe daño, realiza una nueva tirada de salvación contra el hechizo. Si la tirada de salvación tiene éxito, el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '60 pies', 'Druida, Explorador', 'Encantamiento'),
(244, 'Ruina elemental (Elemental Bane)', 'Elige una criatura que puedas ver dentro del alcance y elige uno de los siguientes tipos de daño: ácido, frío, fuego, relámpago o trueno. El objetivo debe tener éxito en una tirada de salvación de Constitución o se verá afectado por el hechizo durante su duración. La primera vez en cada turno que el objetivo afectado reciba daño del tipo elegido, el objetivo recibe 2d6 puntos de daño adicionales de ese tipo. Además, el objetivo pierde cualquier resistencia a ese tipo de daño hasta que finalice el hechizo.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '90 pies', 'Druida, Brujo, Mago', 'Transmutacion'),
(245, 'Tentáculos negros de Evard (Evard\'s Black Tentacles)', 'Oscuros tentáculos retorcidos ocupan el suelo en un cuadrado de 90 pies cresta se puede ver el alcance del hechizo. Durante la duración del hechizo, los tentáculos convierten el terreno en difícil.Cuando una criatura entra en el área afectada por primera vez en un turno o donde comienza su turno, debe hacer una tirada de salvación de destreza o sufre 3d6 puntos de daño contundente y queda obstaculizada por los tentáculos hasta el final del hechizo. Una criatura que comience su turno en la zona y ya esté obstaculizada por los tentáculos sufre 3d6 puntos de daño contundente.Una criatura obstaculizada por los tentáculos puede usar su acción para realizar una prueba de Fuerza o Destreza (a su elección) opuesta al respaldo SD de su destino. Si tiene éxito, queda libre.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '90 pies', 'Brujo, Mago', 'Conjuracion'),
(246, 'Fabricar (Fabricate)', 'Conviertes materias primas en productos del mismo material. Por ejemplo, puedes fabricar un puente de madera a partir de un grupo de árboles, una cuerda a partir de una parcela de cáñamo y ropa a partir de lino o lana.Elige materias primas que puedas ver a tu alcance. Puedes fabricar un objeto Grande o más pequeño (contenido en un cubo de 10 pies, u ocho cubos de 5 pies conectados), dada una cantidad suficiente de materia prima. Sin embargo, si trabajas con metal, piedra u otra sustancia mineral, el objeto fabricado no puede ser mayor que Mediano (contenido en un solo cubo de 5 pies). La calidad de los objetos fabricados por el hechizo es proporcional a la calidad de las materias primas.Criaturas u objetos mágicos no pueden ser creados o transmutados por este hechizo. Tampoco puedes utilizarlo para crear objetos que normalmente requieren un alto grado de artesanía, como joyas, armas, cristal o armaduras, a menos que domines el tipo de herramientas artesanales utilizadas para fabricar tales objetos.', 'Instantaneo', 'no', '10 minutos', 'Nivel 4', '120 pies', 'Mago', 'Transmutacion'),
(247, 'Escudo de fuego (Fire Shield)', 'Una llama fina y vaporosa rodea tu cuerpo mientras dure el conjuro, irradiando una luz brillante en un radio de 3 metros y una luz tenue en un radio adicional de 3 metros. Puedes terminar el conjuro usando una acción para hacerlo desaparecer.Las llamas te rodean un escudo de calor o frío, a tu elección. El escudo térmico te proporciona resistencia al daño por frío y el frío al daño por fuego.Además, cada vez que una criatura a menos de 1,5 m de ti te golpea con un ataque cuerpo a cuerpo, del escudo brotan llamas. El atacante sufre entonces 2d8 puntos de daño de fuego o frío, dependiendo del modelo. ', '10 minutos', 'no', '1 acción', 'Nivel 4', 'Personal', 'Brujo, Mago', 'Evocacion'),
(248, 'Libertad de movimiento (Freedom of Movement)', 'Tocas a una criatura dispuesta. Mientras dure, el movimiento del objetivo no se ve afectado por terreno difícil, y los conjuros y otros efectos mágicos no pueden reducir la velocidad del objetivo ni hacer que quede paralizado o sujeto.El objetivo también puede gastar 5 pies de movimiento para escapar automáticamente de ataduras no mágicas, como grilletes o una criatura que lo tenga agarrado. Por último, estar bajo el agua no impone penalizaciones al movimiento ni a los ataques del objetivo.', '1 hora', 'no', '1 acción', 'Nivel 4', 'Toque', 'Bardo, Clerigo, Druida, Paladin, Explorador', 'Abjuracion'),
(249, 'Insecto gigante (Giant Insect)', 'Transformas hasta diez ciempiés, tres arañas, cinco avispas o un escorpión dentro del alcance en versiones gigantes de sus formas naturales mientras dure el efecto. Un ciempiés se convierte en un ciempiés gigante, una araña en una araña gigante, una avispa en una avispa gigante y un escorpión en un escorpión gigante.Cada criatura obedece tus órdenes verbales y, en combate, actúan en tu turno cada asalto. El DM dispone de las estadísticas de estas criaturas y resuelve sus acciones y movimientos.Una criatura permanece en su tamaño gigante mientras dure, hasta que caiga a 0 puntos de golpe, o hasta que uses una acción para descartar el efecto sobre ella.El DM puede permitirte elegir diferentes objetivos. Por ejemplo, si transformas una abeja, su versión gigante podría tener las mismas estadísticas que una avispa gigante.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 4', '30 pies', 'Druida', 'Transmutacion'),
(250, 'Vid apresadora (Grasping Vine)', 'Conjuras una enredadera que brota del suelo en un espacio desocupado de tu elección que puedas ver dentro de tu alcance. Cuando lanzas este conjuro, puedes hacer que la enredadera ataque a una criatura que veas en un radio de 30 pies. Esa criatura debe tener éxito en una tirada de salvación de destreza o ser arrastrada 6 metros directamente hacia la enredadera. Hasta que el hechizo termine, puedes hacer que la enredadera ataque a la misma criatura o a otra como acción adicional en cada uno de tus turnos.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 4', '30 pies', 'Clerigo, Druida, Explorador', 'Conjuracion'),
(251, 'Invisibilidad mayor (Greater Invisibility)', 'Tú o una criatura que toques os volvéis invisibles hasta que termina el hechizo. Todo lo que el objetivo lleve puesto es invisible mientras lo lleve encima.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', 'Toque', 'Bardo, Druida, Hechicero, Brujo, Mago', 'Ilusion'),
(252, 'Guardián de la fe (Guardian of Faith)', 'Aparece un Gran guardián espectral y planea durante el tiempo que dure el hechizo en un espacio desocupado de tu elección que puedas ver dentro de tu alcance. El guardián ocupa ese espacio y es indistinto salvo por una espada y un escudo relucientes con el símbolo de tu deidad.Cualquier criatura hostil a ti que se mueva a un espacio en un radio de 10 pies del guardián por primera vez en un turno debe tener éxito en una tirada de salvación de destreza. La criatura recibe 20 puntos de daño radiante si falla la tirada de salvación, o la mitad si tiene éxito. El guardián desaparece cuando ha infligido un total de 60 puntos de daño.', '8 horas', 'no', '1 acción', 'Nivel 4', '30 pies', 'Clerigo, Paladin', 'Conjuracion'),
(253, 'Terreno ilusorio (Hallucinatory Terrain)', 'Las características táctiles del terreno no cambian, por lo que es probable que las criaturas que entren en la zona vean a través de la ilusión. Si la diferencia no es obvia al tacto, una criatura que examine cuidadosamente la ilusión puede intentar un chequeo de Inteligencia (Investigación) contra tu DC de salvación de conjuro para no creerla. Una criatura que discierne la ilusión por lo que es, la ve como una vaga imagen superpuesta sobre el terreno.', '24 horas', 'no', '10 minutos', 'Nivel 4', '300 pies', 'Bardo, Druida, Brujo, Mago', 'Ilusion'),
(254, 'Tormenta de hielo (Ice Storm)', 'Una lluvia de hielo duro como una roca golpea el suelo en un cilindro de 20 pies de radio y 40 pies de altura centrado en un punto dentro del alcance. Cada criatura del cilindro debe realizar una tirada de salvación de destreza. Una criatura recibe 2d8 puntos de daño contundente y 4d6 puntos de daño por frío si falla la tirada de salvación, o la mitad de daño si tiene éxito.Las piedras de granizo convierten el área de efecto de la tormenta en terreno difícil hasta el final de tu siguiente turno.', 'Instantaneo', 'no', '1 acción', 'Nivel 4', '300 pies', 'Clerigo, Druida, Paladin, Hechicero, Mago', 'Evocacion'),
(255, 'Cofre secreto de Leomund (Leomund\'s Secret Chest)', 'Escondes un cofre, y todo su contenido, en el Plano Etéreo. Debes tocar el cofre y la réplica en miniatura que sirve como componente material para el hechizo. El cofre puede contener hasta 12 pies cúbicos de material no viviente (3 pies por 2 pies por 2 pies).Mientras el cofre permanece en el Plano Etéreo, puedes usar una acción y tocar la réplica para recuperar el cofre. Aparece en un espacio desocupado en el suelo a menos de 5 pies de ti. Puedes devolver el cofre al Plano Etéreo utilizando una acción y tocando tanto el cofre como la réplica.Después de 60 días, hay una probabilidad acumulativa del 5% por día de que el efecto del hechizo termine. Este efecto termina si lanzas este hechizo de nuevo, si el cofre réplica más pequeño es destruido, o si eliges terminar el hechizo como una acción. Si el hechizo termina y el cofre más grande está en el Plano Etéreo, se pierde irremediablemente.', 'Instantaneo', 'no', '1 acción', 'Nivel 4', 'Toque', 'Mago', 'Conjuracion'),
(256, 'Localizar criatura (Locate Creature)', 'Describe o nombra una criatura que te resulte familiar. Percibes la dirección en la que se encuentra la criatura, siempre que esté a menos de 1.000 pies de ti. Si la criatura se está moviendo, conoces la dirección de su movimiento.El conjuro puede localizar a una criatura específica conocida por ti, o a la criatura más cercana de un tipo específico (como un humano o un unicornio), siempre que hayas visto a dicha criatura de cerca -en un radio de 30 pies- al menos una vez. Si la criatura que has descrito o nombrado tiene una forma diferente, como estar bajo los efectos de un conjuro de polimorfia, este conjuro no localiza a la criatura.Este hechizo no puede localizar a una criatura si el agua corriente de al menos 10 pies de ancho bloquea un camino directo entre tú y la criatura.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 4', 'Personal', 'Bardo, Clerigo, Druida, Paladin, Explorador, Mago', 'Adivinacion'),
(257, 'Sabueso fiel de Mordenkainen (Mordenkainen\'s Faithful Hound)', 'Creas un plano de fuerza en forma de espada que flota dentro de tu alcance. Dura lo que dura.Cuando la espada aparece, realizas un ataque de conjuro cuerpo a cuerpo contra un objetivo de tu elección a menos de 1,5 m de la espada. Si aciertas, el objetivo recibe 3d10 puntos de daño de fuerza. Hasta que el hechizo termine, puedes usar una acción de bonificación en cada uno de tus turnos para mover la espada hasta 20 pies a un punto que puedas ver y repetir este ataque contra el mismo objetivo o uno diferente.', '8 horas', 'no', '1 acción', 'Nivel 4', '30 pies', 'Mago', 'Conjuracion'),
(258, 'Santuario privado de Mordenkainen (Mordenkainen\'s Private Sanctum)', 'Haces que un área dentro de tu alcance sea mágicamente segura. El área es un cubo que puede tener desde 5 pies hasta 100 pies de lado. El hechizo dura lo que dure o hasta que uses una acción para rechazarlo.hasta que uses una acción para desecharlo. Cuando lanzas el hechizo, decides qué tipo de seguridad proporciona el hechizo, eligiendo alguna o todas las propiedades siguientes:- El sonido no puede atravesar la barrera en el borde del área protegida.- La barrera del área protegida aparece oscura y brumosa, impidiendo la visión (incluida la visión oscura) a través de ella.- Los sensores creados por conjuros de adivinación no pueden aparecer dentro del área protegida ni atravesar la barrera de su perímetro.- Las criaturas de la zona no pueden ser objetivo de conjuros de adivinación.- Nada puede teletransportarse dentro o fuera del área protegida.- El viaje planar está bloqueado dentro del área protegida.Si lanzas este hechizo en el mismo lugar todos los días durante un año, el efecto será permanente.', '24 horas', 'no', '10 minutos', 'Nivel 4', '120 pies', 'Mago', 'Abjuracion'),
(259, 'Esfera resiliente de Otiluke (Otiluke\'s Resilient Sphere)', 'Una esfera de fuerza resplandeciente envuelve a una criatura u objeto de tamaño Large o inferior dentro de su alcance. Una criatura que no lo desee debe realizar una tirada de salvación de destreza. Si falla, la criatura queda encerrada mientras dure el hechizo.Nada -ni objetos físicos, energía u otros efectos de conjuro- puede atravesar la barrera, ni dentro ni fuera, aunque una criatura dentro de la esfera puede respirar en ella. La esfera es inmune a todo daño, y una criatura u objeto en su interior no puede ser dañado por ataques o efectos originados en el exterior, ni una criatura dentro de la esfera puede dañar nada fuera de ella.La esfera es ingrávida y lo suficientemente grande como para contener a la criatura u objeto en su interior. Una criatura encerrada puede usar su acción para empujar contra las paredes de la esfera y así hacer rodar la esfera hasta la mitad de la velocidad de la criatura. Del mismo modo, la esfera puede ser recogida y movida por otras criaturas.Un hechizo de desintegración dirigido a la esfera la destruye sin dañar nada de lo que contiene.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '30 pies', 'Mago, Lanzador de Rituales', 'Evocacion'),
(260, 'Asesino fantasmal (Phantasmal Killer)', 'Aprovechas las pesadillas de una criatura que puedas ver dentro de tu alcance y creas una manifestación ilusoria de sus miedos más profundos, visible sólo para esa criatura. El objetivo debe realizar una tirada de salvación de sabiduría. Si falla la tirada de salvación, el objetivo queda asustado mientras dure el efecto. Al comienzo de cada turno del objetivo antes de que el hechizo termine, el objetivo debe tener éxito en una tirada de salvación de sabiduría o recibir 4 d10 de daño psíquico. Si tiene éxito, el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '120 pies', 'Mago', 'Ilusion');
INSERT INTO `conjuros` (`id_spell`, `name`, `descr`, `duracion`, `concentracion`, `casteo`, `level`, `rango`, `clases`, `escuela`) VALUES
(261, 'Polimorfar (Polymorph)', 'Este hechizo transforma a una criatura que puedas ver dentro de su alcance en una nueva forma. Una criatura que no lo desee debe realizar una tirada de salvación de sabiduría para evitar el efecto. Un cambiaformas tiene éxito automáticamente en esta tirada de salvación.La transformación dura lo que dure, o hasta que el objetivo pierda 0 puntos de vida o muera. La nueva forma puede ser cualquier bestia cuyo índice de desafío sea igual o menor que el del objetivo (o el nivel del objetivo, si no tiene índice de desafío). Las estadísticas de juego del objetivo, incluidas las puntuaciones de habilidad mental, se sustituyen por las estadísticas de la bestia elegida. Conserva su alineamiento y personalidad.El objetivo asume los puntos de vida de su nueva forma. Cuando vuelve a su forma normal, la criatura recupera el número de puntos de golpe que tenía antes de transformarse. Si revierte como resultado de una caída a 0 puntos de golpe, cualquier exceso de daño se traslada a su forma normal. Mientras el exceso de daño no reduzca la forma normal de la criatura a 0 puntos de vida, no queda inconsciente.La criatura está limitada en las acciones que puede realizar por la naturaleza de su nueva forma, y no puede hablar, lanzar hechizos ni realizar ninguna otra acción que requiera las manos o el habla.El equipo del objetivo se funde con la nueva forma. La criatura no puede activar, utilizar, blandir ni beneficiarse de ninguna otra forma de su equipo.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 4', '60 pies', 'Bardo, Clerigo, Druida, Hechicero, Mago', 'Transmutacion'),
(262, 'Golpe aturdidor (Staggering Smite)', 'La próxima vez que golpees a una criatura con un ataque de arma cuerpo a cuerpo durante la duración de este hechizo, tu arma atraviesa tanto el cuerpo como la mente, y el ataque inflige 4d6 puntos de daño psíquico adicionales al objetivo. El objetivo debe realizar una tirada de salvación de sabiduría. Si falla, tiene desventaja en las tiradas de ataque y en los chequeos de habilidad, y no puede reaccionar hasta el final de su siguiente turno.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 4', 'Personal', 'Paladin', 'Evocacion'),
(263, 'Moldear piedra (Stone Shape)', 'Tocas un objeto de piedra de tamaño mediano o inferior o una sección de piedra de no más de 1,5 m de cualquier dimensión y le das la forma que te convenga. Así, por ejemplo, puedes convertir una roca grande en un arma, un ídolo o un cofre, o hacer un pequeño pasadizo a través de un muro, siempre que éste tenga menos de 1,5 m de grosor. También puedes dar forma a una puerta de piedra o a su marco para cerrarla herméticamente. El objeto que crees puede tener hasta dos bisagras y un pestillo, pero no es posible dar detalles mecánicos más finos.', 'Instantaneo', 'no', '1 acción', 'Nivel 4', 'Toque', 'Clerigo, Druida, Mago', 'Transmutacion'),
(264, 'Piel de piedra (Stoneskin)', 'Este hechizo hace que la carne de una criatura que toques se vuelva dura como la piedra. Hasta que el hechizo termine, el objetivo tiene resistencia al daño no mágico contundente, perforante y cortante.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 4', 'Toque', 'Clerigo, Druida, Paladin, Explorador, Hechicero, Mago', 'Abjuracion'),
(265, 'Esfera de tormenta (Storm Sphere)', 'Una esfera de aire arremolinado de 20 pies de radio surge centrada en un punto que elijas dentro del alcance. La esfera permanece mientras dura el hechizo. Cada criatura en la esfera cuando aparece o que termina su turno allí debe tener éxito en una tirada de salvación de Fuerza o recibir 2d6 puntos de daño contundente. El espacio de la esfera es terreno difícil.Hasta que el conjuro termine, puedes usar una acción de bonificación en cada uno de tus turnos para hacer que un rayo salte desde el centro de la esfera hacia una criatura que elijas en un radio de 60 pies del centro. Haz un ataque de hechizo a distancia. Tienes ventaja en la tirada de ataque si el objetivo está dentro de la esfera. Si aciertas, el objetivo recibe 4d6 puntos de daño por rayo.Las criaturas en un radio de 30 pies de la esfera tienen desventaja en los chequeos de Sabiduría (Percepción) realizados para escuchar.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '150 pies', 'Hechicero, Mago', 'Evocacion'),
(266, 'Esfera vitriólica (Vitriolic Sphere)', 'Apuntas a un lugar dentro del alcance, y una bola brillante de 1 pie de ácido esmeralda sale disparada hacia allí y explota en un radio de 20 pies. Cada criatura en esa área debe hacer una tirada de salvación de Destreza. Si falla la tirada de salvación, la criatura sufre 10d4 puntos de daño por ácido y 5d4 puntos de daño por ácido al final de su siguiente turno. Si la salvación tiene éxito, la criatura sufre la mitad del daño inicial y ningún daño al final de su siguiente turno.', 'Instantaneo', 'no', '1 acción', 'Nivel 4', '150 pies', 'Hechicero, Mago', 'Evocacion'),
(267, 'Muro de fuego (Wall of Fire)', 'Creas un muro de fuego en una superficie sólida dentro del alcance. Puedes crear un muro de hasta 60 pies de largo, 20 pies de alto y 1 pie de grosor, o un muro anillado de hasta 20 pies de diámetro, 20 pies de alto y 1 pie de grosor. El muro es opaco y dura lo que dura.Cuando el muro aparece, cada criatura dentro de su área debe hacer una tirada de salvación de Destreza. Si falla la tirada de salvación, la criatura recibe 5d8 puntos de daño por fuego, o la mitad de daño si la tirada de salvación tiene éxito.Un lado del muro, seleccionado por ti cuando lanzas este conjuro, inflige 5d8 puntos de daño de fuego a cada criatura que termine su turno a menos de 3 metros de ese lado o dentro del muro. Una criatura recibe el mismo daño cuando entra en el muro por primera vez en un turno o termina su turno allí. El otro lado del muro no inflige daño.El otro lado del muro no inflige daño.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '120 pies', 'Clerigo, Druida, Hechicero, Brujo, Mago', 'Evocacion'),
(268, 'Esfera acuática (Watery Sphere)', 'Conjuras una esfera de agua con un radio de 10 pies sobre un punto que puedas ver dentro del alcance. La esfera puede flotar en el aire, pero a no más de 3 metros del suelo. La esfera permanece durante la duración del hechizo.Cualquier criatura en el espacio de la esfera debe hacer una tirada de salvación de Fuerza. Si la tirada de salvación tiene éxito, la criatura es expulsada de ese espacio al espacio desocupado más cercano fuera de él. Una criatura enorme o más grande supera la tirada de salvación automáticamente. Si la salvación falla, la criatura queda atrapada por la esfera y es engullida por el agua. Al final de cada turno, el objetivo retenido puede repetir la tirada de salvación.La esfera puede contener un máximo de cuatro criaturas medianas o más pequeñas o una criatura grande. Si la esfera retiene a una criatura por encima de estos números, una criatura aleatoria que ya estaba retenida por la esfera cae fuera de ella y aterriza boca abajo en un espacio a 5 pies de ella.Como acción, puedes mover la esfera hasta 30 pies en línea recta. Si se desplaza sobre un pozo, acantilado u otro desnivel, desciende con seguridad hasta quedar suspendida a 10 pies sobre el suelo. Cualquier criatura retenida por la esfera se mueve con ella. Puedes embestir a las criaturas con la esfera, obligándolas a realizar la tirada de salvación, pero no más de una vez por turno.Cuando el hechizo termina, la esfera cae al suelo y extingue todas las llamas normales en un radio de 30 pies. Cualquier criatura inmovilizada por la esfera queda tendida en el espacio donde cae.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 4', '90 pies', 'Druida, Hechicero, Mago', 'Conjuracion'),
(269, 'Animar objetos (Animate Objects)', 'Los objetos cobran vida a tus órdenes. Elige un máximo de diez objetos no mágicos que no lleves puestos. Los objetivos medianos cuentan como dos objetos, los grandes como cuatro y los enormes como ocho. No puedes animar ningún objeto mayor que Enorme. Cada objetivo se anima y se convierte en una criatura bajo tu control hasta que el hechizo termina o hasta que se reduce a 0 puntos de golpe.Como acción de bonificación, puedes comandar mentalmente a cualquier criatura que hayas creado con este conjuro si la criatura está en un radio de 500 pies de ti (si controlas múltiples criaturas, puedes comandar a cualquiera o a todas ellas al mismo tiempo, emitiendo la misma orden a cada una). Tú decides qué acción realizará la criatura y a dónde se moverá durante su siguiente turno, o puedes dar una orden general, como vigilar una cámara o un pasillo en particular. Si no das ninguna orden, la criatura sólo se defiende de las criaturas hostiles. Una vez dada una orden, la criatura continúa cumpliéndola hasta completar su tarea.Un objeto animado es un constructo con CA, puntos de golpe, ataques, Fuerza y Destreza determinados por su tamaño. Su Constitución es 10 y su Inteligencia y Sabiduría son 3, y su Carisma es 1. Su velocidad es de 30 pies; si el objeto carece de patas u otros apéndices que pueda utilizar para locomoción, en su lugar tiene una velocidad de vuelo de 30 pies y puede flotar. Si el objeto está firmemente sujeto a una superficie o a un objeto mayor, como una cadena atornillada a una pared, su velocidad es 0. Tiene vista ciega con un radio de 30 pies y es ciego más allá de esa distancia. Cuando el objeto animado cae a 0 puntos de vida, vuelve a su forma de objeto original, y cualquier daño restante se traslada a su forma de objeto original.Si ordenas a un objeto que ataque, puede realizar un único ataque cuerpo a cuerpo contra una criatura que se encuentre a 1,5 m de él. Realiza un ataque de golpe con un bonificador de ataque y un daño contundente determinado por su tamaño. El DM puede decidir que un objeto específico inflija daño cortante o perforante en función de su forma.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 5', '120 pies', 'Bardo, Hechicero, Mago, Lanzador de Rituales', 'Transmutacion'),
(270, 'Cúpula antivida (Antilife Shell)', 'Una barrera resplandeciente se extiende desde ti en un radio de 10 pies y se mueve contigo, permaneciendo centrada en ti y protegiéndote de criaturas que no sean muertos vivientes o constructos. La barrera dura lo que dura.La barrera impide a las criaturas afectadas atravesarla. Una criatura afectada puede lanzar conjuros o realizar ataques con armas a distancia o de alcance a través de la barrera.Si te mueves de forma que una criatura afectada se vea obligada a atravesar la barrera, el hechizo termina.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 5', 'Personal', 'Druida', 'Abjuracion'),
(271, 'Despertar (Awaken)', 'Después de pasar el tiempo de lanzamiento trazando caminos mágicos dentro de una piedra preciosa, tocas a una bestia o planta enorme o más pequeña. El objetivo no debe tener puntuación de Inteligencia o debe tener una Inteligencia de 3 o menos. El objetivo obtiene una Inteligencia de 10. El objetivo también adquiere la habilidad de hablar un idioma que conozcas. Si el objetivo es una planta, gana la habilidad de mover sus extremidades, raíces, enredaderas, trepadoras, etc., y gana sentidos similares a los de un humano. Tu DM elige las estadísticas apropiadas para la planta despertada, como las estadísticas para el arbusto despertado o el árbol despertado.La bestia o planta despertada queda encantada por ti durante 30 días o hasta que tú o tus compañeros le hagáis algún daño. Cuando termina la condición de encantada, la criatura despierta elige si quiere seguir siendo amistosa contigo, basándose en cómo la trataste mientras estaba encantada.', 'Instantaneo', 'no', '8 horas', 'Nivel 5', 'Toque', 'Bardo, Druida', 'Transmutacion'),
(272, 'Golpe desterrador (Banishing Smite)', 'La próxima vez que golpees a una criatura con un ataque de arma antes de que termine este hechizo, tu arma crepita con fuerza y el ataque inflige 5d10 puntos de daño de fuerza adicionales al objetivo. Además, si este ataque reduce al objetivo a 50 puntos de golpe o menos, lo destierras. Si el objetivo es nativo de un plano de existencia distinto al tuyo, desaparece y vuelve a su plano de origen. Si el objetivo es nativo del plano en el que te encuentras, la criatura se desvanece en un semiplano inofensivo. Mientras está allí, el objetivo queda incapacitado. Permanece allí hasta que el hechizo termina, momento en el que el objetivo reaparece en el espacio que dejó o en el espacio desocupado más cercano si ese espacio está ocupado.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 5', 'Personal', 'Paladín, Paladin', 'Abjuracion'),
(273, 'Mano de Bigby (Bigby\'s Hand)', 'Creas una Gran mano de fuerza resplandeciente y translúcida en un espacio desocupado que puedas ver dentro de tu alcance. La mano dura lo que dura el conjuro y se mueve a tus órdenes, imitando los movimientos de tu propia mano.La mano es un objeto con CA 20 y puntos de vida iguales a tus puntos de vida máximos. Si se reduce a 0 puntos de vida, el hechizo finaliza. Tiene una Fuerza de 26 (+8) y una Destreza de 10 (+0). La mano no llena su espacio.Cuando lanzas el conjuro y como acción adicional en tus turnos siguientes, puedes mover la mano hasta 60 pies y causar con ella uno de los siguientes efectos.<b>Puño cerrado.</b> La mano golpea a una criatura u objeto en un radio de 5 pies. Haz un ataque de hechizo cuerpo a cuerpo para la mano utilizando tus estadísticas de juego. Si acierta, el objetivo recibe 4d8 puntos de daño de fuerza.<b>Mano Contundente.</b> La mano intenta empujar a una criatura en un radio de 5 pies en la dirección que elijas. Haz un chequeo con la Fuerza de la mano impugnada por el chequeo de Fuerza (Atletismo) del objetivo. Si el objetivo es mediano o más pequeño, tienes ventaja en el chequeo. Si tienes éxito, la mano empuja al objetivo hasta 5 pies más un número de pies igual a cinco veces tu modificador de habilidad de lanzamiento de conjuros. La mano se mueve con el objetivo para permanecer a 5 pies de él.<b>Mano que Agarra.</b> La mano intenta agarrar a una criatura Huge o más pequeña que se encuentre a 5 pies de ella. Utilizas la puntuación de Fuerza de la mano para resolver el agarre. Si el objetivo es mediano o más pequeño, tienes ventaja en el chequeo. Mientras la mano está agarrando al objetivo, puedes utilizar una acción adicional para que la mano lo aplaste. Cuando lo haces, el objetivo recibe un daño por apaleamiento igual a 2d6 + tu modificador de habilidad de lanzamiento de conjuros.<b>Mano interpuesta.</b> La mano se interpone entre tú y una criatura que elijas hasta que le des una orden diferente. La mano se mueve para permanecer entre el objetivo y tú, proporcionándote media cobertura contra el objetivo. El objetivo no puede moverse a través del espacio de la mano si su puntuación de Fuerza es menor o igual que la puntuación de Fuerza de la mano. Si su puntuación de Fuerza es mayor que la puntuación de Fuerza de la mano, el objetivo puede moverse hacia ti a través del espacio de la mano, pero ese espacio es terreno difícil para el objetivo.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 5', '120 pies', 'Mago, Lanzador de Rituales', 'Evocacion'),
(274, 'Círculo de poder (Circle of Power)', 'La energía divina irradia de ti, distorsionando y difundiendo la energía mágica en un radio de 30 pies. Hasta que el hechizo termine, la esfera se mueve contigo, centrada en ti. Mientras dure, cada criatura amiga en el área (incluyéndote a ti) tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos. Además, cuando una criatura afectada tiene éxito en una tirada de salvación contra un conjuro o efecto mágico que le permite hacer una tirada de salvación para recibir sólo la mitad del daño, no recibe ningún daño si tiene éxito en la tirada de salvación.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 5', 'Personal', 'Paladín, Paladin', 'Abjuracion'),
(275, 'Nube asesina (Cloudkill)', 'Creas una esfera de 20 pies de radio de niebla venenosa de color amarillo verdoso centrada en un punto que elijas dentro del alcance. La niebla se extiende por las esquinas. Dura lo que dura o hasta que un fuerte viento dispersa la niebla, poniendo fin al hechizo. Su área queda muy oscurecida.Cuando una criatura entra en el área del hechizo por primera vez en un turno o comienza su turno allí, esa criatura debe hacer una tirada de salvación de Constitución. La criatura recibe 5d8 puntos de daño por veneno si falla la tirada de salvación, o la mitad si tiene éxito. Las criaturas se ven afectadas aunque contengan la respiración o no necesiten respirar.La niebla se aleja 10 pies de ti al comienzo de cada uno de tus turnos, rodando por la superficie del suelo. Los vapores, al ser más pesados que el aire, se hunden hasta el nivel más bajo del terreno, llegando a derramarse por las aberturas.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 5', '120 pies', 'Hechicero, Mago, Lanzador de Rituales', 'Conjuracion'),
(276, 'Comunión (Commune)', 'Te pones en contacto con tu deidad o con un apoderado divino y le haces hasta tres preguntas que pueden responderse con un sí o un no. Debes hacer tus preguntas antes de que termine el hechizo. Recibes una respuesta correcta para cada pregunta.Los seres divinos no son necesariamente omniscientes, por lo que podrías recibir un \"no está claro\" como respuesta si una pregunta se refiere a información que está más allá del conocimiento de la deidad. En un caso en el que una respuesta de una sola palabra pudiera ser engañosa o contraria a los intereses de la deidad, el DM podría ofrecer una frase corta como respuesta en su lugar.Si lanzas el hechizo dos o más veces antes de terminar tu siguiente descanso largo, hay una probabilidad acumulativa del 25% por cada lanzamiento después del primero de que no obtengas respuesta. El DM hace esta tirada en secreto.', '1 minuto', 'no', '1 minuto', 'Nivel 5', 'Personal', 'Clérigo, Clerigo', 'Adivinacion'),
(277, 'Comunión con la naturaleza (Commune with Nature)', 'Te conviertes brevemente en uno con la naturaleza y adquieres conocimiento del territorio circundante. Al aire libre, el hechizo te permite conocer la tierra en un radio de 5 km. En cuevas y otros entornos naturales subterráneos, el radio se limita a 300 pies. El hechizo no funciona donde la naturaleza ha sido sustituida por la construcción, como en mazmorras y ciudades. Obtienes al instante conocimiento de hasta tres hechos a tu elección sobre cualquiera de los siguientes temas relacionados con la zona:- terreno y masas de agua- plantas, minerales, animales o pueblos predominantes- poderosos celestiales, fey, fiends, elementales o no muertos- influencia de otros planos de existencia- edificiosPor ejemplo, podrías determinar la ubicación de no muertos poderosos en la zona, la ubicación de las principales fuentes de agua potable y la ubicación de cualquier pueblo cercano.', 'Instantaneo', 'no', '1 minuto', 'Nivel 5', 'Personal', 'Druida, Explorador', 'Adivinacion'),
(278, 'Cono de frío (Cone of Cold)', 'Una ráfaga de aire frío sale de tus manos. Cada criatura en un cono de 18 m debe realizar una tirada de salvación de Constitución. Una criatura recibe 8d8 puntos de daño por frío si falla la tirada de salvación, o la mitad de daño si tiene éxito.Una criatura muerta por este hechizo se convierte en una estatua congelada hasta que se descongela.', 'Instantaneo', 'no', '1 acción', 'Nivel 5', 'Personal', 'Hechicero, Mago, Lanzador de Rituales', 'Evocacion'),
(279, 'Invocar elemental (Conjure Elemental)', 'Invocas a un sirviente elemental. Elige un área de aire, tierra, fuego o agua que llene un cubo de 10 pies dentro del alcance. Un elemental de nivel de desafío 5 o inferior apropiado para el área elegida aparece en un espacio desocupado en un radio de 3 metros. Por ejemplo, un elemental de fuego emerge de una hoguera y un elemental de tierra surge del suelo. El elemental desaparece cuando baja a 0 puntos de vida o cuando termina el hechizo.El elemental es amigo tuyo y de tus compañeros mientras dure el hechizo. Tira iniciativa por el elemental, que tiene sus propios turnos. Obedece cualquier orden verbal que le des (no requiere ninguna acción por tu parte). Si no le das ninguna orden, se defiende de las criaturas hostiles, pero no realiza ninguna otra acción.Si pierdes la concentración, el elemental no desaparece. En cambio, pierdes el control del elemental, se vuelve hostil hacia ti y tus compañeros, y puede atacar. Un elemental no controlado no puede ser rechazado por ti, y desaparece 1 hora después de que lo invocaras.El DM tiene las estadísticas del elemental.', 'Hasta 1 hora', 'si', '1 minuto', 'Nivel 5', '90 pies', 'Druida, Mago, Lanzador de Rituales', 'Conjuracion'),
(280, 'Invocar andanada (Conjure Volley)', 'Disparas una munición no mágica desde un arma a distancia o lanzas un arma no mágica al aire y eliges un punto dentro de su alcance. Cientos de duplicados de la munición o el arma caen en una andanada desde arriba y luego desaparecen. Cada criatura en un radio de 40 pies. 20 pies de altura centrado en ese punto debe hacer una tirada de salvación de destreza. Una criatura recibe 8d8 puntos de daño si falla la tirada de salvación, o la mitad si tiene éxito. El tipo de daño es el mismo que el de la munición o el arma.', 'Instantaneo', 'no', '1 acción', 'Nivel 5', '150 pies', 'Explorador', 'Conjuracion'),
(281, 'Contactar con otro plano (Contact Other Plane)', 'Te pones en contacto mentalmente con un semidiós, el espíritu de un sabio muerto hace mucho tiempo o alguna otra entidad misteriosa de otro plano. Contactar con esta inteligencia extraplanar puede forzar o incluso quebrar tu mente. Cuando lances este conjuro, haz una tirada de salvación de Inteligencia DC 15. Si fallas, sufres 6d. Si fallas, recibes 6d6 puntos de daño psíquico y te vuelves loco hasta que termines un descanso largo. Mientras estás loco, no puedes realizar acciones, no puedes entender lo que dicen otras criaturas, no puedes leer y sólo hablas en galimatías. Un conjuro de restauración mayor lanzado sobre ti acaba con este efecto.Con una salvación exitosa, puedes hacer hasta cinco preguntas a la entidad. Debes hacer tus preguntas antes de que el hechizo termine. El DM responde a cada pregunta con una palabra, como \"sí\", \"no\", \"tal vez\", \"nunca\", \"irrelevante\" o \"poco claro\" (si la entidad no sabe la respuesta a la pregunta). Si una respuesta de una sola palabra puede inducir a error, el DM puede ofrecer una frase corta como respuesta.', '1 minuto', 'no', '1 minuto', 'Nivel 5', 'Personal', 'Mago, Brujo, Lanzador de Rituales', 'Adivinacion'),
(282, 'Contagio (Contagion)', 'Tu toque inflige enfermedad. Haz un ataque de hechizo cuerpo a cuerpo contra una criatura a tu alcance. Si aciertas, infliges a la criatura una enfermedad a tu elección de entre las descritas a continuación.Al final de cada turno del objetivo, debe realizar una tirada de salvación de Constitución. Después de fallar tres de estas tiradas de salvación, los efectos de la enfermedad duran lo que duran, y la criatura deja de hacer estas salvaciones. Después de tener éxito en tres de estas tiradas de salvación, la criatura se recupera de la enfermedad, y el hechizo termina.Dado que este conjuro induce una enfermedad natural en su objetivo, se le aplica cualquier efecto que elimine una enfermedad o que mejore los efectos de una enfermedad.<b>Enfermedad Cegadora.</b> El dolor se apodera de la mente de la criatura y sus ojos se vuelven de un blanco lechoso. La criatura tiene desventaja en los chequeos y tiradas de salvación de sabiduría y está cegada.<b>Fiebre inmunda.</b> Una fiebre feroz recorre el cuerpo de la criatura. La criatura tiene desventaja en los chequeos de fuerza, tiradas de salvación de fuerza y tiradas de ataque que usen Fuerza.<b>Pudrición de la carne.</b> La carne de la criatura se pudre. La criatura tiene desventaja en los chequeos de Carisma y es vulnerable a todo tipo de daño.<b>Fuego mental.</b> La mente de la criatura se vuelve febril. La criatura tiene desventaja en los chequeos de inteligencia y tiradas de salvación de inteligencia, y la criatura se comporta como si estuviera bajo los efectos del hechizo confusión durante el combate.<b>Convulsión.</b> La criatura se siente abrumada por los temblores. La criatura tiene desventaja en los chequeos de destreza, tiradas de salvación de destreza y tiradas de ataque que usen Destreza.<b>Perdición viscosa.</b> La criatura comienza a sangrar sin control. La criatura tiene desventaja en los chequeos de Constitución y en las tiradas de salvación de Constitución. Además, cada vez que la criatura recibe daño, queda aturdida hasta el final de su siguiente turno.', '7 days', 'no', '1 acción', 'Nivel 5', 'Toque', 'Clérigo, Clerigo, Druida', 'Nigromancia'),
(283, 'Controlar vientos (Control Winds)', 'Tomas el control del aire en un cubo de 100 pies que puedes ver dentro del alcance. Elige uno de los siguientes efectos cuando lances el hechizo. El efecto dura lo que dura el hechizo, a menos que uses tu acción en un turno posterior para cambiar a un efecto diferente. También puedes usar tu acción para detener temporalmente el efecto o para reiniciar uno que hayas detenido.Ráfagas. En el interior del cubo se levanta un viento que sopla continuamente en la dirección horizontal que elijas. Tú eliges la intensidad del viento: en calma, moderado o fuerte. Si el viento es moderado o fuerte, los ataques con armas a distancia que lo atraviesen o que se realicen contra objetivos dentro del cubo tienen desventaja en sus tiradas de ataque. Si el viento es fuerte, cualquier criatura que se mueva contra el viento debe gastar 1 pie extra de movimiento por cada pie movido.Corriente descendente. Provocas una ráfaga sostenida de viento fuerte que sopla hacia abajo desde la parte superior del cubo. Los ataques con armas a distancia que atraviesen el cubo o que se realicen contra objetivos situados en su interior tienen desventaja en sus tiradas de ataque. Una criatura debe realizar una tirada de salvación de Fuerza si vuela dentro del cubo por primera vez en un turno o comienza su turno allí volando. Si falla la tirada de salvación, la criatura es derribada.Corriente ascendente. Provocas una corriente ascendente sostenida dentro del cubo, que se eleva desde el borde inferior del cubo. Las criaturas que terminan una caída dentro del cubo sólo sufren la mitad del daño de la caída. Cuando una criatura dentro del cubo realiza un salto vertical, puede saltar hasta 3 metros más alto de lo normal.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 5', '300 pies', 'Druida, Mago, Lanzador de Rituales', 'Transmutacion'),
(284, 'Creación (Creation)', 'Extraes volutas de material sombrío del Infierno Sombrío para crear un objeto no viviente de materia vegetal dentro de su \"alcance\": materiales blandos, cuerda, madera o algo similar. También puedes usar este hechizo para crear objetos minerales como piedra, cristal o metal. El objeto creado no debe ser mayor que un cubo de 5 pies, y el objeto debe ser de una forma y material que hayas visto antes.La duración depende del material del objeto. Si el objeto está compuesto de varios materiales, utiliza la duración más corta.<b>Materia vegetal</b> 1 día<b>Piedra o cristal</b> 12 horas<b>Metales preciosos</b> 1 hora<b>Gemas</b> 10 minutos<b>Adamantina o mithral</b> 1 minutoEl uso de cualquier material creado por este hechizo como componente material de otro hechizo hace que éste falle.', 'Special', 'no', '1 minuto', 'Nivel 5', '30 pies', 'Hechicero, Mago, Lanzador de Rituales', 'Ilusion'),
(285, 'Ola destructiva (Destructive Wave)', 'Golpeas el suelo y creas un estallido de energía divina que se extiende desde ti. Cada criatura que elijas en un radio de 30 pies debe tener éxito en una tirada de salvación de Constitución o recibirá 5d6 puntos de daño por trueno, así como 5d6 puntos de daño radiante o necrótico (a tu elección), y será derribada. Una criatura que tenga éxito en su tirada de salvación recibe la mitad de daño y no es derribada.', 'Instantaneo', 'no', '1 acción', 'Nivel 5', 'Personal', 'Paladín, Paladin', 'Evocacion'),
(286, 'Disipar el bien y el mal (Dispel Evil and Good)', 'Una energía resplandeciente te rodea y te protege de feéricos, muertos vivientes y criaturas originarias de más allá del Plano Material. Mientras dure el hechizo, los celestiales, elementales, fey, fiends y no muertos tienen desventaja en las tiradas de ataque contra ti.Puedes terminar el hechizo antes de tiempo utilizando cualquiera de las siguientes funciones especiales.<b>Romper Encantamiento.</b> Como acción, tocas a una criatura a tu alcance que esté encantada, asustada o poseída por un celestial, un elemental, un fey, un fiend o un no muerto. La criatura que tocas deja de estar encantada, asustada o poseída por dichas criaturas.<b>Expulsión.</b> Como acción, realiza un ataque cuerpo a cuerpo contra un celestial, un elemental, un fey, un fiend o un no muerto que puedas alcanzar. Si aciertas, intentas expulsar a la criatura a su plano natal. La criatura debe tener éxito en una tirada de salvación de carisma o ser enviada de vuelta a su plano natal (si aún no está allí). Si no están en su plano natal, los no muertos son enviados a Shadowfell, y los fey son enviados a Feywild.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 5', 'Personal', 'Clerigo, Paladin', 'Abjuracion'),
(287, 'Dominar persona (Dominate Person)', 'Intentas hechizar a un humanoide que veas dentro de tu alcance. Debe tener éxito en una tirada de salvación de sabiduría o quedará hechizado por ti mientras dure el hechizo. Si tú o criaturas amigas tuyas estáis luchando contra él, tiene ventaja en la tirada de salvación.Mientras el objetivo está encantado, tienes un vínculo telepático con él mientras los dos estéis en el mismo plano de existencia. Puedes utilizar este vínculo telepático para dar órdenes a la criatura mientras estás consciente (no requiere acción), que hará todo lo posible por obedecer. Puedes especificar un curso de acción simple y general, como \"Ataca a esa criatura\", \"Corre hacia allí\" o \"Busca ese objeto\". Si la criatura cumple la orden y no recibe más indicaciones tuyas, se defiende y se preserva lo mejor que puede.Puedes utilizar tu acción para tomar el control total y preciso del objetivo. Hasta el final de tu siguiente turno, la criatura sólo realiza las acciones que tú elijas y no hace nada que tú no le permitas hacer. Durante este tiempo también puedes hacer que la criatura utilice una reacción, pero esto requiere que utilices también tu propia reacción.Cada vez que el objetivo recibe daño, realiza una nueva tirada de salvación contra el hechizo. Si la tirada de salvación tiene éxito, el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 5', '60 pies', 'Bardo, Clerigo, Hechicero, Brujo, Mago', 'Encantamiento'),
(288, 'Sueño (Dream)', 'Este hechizo da forma a los sueños de una criatura. Elige una criatura conocida por ti como objetivo de este hechizo. El objetivo debe estar en el mismo plano de existencia que tú. Las criaturas que no duermen, como los elfos, no pueden ser contactadas por este hechizo. Tú, o una criatura dispuesta a la que toques, entráis en estado de trance, actuando como mensajeros.Mientras está en trance, el mensajero es consciente de su entorno, pero no puede realizar acciones ni moverse.Si el objetivo está dormido, el mensajero aparece en sus sueños y puede conversar con él mientras permanezca dormido, mientras dure el hechizo. El mensajero también puede dar forma al entorno del sueño, creando paisajes, objetos y otras imágenes. El mensajero puede salir del trance en cualquier momento, poniendo fin al efecto del hechizo antes de tiempo. El objetivo recuerda el sueño perfectamente al despertar. Si el objetivo está despierto cuando lanzas el hechizo, el mensajero lo sabe, y puede terminar el trance (y el hechizo) o esperar a que el objetivo se duerma, momento en el que el mensajero aparece en los sueños del objetivo.Puedes hacer que el mensajero parezca monstruoso y aterrador para el objetivo. Si lo haces, el mensajero puede entregar un mensaje de no más de diez palabras y entonces el objetivo debe hacer una tirada de salvación de sabiduría. Si falla la tirada de salvación, los ecos de la monstruosidad fantasmal provocan una pesadilla que dura lo que el objetivo duerme y le impide obtener ningún beneficio de ese descanso. Además, cuando el objetivo despierta, recibe 3d6 puntos de daño psíquico.Si tiene una parte del cuerpo, mechón de pelo, recorte de una uña o porción similar del cuerpo del objetivo, éste realiza su tirada de salvación con desventaja.', '8 horas', 'no', '1 minuto', 'Nivel 5', 'Special', 'Bardo, Druida, Brujo, Mago', 'Ilusion'),
(289, 'Golpe de llamas (Flame Strike)', 'Una columna vertical de fuego divino ruge desde los cielos en el lugar que especifiques. Cada criatura en un cilindro de 10 pies de radio y 40 pies de altura centrado en un punto dentro del alcance debe hacer una tirada de salvación de destreza. Una criatura recibe 4d6 puntos de daño de fuego y 4d6 puntos de daño radiante si falla la tirada de salvación, o la mitad de daño si tiene éxito.', 'Instantaneo', 'no', '1 acción', 'Nivel 5', '60 pies', 'Clerigo, Paladin, Brujo', 'Evocacion'),
(290, 'Geas (Geas)', 'Impartes una orden mágica a una criatura que puedas ver dentro de tu alcance, obligándola a realizar algún servicio o a abstenerse de alguna acción o curso de actividad que tú decidas. Si la criatura puede entenderte, debe tener éxito en una tirada de salvación de sabiduría o quedará encantada por ti mientras dure la orden. Mientras la criatura esté encantada por ti, sufrirá 5d10 puntos de daño psíquico cada vez que actúe de forma contraria a tus instrucciones, pero no más de una vez al día. Una criatura que no pueda entenderte no se ve afectada por el hechizo.Puedes dar cualquier orden que elijas, salvo una actividad que provoque una muerte segura. Si das una orden suicida, el hechizo termina.Puedes terminar el hechizo antes de tiempo utilizando una acción para desecharlo. Un hechizo de eliminar maldición, restauración mayor o deseo también lo finaliza.', '30 days', 'no', '1 minuto', 'Nivel 5', '60 pies', 'Bardo, Clerigo, Druida, Paladin, Mago', 'Encantamiento'),
(291, 'Restauración mayor (Greater Restoration)', 'Imbuyes energía positiva a una criatura que tocas para deshacer un efecto debilitador. Puedes reducir el nivel de agotamiento del objetivo en uno, o acabar con uno de los siguientes efectos sobre el objetivo:- Un efecto que encantara o petrificara al objetivo- Una maldición, incluyendo la sintonización del objetivo con un objeto mágico maldito- Cualquier reducción de una de las puntuaciones de habilidad del objetivo- Un efecto que reduzca el máximo de puntos de vida del objetivo', 'Instantaneo', 'no', '1 acción', 'Nivel 5', 'Toque', 'Bardo, Clerigo, Druida', 'Abjuracion'),
(292, 'Santificar (Hallow)', 'Tocas un punto e infundes un área a su alrededor con poder sagrado (o profano). El área puede tener un radio de hasta 60 pies, y el hechizo falla si el radio incluye un área ya bajo el efecto de un hechizo de santificar. El área afectada está sujeta a los siguientes efectos.En primer lugar, los celestiales, elementales, fey, fiends y no muertos no pueden entrar en el área, ni pueden tales criaturas encantar, asustar o poseer criaturas dentro de ella. Cualquier criatura encantada, asustada o poseída por una criatura de este tipo deja de estar encantada, asustada o poseída al entrar en el área. Puedes excluir a uno o más de esos tipos de criaturas de este efecto.En segundo lugar, puedes vincular un efecto adicional al área. Elige el efecto de la siguiente lista, o elige un efecto ofrecido por el DM. Algunos de estos efectos se aplican a las criaturas del área; puedes designar si el efecto se aplica a todas las criaturas, a las criaturas que siguen a una deidad o líder específico, o a criaturas de un tipo específico, como los orcos o los trolls. Cuando una criatura que se vería afectada entra en el área del conjuro por primera vez en un turno o comienza su turno allí, puede hacer una tirada de salvación de carisma. Si tiene éxito, la criatura ignora el efecto extra hasta que abandone el área.<b>Coraje.</b> Las criaturas afectadas no pueden asustarse mientras estén en el área.<b>Oscuridad.</b> La oscuridad llena el área. La luz normal, así como la luz mágica creada por hechizos de un nivel inferior al de la ranura que utilizaste para lanzar este hechizo, no pueden iluminar el área.<b>Luz diurna.</b> La zona se llena de luz brillante. La oscuridad mágica creada por hechizos de un nivel inferior al de la ranura que utilizaste para lanzar este hechizo no puede extinguir la luz.<b>Protección Energética.</b> Las criaturas afectadas en el área tienen resistencia a un tipo de daño de tu elección, excepto contundente, perforante o cortante.<b>Vulnerabilidad energética.</b> Las criaturas afectadas en el área tienen vulnerabilidad a un tipo de daño de tu elección, excepto contundente, perforante o cortante.<b>Reposo Eterno.</b> Los cadáveres enterrados en el área no pueden convertirse en muertos vivientes.<b>Interferencia extradimensional.</b> Las criaturas afectadas no pueden moverse o viajar usando teletransporte o por medios extradimensionales o interplanares.<b>Miedo.</b> Las criaturas afectadas se asustan mientras están en la zona.<b>Silencio.</b> Ningún sonido puede emanar del interior del área, y ningún sonido puede llegar hasta ella.<b>Lenguas.</b> Las criaturas afectadas pueden comunicarse con cualquier otra criatura de la zona, aunque no compartan un idioma común.', 'Hasta que se disipe', 'no', '24 horas', 'Nivel 5', 'Toque', 'Clerigo, Brujo', 'Evocacion'),
(293, 'Inmovilizar monstruo (Hold Monster)', 'Elige una criatura que puedas ver y alcanzar. El objetivo debe hacer una tirada de salvación de Sabiduría o quedar paralizado mientras dure el hechizo. Este hechizo no tiene efecto contra los muertos vivientes. Al final de cada asalto, el objetivo puede realizar una nueva tirada de salvación de Sabiduría. Si tiene éxito, el hechizo termina para la criatura.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 5', '90 pies', 'Bardo, Clerigo, Paladin, Hechicero, Brujo, Mago', 'Encantamiento'),
(294, 'Inmolación (Immolation)', 'Las llamas envuelven a una criatura que puedas ver dentro del alcance. El objetivo debe realizar una tirada de salvación de Destreza. Si falla la tirada de salvación, recibe 7d6 puntos de daño por fuego, o la mitad si la falla. Si falla la tirada de salvación, el objetivo también arde durante la duración del hechizo. El objetivo en llamas emite luz brillante en un radio de 30 pies y luz tenue en un radio adicional de 30 pies. Al final de cada turno, el objetivo repite la tirada de salvación. Si falla la tirada de salvación, sufre 3d6 puntos de daño por fuego, y el hechizo termina si tiene éxito. Estas llamas mágicas no pueden extinguirse por medios no mágicos.Si el daño de este hechizo reduce un objetivo a 0 puntos de golpe, el objetivo se convierte en cenizas.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 5', '90 pies', 'Hechicero, Mago', 'Evocacion'),
(295, 'Plaga de insectos (Insect Plague)', 'Enjambres de langostas mordedoras llenan una esfera de 20 pies de radio centrada en un punto que elijas dentro del alcance. La esfera se extiende por las esquinas. La esfera permanece mientras dura y su área queda ligeramente oscurecida. El área de la esfera es terreno difícil.Cuando el área aparece, cada criatura en ella debe hacer una tirada de salvación de Constitución. Una criatura recibe 4d10 puntos de daño perforante si falla la tirada de salvación, o la mitad de daño si tiene éxito. Una criatura también debe hacer esta tirada de salvación cuando entra en el área del hechizo por primera vez en un turno o termina su turno allí.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 5', '300 pies', 'Clerigo, Druida, Hechicero', 'Conjuracion'),
(296, 'Conocimiento de leyenda (Legend Lore)', 'Nombra o describe a una persona, lugar u objeto. El destino trae a la mente una información breve y resumida sobre lo que has nombrado. La información puede presentarse como relatos de historia olvidada o incluso información secreta que nunca ha sido revelada. Si la cosa que has nombrado no es de resonancia legendaria, no obtienes ninguna información. Cuanta más información tengas sobre el objeto, más precisa y detallada será la información que recibas.Lo que aprendes es preciso, pero puede estar oculto en un lenguaje figurado. Por ejemplo, si tienes una misteriosa hacha mágica en la mano, el hechizo puede revelar esta información: \"Ay de los malvados que afecta a sus manos el hacha porque el mango decidir los de maligno Sólo un verdadero hijo de la piedra imán. y amado Moradin podría despertar el verdadero poder de esta hacha, y sólo con la palabra sagrada Rudnogg en los labios \".', 'Instantaneo', 'no', '10 minutos', 'Nivel 5', 'Personal', 'Bardo, Clerigo, Mago', 'Adivinacion'),
(297, 'Maelstrom (Maelstrom)', 'Aparece una masa de agua de 1,5 m de profundidad y se arremolina en un radio de 9 m centrado en un punto que puedas ver dentro del alcance. El punto debe estar en tierra o en una masa de agua. Hasta que el conjuro termine, esa zona es terreno difícil, y cualquier criatura que empiece su turno allí debe tener éxito en una tirada de salvación de Fuerza o recibir 6d6 puntos de daño contundente y ser arrastrada 3 metros hacia el centro.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 5', '120 pies', 'Druida', 'Evocacion'),
(298, 'Curar heridas en masa (Mass Cure Wounds)', 'Una onda de energía curativa fluye desde un punto de tu elección dentro del alcance. Elige hasta seis criaturas en una esfera de 30 pies de radio centrada en ese punto. Cada objetivo recupera puntos de golpe iguales a 3d8 + tu modificador de habilidad de conjuro. Este hechizo no tiene efecto sobre muertos vivientes o constructos.', 'Instantaneo', 'no', '1 acción', 'Nivel 5', '60 pies', 'Bardo, Clerigo, Druida', 'Conjuracion'),
(299, 'Engañar (Mislead)', 'Te vuelves invisible al mismo tiempo que aparece un doble ilusorio tuyo en el lugar donde te encuentras. El doble dura lo que dura, pero la invisibilidad termina si atacas o lanzas un hechizo.Puedes utilizar tu acción para mover tu doble ilusorio hasta el doble de tu velocidad y hacer que gesticule, hable y se comporte de la forma que elijas.Puedes ver a través de sus ojos y oír a través de sus oídos como si estuvieras situado donde se encuentra. En cada uno de tus turnos, como acción adicional, puedes pasar de utilizar sus sentidos a utilizar los tuyos propios, o viceversa. Mientras utilizas sus sentidos, estás cegado y ensordecido con respecto a tu propio entorno.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 5', 'Personal', 'Bardo, Mago', 'Ilusion'),
(300, 'Modificar memoria (Modify Memory)', 'Intentas remodelar los recuerdos de otra criatura. Una criatura que puedas ver debe realizar una tirada de salvación de sabiduría. Si estás luchando contra la criatura, ésta tiene ventaja en la tirada de salvación. Si falla la tirada de salvación, el objetivo queda hechizado por ti mientras dure el hechizo. El objetivo encantado queda incapacitado y no es consciente de su entorno, aunque aún puede oírte. Si recibe algún daño o es objetivo de otro hechizo, este hechizo termina y no se modifica ninguno de sus recuerdos.Mientras dure este encantamiento, puedes afectar al recuerdo del objetivo de un suceso que haya vivido en las últimas 24 horas y que no haya durado más de 10 minutos. Puedes eliminar permanentemente todo recuerdo del suceso, permitir que el objetivo recuerde el suceso con perfecta claridad y detalles exactos, cambiar su recuerdo de los detalles del suceso o crear un recuerdo de algún otro suceso.Debes hablar con el objetivo para describir cómo se ven afectados sus recuerdos, y éste debe ser capaz de entender tu lenguaje para que los recuerdos modificados arraiguen. Su mente rellena cualquier laguna en los detalles de tu descripción. Si el hechizo termina antes de que hayas terminado de describir los recuerdos modificados, la memoria de la criatura no se altera. De lo contrario, los recuerdos modificados se asientan cuando termina el hechizo.Un recuerdo modificado no afecta necesariamente al comportamiento de la criatura, especialmente si el recuerdo contradice sus inclinaciones naturales, alineamiento o creencias. Un recuerdo modificado ilógico, como implantar un recuerdo de cuánto disfrutaba la criatura rociándose en ácido, se descarta, quizás como un mal sueño. El DM puede considerar que un recuerdo modificado es demasiado absurdo como para afectar a una criatura de forma significativa.Un conjuro de eliminar maldición o de restauración mayor lanzado sobre el objetivo restaura el verdadero recuerdo de la criatura.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 5', '30 pies', 'Bardo, Clerigo, Mago', 'Encantamiento'),
(301, 'Pasadizo (Passwall)', 'Aparece un pasadizo en un punto de tu elección que puedes ver en una superficie de madera, yeso o piedra (como una pared, un techo o un suelo) dentro de tu alcance, y dura lo que dura el pasadizo. Tú eliges las dimensiones de la abertura: hasta 5 pies de ancho, 8 pies de alto y 20 pies de profundidad. El pasaje no crea inestabilidad en la estructura que lo rodea.Cuando la abertura desaparece, cualquier criatura u objeto que aún se encuentre en el pasadizo creado por el hechizo es expulsado de forma segura a un espacio desocupado más cercano a la superficie sobre la que lanzaste el hechizo.', '1 hora', 'no', '1 acción', 'Nivel 5', '30 pies', 'Druida, Mago', 'Transmutacion'),
(302, 'Vínculo planar (Planar Binding)', 'Con este hechizo, intentas atar a un celestial, elemental, fey o demonio a tu servicio. La criatura debe estar a tu alcance durante todo el lanzamiento del hechizo. (Normalmente, primero se invoca a la criatura en el centro de un círculo mágico invertido para mantenerla atrapada mientras se lanza este hechizo). Al finalizar el lanzamiento, el objetivo debe realizar una tirada de salvación de carisma. Si falla la tirada de salvación, queda obligado a servirte mientras dure el hechizo. Si la criatura fue invocada o creada por otro hechizo, la duración de ese hechizo se amplía para coincidir con la duración de este hechizo.Una criatura atada debe seguir tus instrucciones lo mejor que pueda. Puedes ordenar a la criatura que te acompañe en una aventura, que vigile un lugar o que entregue un mensaje. La criatura obedece al pie de la letra tus instrucciones, pero si la criatura te es hostil, se esfuerza por tergiversar tus palabras para conseguir sus propios objetivos. Si la criatura cumple completamente tus instrucciones antes de que termine el hechizo, viaja hasta ti para informarte de este hecho si os encontráis en el mismo plano de existencia. Si te encuentras en otro plano de existencia, regresa al lugar donde la ataste y permanece allí hasta que finaliza el hechizo.', '24 horas', 'no', '1 hora', 'Nivel 5', '60 pies', 'Bardo, Clerigo, Druida, Mago', 'Abjuracion'),
(303, 'Resurrección (Raise Dead)', 'Devuelves la vida a una criatura muerta que toques, siempre que no lleve muerta más de 10 días. Si el alma de la criatura está dispuesta y en libertad de reunirse con el cuerpo, la criatura vuelve a la vida con 1 punto de vida.Este hechizo también neutraliza cualquier veneno y cura enfermedades no mágicas que afectaran a la criatura en el momento de su muerte. Sin embargo, este conjuro no elimina enfermedades mágicas, maldiciones o efectos similares; si no se eliminan antes de lanzar el conjuro, surtirán efecto cuando la criatura vuelva a la vida. El hechizo no puede devolver a la vida a una criatura no muerta.Este hechizo cierra todas las heridas mortales, pero no restaura las partes del cuerpo que faltan. Si a la criatura le faltan partes del cuerpo u órganos esenciales para su supervivencia -su cabeza, por ejemplo- el hechizo falla automáticamente.Regresar de la muerte es un calvario. El objetivo sufre un penalizador de -4 a todas las tiradas de ataque, tiradas de salvación y chequeos de habilidad. Cada vez que el objetivo termina un descanso largo, el penalizador se reduce en 1 hasta que desaparece.', 'Instantaneo', 'no', '1 hora', 'Nivel 5', 'Toque', 'Bardo, Clerigo, Paladin', 'Nigromancia'),
(304, 'Vínculo telepático de Rary (Rary\'s Telepathic Bond)', 'Forjas un vínculo telepático entre hasta ocho criaturas voluntarias de tu elección dentro del alcance, vinculando psíquicamente a cada criatura con todas las demás mientras dure el hechizo. Las criaturas con puntuaciones de Inteligencia de 2 o menos no se ven afectadas por este hechizo.Hasta que el hechizo termine, los objetivos pueden comunicarse telepáticamente a través del vínculo, tengan o no un idioma común. La comunicación es posible a cualquier distancia, aunque no puede extenderse a otros planos de existencia.', '1 hora', 'no', '1 acción', 'Nivel 5', '30 pies', 'Lanzador de Rituales, Mago', 'Adivinacion');
INSERT INTO `conjuros` (`id_spell`, `name`, `descr`, `duracion`, `concentracion`, `casteo`, `level`, `rango`, `clases`, `escuela`) VALUES
(305, 'Reencarnar (Reincarnate)', 'Tocas a un humanoide muerto o un trozo de humanoide muerto. Siempre que la criatura no lleve muerta más de 10 días, el hechizo forma un nuevo cuerpo adulto para ella y luego llama al alma para que entre en ese cuerpo. Si el alma del objetivo no está libre o dispuesta a hacerlo, el hechizo falla.La magia forma un nuevo cuerpo para que la criatura lo habite, lo que probablemente cause que la raza de la criatura cambie. El DM tira un d 100 y consulta la siguiente tabla para determinar qué forma toma la criatura cuando es restaurada a la vida, o el DM elige una forma.<b>01-04</b> Dragonborn<b>05-13</b> Enano, colina<b>14-21</b> Enano, montaña<b>22-25</b> Elfo, oscuro<b>26-34</b> Elfo, alto<b>35-42</b> Elfo, bosque<b>43-46</b> Gnomo, bosque<b>47-52</b> Gnomo, roca<b>53-56</b> Medio-elfo<b>57-60</b> Medio-orco<b>61-68</b> Halfling, pies ligeros<b>69-76</b> Halfling, corpulento<b>77-96</b> Humano<b>97-00</b> TieflingLa criatura reencarnada recuerda su vida y experiencias anteriores. Conserva las capacidades que tenía en su forma original, salvo que cambia su raza original por la nueva y modifica sus rasgos raciales en consecuencia.', 'Instantaneo', 'no', '1 hora', 'Nivel 5', 'Toque', 'Druida', 'Transmutacion'),
(306, 'Clarividencia (Scrying)', 'Puedes ver y oír a una criatura concreta que elijas y que se encuentre en el mismo plano de existencia que tú. El objetivo debe realizar una tirada de salvación de sabiduría, que se ve modificada por lo bien que conozcas al objetivo y el tipo de conexión física que tengas con él. Si un objetivo sabe que estás lanzando este hechizo, puede fallar la tirada de salvación voluntariamente si quiere ser observado.<b>Conocimiento y Modificador de Salvación</b>De segunda mano (has oído hablar del objetivo) +5De primera mano (has conocido al objetivo) +0Familiar (conoces bien al objetivo) -5<b>Conexión y Modificador de Salvación</b>Parecido o imagen -2Posesión o prenda -4Parte del cuerpo, mechón de pelo, uña o similar -10Si la salvación tiene éxito, el objetivo no se ve afectado y no puedes volver a utilizar este hechizo contra él durante 24 horas.Si fallas la salvación, el hechizo crea un sensor invisible a 3 metros del objetivo. Puedes ver y oír a través del sensor como si estuvieras allí. El sensor se mueve con el objetivo, permaneciendo a 10 pies de él mientras dure el hechizo. Una criatura que pueda ver objetos invisibles ve el sensor como un orbe luminoso del tamaño de tu puño.En lugar de apuntar a una criatura, puedes elegir un lugar que hayas visto antes como objetivo de este hechizo. Al hacerlo, el sensor aparece en ese lugar y no se mueve.', 'Hasta 10 minutos', 'si', '10 minutos', 'Nivel 5', 'Personal', 'Bardo, Clerigo, Druida, Paladin, Brujo, Mago', 'Adivinacion'),
(307, 'Apariencia ilusoria (Seeming)', 'Este hechizo te permite cambiar la apariencia de cualquier número de criaturas que puedas ver dentro de su alcance. A cada objetivo que elijas le das una nueva apariencia ilusoria. Un objetivo no dispuesto puede hacer una tirada de salvación de carisma y, si la supera, no se ve afectado por este hechizo.El conjuro disfraza la apariencia física, así como la ropa, la armadura, las armas y el equipo. Puedes hacer que cada criatura parezca 1 pie más baja o más alta y que parezca delgada, gorda o intermedia. No puedes cambiar el tipo de cuerpo de un objetivo, por lo que debes elegir una forma que tenga la misma disposición básica de extremidades. Por lo demás, el alcance de la ilusión depende de ti. El hechizo dura lo que dura, a menos que uses tu acción para desecharlo antes.Los cambios provocados por este hechizo no resisten una inspección física. Por ejemplo, si utilizas este hechizo para añadir un sombrero al atuendo de una criatura, los objetos pasan a través del sombrero, y cualquiera que lo toque no sentiría nada o sentiría la cabeza y el pelo de la criatura. Si utilizas este conjuro para parecer más delgado de lo que eres, la mano de alguien que se extienda para tocarte chocaría contigo mientras estuviera aparentemente inmóvil en el aire.Una criatura puede usar su acción para inspeccionar a un objetivo y hacer un chequeo de Inteligencia (Investigación) contra tu DC de salvación del hechizo. Si tiene éxito, se da cuenta de que el objetivo está disfrazado.', '8 horas', 'no', '1 acción', 'Nivel 5', '30 pies', 'Bardo, Hechicero, Brujo, Mago', 'Ilusion'),
(308, 'Carcaj veloz (Swift Quiver)', 'Transmutas tu aljaba para que produzca un suministro interminable de munición no mágica, que parece saltar a tu mano cuando la coges.En cada uno de tus turnos hasta que el hechizo termine, puedes utilizar una acción adicional para realizar dos ataques con un arma que utilice munición del carcaj. Cada vez que realizas un ataque a distancia de este tipo, tu carcaj reemplaza mágicamente la pieza de munición que utilizaste por una pieza similar de munición no mágica. Cualquier pieza de munición creada por este hechizo se desintegra cuando el hechizo termina. Si el carcaj deja de estar en tu posesión, el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción adicional', 'Nivel 5', 'Toque', 'Explorador', 'Transmutacion'),
(309, 'Telequinesis (Telekinesis)', 'Obtienes la habilidad de mover o manipular criaturas u objetos con el pensamiento. Cuando lanzas el conjuro, y como tu acción cada asalto mientras dure, puedes ejercer tu voluntad sobre una criatura u objeto que puedas ver dentro del alcance, causando el efecto apropiado a continuación. Puedes afectar al mismo objetivo asalto tras asalto, o elegir uno nuevo en cualquier momento. Si cambias de objetivo, el objetivo anterior deja de estar afectado por el hechizo.<b>Criatura.</b> Puedes intentar mover una criatura Enorme o más pequeña. Haz un chequeo de habilidad con tu habilidad de lanzamiento de conjuros impugnado por el chequeo de Fuerza de la criatura. Si ganas el combate, mueves a la criatura hasta 30 pies en cualquier dirección, incluyendo hacia arriba pero no más allá del alcance de este hechizo. Hasta el final de tu siguiente turno, la criatura queda sujeta a tu agarre telequinético. Una criatura elevada queda suspendida en el aire.En los siguientes asaltos, puedes utilizar tu acción para intentar mantener tu agarre telequinético sobre la criatura repitiendo la contienda.<b>Objeto.</b> Puedes intentar mover un objeto que pese hasta 1.000 libras. Si el objeto no está siendo usado o llevado, automáticamente lo mueves hasta 30 pies en cualquier dirección, pero no más allá del alcance de este hechizo.Si el objeto es llevado o transportado por una criatura, debes hacer un chequeo de habilidad con tu habilidad de lanzamiento de conjuros impugnado por el chequeo de Fuerza de esa criatura. Si tienes éxito, alejas el objeto de esa criatura y puedes moverlo hasta 30 pies en cualquier dirección, pero no más allá del alcance de este hechizo.Puedes ejercer un control fino sobre objetos con tu agarre telequinético, como manipular una herramienta simple, abrir una puerta o un contenedor, guardar o recuperar un objeto de un contenedor abierto o verter el contenido de un vial.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 5', '60 pies', 'Hechicero, Brujo, Mago', 'Transmutacion'),
(310, 'Círculo de teletransporte (Teleportation Circle)', 'Cuando lanzas el conjuro, dibujas un círculo de 3 metros de diámetro en el suelo inscrito con sellos que vinculan tu ubicación a un círculo de teletransporte permanente de tu elección cuya secuencia de sellos conozcas y que esté en el mismo plano de existencia que tú. Un portal resplandeciente se abre dentro del círculo que dibujaste y permanece abierto hasta el final de tu siguiente turno. Cualquier criatura que entre en el portal aparece instantáneamente en un radio de 1,5 m del círculo de destino o en el espacio desocupado más cercano si ese espacio está ocupado.Muchos templos importantes, gremios y otros lugares importantes tienen círculos de teletransporte permanentes inscritos en algún lugar de sus confines. Cada uno de estos círculos incluye una secuencia de sigilos única: una cadena de runas mágicas dispuestas según un patrón determinado. Cuando obtienes por primera vez la habilidad de lanzar este conjuro, aprendes las secuencias de sellos para dos destinos en el Plano Material, determinados por el DM. Puedes aprender secuencias de sellos adicionales durante tus aventuras. Puedes memorizar una nueva secuencia de sellos después de estudiarla durante 1 minuto.Puedes crear un círculo de teletransporte permanente lanzando este conjuro en el mismo lugar todos los días durante un año. No es necesario que utilices el círculo para teletransportarte cuando lances el hechizo de esta forma.', '1 ronda', 'no', '1 minuto', 'Nivel 5', '10 pies', 'Bardo, Hechicero, Mago', 'Conjuracion'),
(311, 'Transmutar roca (Transmute Rock)', 'Eliges un área de piedra o barro que puedas ver que quepa dentro de un cubo de 40 pies y que esté dentro del alcance, y eliges uno de los siguientes efectos.Transmutar roca en barro. La roca no mágica de cualquier tipo en el área se convierte en un volumen igual de lodo espeso y fluido que permanece durante la duración del hechizo.Si lanzas el conjuro sobre un área de tierra, ésta se vuelve lo suficientemente fangosa como para que las criaturas puedan hundirse en ella. Cada pie que una criatura se mueve a través del barro le cuesta 4 pies de movimiento, y cualquier criatura que esté en el suelo cuando lanzas el conjuro debe hacer una tirada de salvación de Fuerza. Una criatura también debe hacer esta salvación la primera vez que entra en el área en un turno o termina su turno allí. Si falla la tirada de salvación, la criatura se hunde en el barro y queda inmovilizada, aunque puede utilizar una acción para poner fin a la condición de inmovilización tirando de sí misma para liberarse del barro.Si lanzas el hechizo sobre un techo, el barro cae. Cualquier criatura que se encuentre bajo el barro al caer debe realizar una tirada de salvación de Destreza. La criatura recibe 4d8 puntos de daño contundente si falla la tirada de salvación, o la mitad de daño si tiene éxito.Transmutar barro en roca. El barro no mágico o las arenas movedizas en un área de no más de 10 pies de profundidad se transforman en piedra blanda durante la duración del hechizo. Cualquier criatura en el barro cuando se transforma debe hacer una tirada de salvación de Destreza. Si falla la tirada de salvación, la criatura queda atrapada por la roca. La criatura retenida puede utilizar una acción para intentar liberarse teniendo éxito en un chequeo de Fuerza (DC 20) o infligiendo 25 puntos de daño a la roca que la rodea. Si la salvación tiene éxito, la criatura es expulsada a la superficie a un espacio desocupado.', 'Instantaneo', 'no', '1 acción', 'Nivel 5', '120 pies', 'Druida, Mago', 'Transmutacion'),
(312, 'Paso entre árboles (Tree Stride)', 'Obtienes la habilidad de entrar en un árbol y moverte de su interior al interior de otro árbol del mismo tipo en un radio de 500 pies. Ambos árboles deben estar vivos y tener al menos el mismo tamaño que tú. Debes utilizar 5 pies de movimiento para entrar en un árbol. Conoces al instante la ubicación de todos los demás árboles del mismo tipo en un radio de 500 pies y, como parte del movimiento utilizado para entrar en el árbol, puedes pasar a uno de esos árboles o salir del árbol en el que estás. Apareces en un lugar de tu elección a 5 pies del árbol de destino, utilizando otros 5 pies de movimiento. Si no te queda movimiento, apareces a 5 pies del árbol en el que entraste.Puedes utilizar esta habilidad de transporte una vez por asalto mientras dure. Debes terminar cada turno fuera de un árbol.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 5', 'Personal', 'Clerigo, Druida, Paladin, Explorador', 'Conjuracion'),
(313, 'Muro de fuerza (Wall of Force)', 'Un muro invisible de fuerza surge en un punto de tu alcance. El muro aparece con la orientación que elijas, como una barrera horizontal, vertical o en ángulo. Puede flotar libremente o apoyarse en una superficie sólida. Puedes darle forma de cúpula semiesférica o de esfera con un radio de hasta 3 metros, o puedes formar una superficie plana compuesta por diez paneles de 3 metros por 3 metros. Cada panel debe ser contiguo a otro. En cualquiera de sus formas, el muro tiene un grosor de 1/4 de pulgada. Dura lo que dura. Si el muro atraviesa el espacio de una criatura cuando aparece, la criatura es empujada hacia un lado del muro (tú eliges de qué lado).Nada puede atravesar físicamente el muro. Es inmune a todo tipo de daño y no puede disiparse con magia de disipación. Sin embargo, un hechizo de desintegración destruye el muro al instante. El muro también se extiende hasta el Plano Etéreo, bloqueando el viaje etéreo a través de él.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 5', '120 pies', 'Mago', 'Evocacion'),
(314, 'Muro de piedra (Wall of Stone)', 'Un muro no mágico de piedra maciza surge a la existencia en un punto que elijas dentro del alcance. El muro tiene 15 cm de grosor y está compuesto por diez paneles de 3 metros por 3 metros. Cada panel debe ser contiguo con al menos otro panel. Alternativamente, puedes crear paneles de 10 pies por 20 pies de sólo 3 pulgadas de grosor.Si el muro atraviesa el espacio de una criatura cuando aparece, la criatura es empujada hacia un lado del muro (a tu elección). Si una criatura estuviera rodeada por todos lados por el muro (o por el muro y otra superficie sólida), esa criatura puede hacer una tirada de salvación de destreza. Si tiene éxito, puede usar su reacción para moverse a su velocidad y dejar de estar rodeada por el muro.El muro puede tener cualquier forma que desees, aunque no puede ocupar el mismo espacio que una criatura u objeto. El muro no tiene por qué ser vertical ni descansar sobre ningún cimiento firme. Sin embargo, debe fundirse con la piedra existente y apoyarse sólidamente en ella. Así, puedes utilizar este hechizo para salvar un abismo o crear una rampa.Si creas un tramo de más de 20 pies de longitud, debes reducir a la mitad el tamaño de cada panel para crear soportes. Puedes dar forma rudimentaria al muro para crear almenas, almenas, etc.La muralla es un objeto de piedra que puede ser dañado y, por tanto, atravesado. Cada panel tiene CA 15 y 30 puntos de vida por pulgada de grosor. Reducir un panel a 0 puntos de golpe lo destruye y puede causar que paneles conectados se derrumben a discreción del DM.Si mantienes la concentración en este hechizo durante toda su duración, el muro se convierte en permanente y no puede ser disipado. De lo contrario, el muro desaparece cuando finaliza el hechizo.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 5', '120 pies', 'Druida, Hechicero, Mago', 'Evocacion'),
(315, 'Portal arcano (Arcane Gate)', 'Creas portales de teletransporte enlazados que permanecen abiertos mientras duran. Elige dos puntos en el suelo que puedas ver, un punto a 10 pies de ti y un punto a 500 pies de ti. Un portal circular, de 10 pies de diámetro, se abre sobre cada punto. Si el portal se abriera en el espacio ocupado por una criatura, el hechizo falla y se pierde el lanzamiento.Los portales son anillos brillantes bidimensionales llenos de niebla, flotando a centímetros del suelo y perpendiculares a él en los puntos que elijas. Un anillo sólo es visible desde un lado (a tu elección), que es el lado que funciona como portal.Cualquier criatura u objeto que entre en el portal sale por el otro portal como si ambos fueran adyacentes; atravesar un portal desde el lado que no es portal no tiene ningún efecto. La niebla que llena cada portal es opaca y bloquea la visión a través de ella. En tu turno, puedes girar los anillos como acción adicional para que el lado activo mire en una dirección diferente.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 6', '500 pies', 'Hechicero, Mago, Brujo, Lanzador de Rituales', 'Conjuracion'),
(316, 'Barrera de hojas (Blade Barrier)', 'Creas un muro vertical de cuchillas giratorias y afiladas hechas de energía mágica. El muro aparece dentro de su alcance y dura lo que dura. Puedes crear un muro recto de hasta 100 pies de largo, 20 pies de alto y 5 pies de grosor, o un muro anillado de hasta 60 pies de diámetro, 20 pies de alto y 5 pies de grosor. El muro proporciona tres cuartos de cobertura a las criaturas que se encuentran tras él, y su espacio es terreno difícil.Cuando una criatura entra en el área del muro por primera vez en un turno o comienza su turno allí, la criatura debe hacer una tirada de salvación de destreza. Si falla la tirada de salvación, la criatura recibe 6d10 puntos de daño cortante. Si la tirada de salvación tiene éxito, la criatura recibe la mitad de daño.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 6', '90 pies', 'Clérigo, Clerigo', 'Evocacion'),
(317, 'Huesos de la tierra (Bones of the Earth)', 'Haces estallar hasta seis pilares de piedra desde lugares del suelo que puedas ver dentro de tu alcance. Cada pilar es un cilindro de 1,5 m de diámetro y hasta 9 m de altura. El suelo donde aparece un pilar debe ser lo suficientemente ancho para su diámetro, y puedes apuntar al suelo bajo una criatura si ésta es Mediana o más pequeña. Cada pilar tiene CA 5 y 30 puntos de golpe. Cuando se reduce a 0 puntos de golpe, un pilar se desmorona en escombros, lo que crea un área de terreno difícil con un radio de 10 pies. Los escombros duran hasta que se limpian.Si se crea un pilar bajo una criatura, ésta debe tener éxito en una tirada de salvación de Destreza o ser levantada por el pilar. La criatura puede elegir fallar la tirada de salvación.Si un pilar no puede alcanzar su altura máxima debido a un techo u otro obstáculo, la criatura que se encuentre sobre el pilar recibe 6d6 puntos de daño contundente y queda inmovilizada, atrapada entre el pilar y el obstáculo. La criatura inmovilizada puede utilizar una acción para realizar un chequeo de Fuerza o Destreza (a elección de la criatura) contra la CD de la tirada de salvación del hechizo. Si tiene éxito, la criatura deja de estar atrapada y debe salirse del pilar o caerse.', 'Instantaneo', 'no', '1 acción', 'Nivel 6', '120 pies', 'Druida', 'Transmutacion'),
(318, 'Relámpago encadenado (Chain Lightning)', 'Creas un rayo que se arquea hacia un objetivo de tu elección que puedas ver dentro de tu alcance. Tres rayos saltan desde ese objetivo hasta otros tres objetivos, cada uno de los cuales debe estar a menos de 30 pies del primer objetivo. Un objetivo puede ser una criatura o un objeto y sólo puede ser alcanzado por uno de los proyectiles.Un objetivo debe realizar una tirada de salvación de destreza. Si falla la tirada de salvación, el objetivo recibe 10d8 puntos de daño por rayo, o la mitad si tiene éxito.', 'Instantaneo', 'no', '1 acción', 'Nivel 6', '150 pies', 'Hechicero, Mago, Lanzador de Rituales', 'Evocacion'),
(319, 'Círculo de la muerte (Circle of Death)', 'Una esfera de energía negativa se extiende en un radio de 18 metros desde un punto dentro del alcance. Cada criatura en esa área debe realizar una tirada de salvación de Constitución. Un objetivo recibe 8d6 puntos de daño necrótico si falla la tirada de salvación, o la mitad de daño si tiene éxito.', 'Instantaneo', 'no', '1 acción', 'Nivel 6', '150 pies', 'Hechicero, Mago, Brujo, Lanzador de Rituales', 'Nigromancia'),
(320, 'Invocar feérico (Conjure Fey)', 'Invocas a una criatura feérica de nivel de desafío 6 o inferior, o a un espíritu feérico que adopta la forma de una bestia de nivel de desafío 6 o inferior. Aparece en un espacio desocupado que puedas ver dentro de su alcance. La criatura feérica desaparece cuando baja a 0 puntos de vida o cuando termina el hechizo.La criatura feérica es amistosa contigo y tus compañeros mientras dure el hechizo. Tira iniciativa por la criatura, que tiene sus propios turnos. Obedece cualquier orden verbal que le des (no requiere ninguna acción por tu parte), siempre que no infrinja su alineamiento. Si no le das ninguna orden, se defiende de las criaturas hostiles, pero no realiza ninguna otra acción.Si tu concentración se rompe, la criatura feérica no desaparece. En cambio, pierdes el control sobre ella, se vuelve hostil hacia ti y tus compañeros y puede atacar. Una criatura feérica no controlada no puede ser rechazada por ti, y desaparece 1 hora después de que la invocaras.El DM tiene las estadísticas de la criatura feérica.', 'Hasta 1 hora', 'si', '1 minuto', 'Nivel 6', '90 pies', 'Druida', 'Conjuracion'),
(321, 'Contingencia (Contingency)', 'Elige un hechizo de 5º nivel o inferior que puedas lanzar, que tenga un tiempo de lanzamiento de 1 acción y que pueda tenerte como objetivo. Lanzas ese hechizo -llamado el hechizo contingente- como parte del lanzamiento de contingencia, gastando ranuras de hechizo para ambos, pero el hechizo contingente no entra en efecto. En su lugar, tiene efecto cuando ocurre una circunstancia determinada. Describes esa circunstancia cuando lanzas los dos hechizos. Por ejemplo, una contingencia lanzada con respiración acuática podría estipular que la respiración acuática entra en efecto cuando te ves envuelto en agua o un líquido similar. El hechizo contingente tiene efecto inmediatamente después de que la circunstancia se cumpla por primera vez, lo quieras o no. y entonces la contingencia termina.El hechizo contingente tiene efecto sólo sobre ti, incluso si normalmente puede tener como objetivo a otros. Sólo puedes usar un hechizo de contingencia a la vez. Si lanzas este hechizo de nuevo, el efecto de otro hechizo de contingencia sobre ti termina. Además, la contingencia termina sobre ti si su componente material no está nunca en tu persona.', '10 days', 'no', '10 minutos', 'Nivel 6', 'Personal', 'Mago, Lanzador de Rituales', 'Evocacion'),
(322, 'Crear no-muerto (Create Undead)', 'Sólo puedes lanzar este hechizo de noche. Elige hasta tres cadáveres de humanoides medianos o pequeños dentro del alcance. Cada cadáver se convierte en un ghoul bajo tu control. (El DM tiene las estadísticas del juego para estas criaturas).Como acción de bonificación en cada uno de tus turnos, puedes comandar mentalmente a cualquier criatura que hayas animado con este hechizo si la criatura está a menos de 120 pies de ti (si controlas múltiples criaturas, puedes comandar a cualquiera o a todas ellas al mismo tiempo, emitiendo la misma orden a cada una). Tú decides qué acción llevará a cabo la criatura y adónde se moverá durante su siguiente turno, o puedes dar una orden general, como vigilar una cámara o un pasillo en particular. Si no das ninguna orden, la criatura sólo se defiende de las criaturas hostiles. Una vez dada una orden, la criatura sigue cumpliéndola hasta completar su tarea.La criatura está bajo tu control durante 24 horas, tras las cuales deja de obedecer cualquier orden que le hayas dado. Para mantener el control de la criatura durante otras 24 horas, debes lanzar este hechizo sobre la criatura antes de que termine el periodo actual de 24 horas. Este uso del hechizo reafirma tu control sobre hasta tres criaturas que hayas animado con este hechizo, en lugar de animar otras nuevas.', 'Instantaneo', 'no', '1 minuto', 'Nivel 6', '10 pies', 'Clérigo, Clerigo, Mago, Brujo, Lanzador de Rituales', 'Nigromancia'),
(323, 'Desintegrar (Disintegrate)', 'Un fino rayo verde brota del dedo que apuntas hacia un objetivo que puedas ver dentro del alcance. El objetivo puede ser una criatura, un objeto o una creación de fuerza mágica, como el muro creado por Muro de Fuerza.Una criatura que sea objetivo de este hechizo debe realizar una tirada de salvación de destreza. Si falla la tirada de salvación, el objetivo recibe 10d6 + 40 puntos de daño de fuerza. Si este daño reduce al objetivo a 0 puntos de golpe, queda desintegrado.Una criatura desintegrada y todo lo que lleva puesto, excepto los objetos mágicos, quedan reducidos a un montón de fino polvo gris. La criatura sólo puede volver a la vida mediante un hechizo de resurrección verdadera o de deseo.Este hechizo desintegra automáticamente un objeto no mágico Grande o menor o una creación de fuerza mágica. Si el objetivo es un objeto o creación de fuerza Enorme o mayor, este conjuro desintegra una porción de 10 pies cúbicos del mismo. Un objeto mágico no se ve afectado por este hechizo.', 'Instantaneo', 'no', '1 acción', 'Nivel 6', '60 pies', 'Hechicero, Mago', 'Transmutacion'),
(324, 'Invocación instantánea de Drawmij (Drawmij\'s Instant Summons)', 'Tocas un objeto que pese 10 libras o menos y cuya dimensión más larga sea de 6 pies o menos. El hechizo deja una marca invisible en su superficie e inscribe de forma invisible el nombre del objeto en el zafiro que utilices como componente material. Cada vez que lances este hechizo, debes utilizar un zafiro diferente.En cualquier momento posterior, puedes usar tu acción para pronunciar el nombre del objeto y aplastar el zafiro. El objeto aparece instantáneamente en tu mano, independientemente de las distancias físicas o planares, y el hechizo termina.Si otra criatura está sosteniendo o llevando el objeto, aplastar el zafiro no transporta el objeto hacia ti, sino que tú aprendes quién es la criatura que posee el objeto y aproximadamente dónde se encuentra esa criatura en ese momento.Disipar magia o un efecto similar aplicado con éxito al zafiro acaba con el efecto de este hechizo.', 'Hasta que se disipe', 'no', '1 minuto', 'Nivel 6', 'Toque', 'Lanzador de Rituales, Mago', 'Conjuracion'),
(325, 'Mordisco ocular (Eyebite)', 'Durante la duración del hechizo, tus ojos se convierten en un vacío de tinta imbuido de un terrible poder. Una criatura de tu elección en un radio de 60 pies que puedas ver debe tener éxito en una tirada de salvación de sabiduría o verse afectada por uno de los siguientes efectos de tu elección mientras dure el hechizo. En cada uno de tus turnos hasta que el hechizo termine, puedes usar tu acción para apuntar a otra criatura pero no puedes apuntar a una criatura de nuevo si ha tenido éxito en una tirada de salvación contra este lanzamiento de eyebite.<b>Dormir.</b> El objetivo cae inconsciente. Despierta si recibe algún daño o si otra criatura utiliza su acción para sacudir al durmiente y despertarlo.<b>Pánico.</b> El objetivo te tiene miedo. En cada uno de sus turnos, la criatura asustada debe realizar la acción de Aterrorizarse y alejarse de ti por la ruta más segura y corta disponible, a menos que no haya ningún lugar al que moverse. Si el objetivo se mueve a un lugar al menos a 60 pies de ti donde ya no pueda verte, este efecto termina.<b>Enfermo.</b> El objetivo tiene desventaja en las tiradas de ataque y los chequeos de habilidad. Al final de cada turno, puede realizar otra tirada de salvación de sabiduría. Si tiene éxito, el efecto termina.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 6', 'Personal', 'Bardo, Hechicero, Brujo, Mago', 'Nigromancia'),
(326, 'Encontrar el camino (Find the Path)', 'Este hechizo te permite encontrar la ruta física más corta y directa a una ubicación fija específica que conozcas en el mismo plano de existencia. Si nombras un destino en otro plano de existencia, un destino que se mueve (como una fortaleza móvil) o un destino que no es específico (como \"la guarida de un dragón verde\"), el hechizo falla.Mientras estés en el mismo plano de existencia que el destino, sabrás a qué distancia se encuentra y en qué dirección. Mientras viajas hacia allí, siempre que se te presenten varios caminos en el camino, determinas automáticamente cuál es la ruta más corta y directa (aunque no necesariamente la más segura) hacia el destino.', 'Hasta 24 horas', 'si', '1 minuto', 'Nivel 6', 'Personal', 'Bardo, Clerigo, Druida', 'Adivinacion'),
(327, 'Carne a piedra (Flesh to Stone)', 'Intentas convertir en piedra a una criatura que puedas ver dentro de tu alcance. Si el cuerpo del objetivo es de carne, la criatura debe realizar una tirada de salvación de Constitución. Si falla, queda inmovilizada y su carne comienza a endurecerse. Si la salvación tiene éxito, la criatura no se ve afectada.Una criatura restringida por este hechizo debe realizar otra tirada de salvación de Constitución al final de cada uno de sus turnos. Si salva con éxito contra este hechizo tres veces, el hechizo termina. Si falla tres veces, se convierte en piedra y queda petrificada mientras dure el hechizo. No es necesario que los éxitos y los fracasos sean consecutivos; lleva la cuenta de ambos hasta que el objetivo consiga tres iguales.Si la criatura se rompe físicamente mientras está petrificada, sufre deformaciones similares si vuelve a su estado original.Si mantienes la concentración en este hechizo durante toda la duración posible, la criatura queda convertida en piedra hasta que se elimine el efecto.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 6', '60 pies', 'Brujo, Mago', 'Transmutacion'),
(328, 'Prohibición (Forbiddance)', 'Creas una barrera contra los viajes mágicos que protege hasta 40.000 pies cuadrados de superficie hasta una altura de 30 pies sobre el suelo. Mientras dure, las criaturas no pueden teletransportarse a la zona ni utilizar portales, como los creados por el conjuro puerta, para entrar en ella. El hechizo protege la zona contra los viajes planares y, por lo tanto, impide que las criaturas accedan a la zona a través del Plano Astral, el Plano Etéreo, el Feywild, el Sótano Sombrío o el hechizo de cambio de plano.Además, el hechizo daña a los tipos de criaturas que elijas al lanzarlo. Elige uno o más de los siguientes: celestiales, elementales, fey, fiends y no muertos. Cuando una criatura elegida entra en el área del hechizo por primera vez en un turno o comienza su turno allí, la criatura recibe 5d10 puntos de daño radiante o necrótico (a tu elección cuando lanzas este hechizo).Cuando lanzas este hechizo, puedes designar una contraseña. Una criatura que pronuncie la contraseña al entrar en el área no recibe daño del hechizo.El área del hechizo no puede solaparse con el área de otro hechizo de prohibición. Si lanzas Prohibición todos los días durante 30 días en el mismo lugar, el hechizo dura hasta que se disipa y los componentes materiales se consumen en el último lanzamiento.', '24 horas', 'no', '10 minutos', 'Nivel 6', 'Toque', 'Clerigo, Lanzador de Rituales', 'Abjuracion'),
(329, 'Globo de invulnerabilidad (Globe of Invulnerability)', 'Una barrera inmóvil y débilmente resplandeciente surge en un radio de 3 metros a tu alrededor y permanece mientras dure.Cualquier conjuro de 5º nivel o inferior lanzado desde el exterior de la barrera no puede afectar a las criaturas u objetos que se encuentren en su interior, incluso si el conjuro se lanza utilizando una ranura de conjuro de nivel superior. Tal hechizo puede tener como objetivo criaturas y objetos dentro de la barrera, pero el hechizo no tiene efecto sobre ellos. Del mismo modo, el área dentro de la barrera se excluye de las áreas afectadas por tales hechizos.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 6', 'Personal', 'Hechicero, Mago', 'Abjuracion'),
(330, 'Guardianes y protecciones (Guards and Wards)', 'Creas un pabellón que protege hasta 2.500 pies cuadrados de superficie (un área de 50 pies cuadrados, o cien cuadrados de 5 pies o veinticinco cuadrados de 10 pies). El área protegida puede tener hasta 6 metros de altura y la forma que desees. Puedes proteger varios pisos de una fortaleza dividiendo el área entre ellos, siempre que puedas entrar en cada área contigua mientras lanzas el hechizo.Cuando lanzas este hechizo, puedes especificar individuos que no se vean afectados por ninguno o todos los efectos que elijas. También puedes especificar una contraseña que, cuando se pronuncia en voz alta, hace que el hablante sea inmune a estos efectos.Guardias y protecciones crea los siguientes efectos dentro del área protegida.<b>Pasillos.</b> La niebla llena todos los pasillos protegidos, oscureciéndolos en gran medida. Además, en cada intersección o bifurcación que ofrezca una elección de dirección, hay un 50% de posibilidades de que una criatura que no seas tú crea que va en la dirección opuesta a la que elige.<b>Puertas.</b> Todas las puertas de la zona protegida se cierran mágicamente, como si estuvieran selladas por un hechizo de cerradura arcana. Además, puedes cubrir hasta diez puertas con una ilusión (equivalente a la función de objeto ilusorio del conjuro de ilusión menor) para que parezcan simples secciones de pared. <b>Escaleras.</b> Las telarañas llenan todas las escaleras de la zona protegida de arriba abajo, como el hechizo de telaraña. Estas telarañas vuelven a crecer en 10 minutos si son quemadas o arrancadas mientras duran las guardas y los resguardos.<b>Otro Efecto de Hechizo.</b> Puedes colocar a tu elección uno de los siguientes efectos mágicos dentro del área protegida de la fortaleza.- Coloca luces danzantes en cuatro pasillos. Puedes diseñar un sencillo programa para que las luces se repitan mientras dure la guardia.- Coloca una boca mágica en dos lugares.- Coloca una nube apestosa en dos lugares. Los vapores aparecen en los lugares que designes; vuelven en 10 minutos si los dispersa el viento mientras duren las guardias y los resguardos.- Coloca una ráfaga de viento constante en un pasillo o habitación.- Coloca una sugestión en un lugar. Seleccionas un área de hasta 5 pies cuadrados, y cualquier criatura que entre o pase por el área recibe la sugestión mentalmente.Toda el área protegida irradia magia. Un lanzamiento de disipar magia sobre un efecto específico, si tiene éxito, elimina sólo ese efecto.Puedes crear una estructura vigilada y protegida permanentemente lanzando este hechizo todos los días durante un año.', '24 horas', 'no', '10 minutos', 'Nivel 6', 'Toque', 'Bardo, Mago', 'Abjuracion'),
(331, 'Daño (Harm)', 'Desatas una enfermedad virulenta sobre una criatura que puedas ver dentro de tu alcance. El objetivo debe realizar una tirada de salvación de Constitución. Si falla la tirada de salvación, recibe 14d6 puntos de daño necrótico, o la mitad de daño si la tirada de salvación tiene éxito. El daño no puede reducir los puntos de golpe del objetivo por debajo de 1. Si el objetivo falla la tirada de salvación, sus puntos de golpe máximos se reducen durante 1 hora en una cantidad igual al daño necrótico que recibió. Cualquier efecto que elimine una enfermedad permite que el máximo de puntos de golpe de una criatura vuelva a la normalidad antes de que pase ese tiempo.', 'Instantaneo', 'no', '1 acción', 'Nivel 6', '60 pies', 'Clerigo', 'Nigromancia'),
(332, 'Curar (Heal)', 'Elige una criatura que puedas ver dentro de tu alcance. Una oleada de energía positiva inunda a la criatura, haciéndole recuperar 70 puntos de golpe. Este hechizo también acaba con la ceguera, la sordera y cualquier enfermedad que afecte al objetivo. Este hechizo no tiene efecto sobre constructos ni muertos vivientes.', 'Instantaneo', 'no', '1 acción', 'Nivel 6', '60 pies', 'Clerigo, Druida', 'Evocacion'),
(333, 'Banquete de los héroes (Heroes\' Feast)', 'Ofreces un gran festín, que incluye comida y bebida magníficas. El festín tarda 1 hora en consumirse y desaparece al cabo de ese tiempo, y los efectos beneficiosos no se manifiestan hasta que pasa esa hora. Hasta doce criaturas más pueden participar en el festín.Una criatura que participa en el festín obtiene varios beneficios. La criatura se cura de todas las enfermedades y venenos, se vuelve inmune al veneno y al miedo, y hace todas las tiradas de salvación de sabiduría con ventaja. Su punto de golpe máximo también aumenta en 2d10, y gana el mismo número de puntos de golpe. Estos beneficios duran 24 horas.', 'Instantaneo', 'no', '10 minutos', 'Nivel 6', '30 pies', 'Clerigo, Druida', 'Conjuracion'),
(334, 'Investidura de llama (Investiture of Flame)', 'Las llamas recorren tu cuerpo, arrojando una luz brillante en un radio de 30 pies y una luz tenue en un radio adicional de 30 pies durante la duración del hechizo. Las llamas no te dañan. Hasta que el hechizo termine, obtienes los siguientes beneficios:- Eres inmune al daño por fuego y tienes resistencia al daño por frío.- Cualquier criatura que se mueva a menos de 5 pies de ti por primera vez en un turno o termine su turno allí recibe 1d10 puntos de daño por fuego.- Puedes usar tu acción para crear una línea de fuego de 15 pies de largo y 5 pies de ancho que se extienda desde ti en la dirección que elijas. Cada criatura en la línea debe hacer una tirada de salvación de Destreza. Una criatura recibe 4d8 puntos de daño por fuego si falla la tirada de salvación, o la mitad de daño si tiene éxito.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 6', 'Personal', 'Druida, Hechicero, Brujo, Mago', 'Transmutacion'),
(335, 'Investidura de hielo (Investiture of Ice)', 'Hasta que el hechizo termine, el hielo invade tu cuerpo y obtienes los siguientes beneficios:- Eres inmune al daño por frío y tienes resistencia al daño por fuego.- Puedes moverte por terrenos difíciles creados por el hielo o la nieve sin gastar movimiento adicional.- El suelo en un radio de 10 pies a tu alrededor está helado y es terreno difícil para las criaturas que no seas tú. El radio se mueve contigo.- Puedes usar tu acción para crear un cono de viento helado de 15 pies que se extiende desde tu mano extendida en la dirección que elijas. Cada criatura en el cono debe hacer una tirada de salvación de Constitución. Una criatura recibe 4d6 puntos de daño por frío si falla la tirada de salvación, o la mitad de daño si tiene éxito. Una criatura que falle su salvación contra este efecto ve su velocidad reducida a la mitad hasta el inicio de tu siguiente turno.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 6', 'Personal', 'Druida, Hechicero, Brujo, Mago', 'Transmutacion'),
(336, 'Investidura de piedra (Investiture of Stone)', 'Hasta que el hechizo termina, trozos de roca se extienden por tu cuerpo y obtienes los siguientes beneficios:- Tienes resistencia al daño contundente, perforante y cortante de armas no mágicas.- Puedes usar tu acción para crear un pequeño terremoto en el suelo en un radio de 15 pies centrado en ti. Otras criaturas en ese terreno deben tener éxito en una tirada de salvación de Destreza o ser derribadas.- Puedes moverte por terreno difícil de tierra o piedra sin gastar movimiento adicional. Puedes moverte por tierra o piedra sólida como si fuera aire y sin desestabilizarla, pero no puedes terminar tu movimiento allí. Si lo haces, eres expulsado al espacio desocupado más cercano, este hechizo termina y quedas aturdido hasta el final de tu siguiente turno.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 6', 'Personal', 'Druida, Hechicero, Brujo, Mago', 'Transmutacion'),
(337, 'Investidura de viento (Investiture of Wind)', 'Hasta que el hechizo termine, el viento se arremolina a tu alrededor y obtienes los siguientes beneficios:- Los ataques con armas a distancia realizados contra ti tienen desventaja en la tirada de ataque.- Obtienes una velocidad de vuelo de 60 pies. Si sigues volando cuando termina el hechizo, caes, a menos que puedas evitarlo de algún modo.- Puedes usar tu acción para crear un cubo de 15 pies de viento arremolinado centrado en un punto que puedas ver a 60 pies de ti. Cada criatura en esa área debe hacer una tirada de salvación de Constitución. Una criatura recibe 2d10 puntos de daño contundente si falla la tirada de salvación, o la mitad de daño si tiene éxito. Si una criatura Grande o más pequeña falla la tirada de salvación, esa criatura también es empujada hasta 10 pies de distancia del centro del cubo.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 6', 'Personal', 'Druida, Hechicero, Brujo, Mago', 'Transmutacion'),
(338, 'Frasco mágico (Magic Jar)', 'Tu cuerpo cae en un estado catatónico mientras tu alma lo abandona y entra en el contenedor que utilizaste para el componente material del hechizo. Mientras tu alma habita en el contenedor, eres consciente de tu entorno como si estuvieras en el espacio del contenedor. No puedes moverte ni usar reacciones. La única acción que puedes realizar es proyectar tu alma hasta 100 pies fuera del contenedor, ya sea regresando a tu cuerpo vivo (y terminando el hechizo) o intentando poseer un cuerpo humanoide.Puedes intentar poseer a cualquier humanoide a 100 pies de ti que puedas ver (las criaturas protegidas por un hechizo de protección contra el mal y el bien o círculo mágico no pueden ser poseídas). El objetivo debe realizar una tirada de salvación de Carisma. Si fallas, tu alma se traslada al cuerpo del objetivo y queda atrapada en el contenedor. Si tienes éxito, el objetivo se resiste a tus esfuerzos por poseerlo y no puedes intentar poseerlo de nuevo durante 24 horas.Una vez que posees el cuerpo de una criatura, la controlas. Tus estadísticas de juego son reemplazadas por las de la criatura, aunque conservas tu alineamiento y tus puntuaciones de Inteligencia, Sabiduría y Carisma. Conservas el beneficio de tus propios rasgos de clase. Si el objetivo tiene algún nivel de clase, no puedes utilizar ninguno de sus rasgos de clase.Mientras tanto, el alma de la criatura poseída puede percibir desde el contenedor utilizando sus propios sentidos, pero no puede moverse ni realizar ninguna acción.Mientras posees un cuerpo, puedes usar tu acción para volver del cuerpo anfitrión al contenedor si está a menos de 100 pies de ti, devolviendo el alma de la criatura anfitriona a su cuerpo. Si el cuerpo anfitrión muere mientras estás en él, la criatura muere, y debes hacer una tirada de salvación de carisma contra tu propia CD de lanzamiento de conjuros. Si tienes éxito, vuelves al contenedor si está a menos de 100 pies de ti. De lo contrario, mueres.Si el contenedor se destruye o el hechizo termina, tu alma vuelve inmediatamente a tu cuerpo. Si tu cuerpo está a más de 100 pies de ti o si tu cuerpo está muerto cuando intentas volver a él, mueres. Si el alma de otra criatura está en el contenedor cuando se destruye, el alma de la criatura vuelve a su cuerpo si el cuerpo está vivo y a menos de 100 pies. De lo contrario, esa criatura muere.Cuando el hechizo termina, el contenedor se destruye.', 'Hasta que se disipe', 'no', '1 minuto', 'Nivel 6', 'Personal', 'Mago', 'Nigromancia'),
(339, 'Sugerencia en masa (Mass Suggestion)', 'Sugieres un curso de actividad (limitado a una o dos frases) e influyes mágicamente en hasta doce criaturas de tu elección que puedas ver dentro de tu alcance y que puedan oírte y entenderte. Las criaturas que no pueden ser encantadas son inmunes a este efecto. La sugerencia debe estar redactada de tal manera que el curso de acción parezca razonable. Pedir a la criatura que se apuñale a sí misma, que se arroje a una lanza, que se inmolé o que realice cualquier otro acto obviamente dañino anula automáticamente el efecto del hechizo.Cada objetivo debe realizar una tirada de salvación de sabiduría. Si falla la tirada de salvación, sigue el curso de acción descrito lo mejor que puede. La acción sugerida puede continuar durante todo el hechizo. Si la actividad sugerida puede completarse en menos tiempo, el hechizo termina cuando el sujeto termina lo que se le pidió que hiciera.También puedes especificar condiciones que desencadenen una actividad especial durante la duración. Por ejemplo, puedes sugerir a un grupo de soldados que den todo su dinero al primer mendigo que encuentren. Si la condición no se cumple antes de que termine el hechizo, la actividad no se realiza.Si tú o cualquiera de tus compañeros dañáis a una criatura afectada por este hechizo, el hechizo termina para esa criatura.', '24 horas', 'no', '1 acción', 'Nivel 6', '60 pies', 'Bardo, Hechicero, Brujo, Mago', 'Encantamiento'),
(340, 'Mover tierra (Move Earth)', 'Elige un área de terreno de no más de 40 pies de lado dentro del alcance. Puedes remodelar la tierra, la arena o la arcilla de la zona de la forma que elijas mientras dure el efecto. Puedes subir o bajar la elevación de la zona, crear o rellenar una zanja, levantar o aplanar un muro o formar un pilar. La extensión de tales cambios no puede exceder la mitad de la dimensión mayor del área. Por tanto, si afecta a un cuadrado de 12 metros, puede crear un pilar de hasta 6 metros de altura, elevar o bajar la elevación del cuadrado hasta 6 metros, cavar una zanja de hasta 6 metros de profundidad, etcétera. Estos cambios tardan 10 minutos en completarse.Al final de cada 10 minutos que pases concentrado en el conjuro, puedes elegir una nueva área de terreno a la que afectar.Debido a que la transformación del terreno ocurre lentamente, las criaturas en el área no pueden ser atrapadas o heridas por el movimiento del terreno.Este hechizo no puede manipular piedra natural o construcciones de piedra. Las rocas y estructuras se desplazan para acomodarse al nuevo terreno. Si la forma que le das al terreno hace que una estructura sea inestable, podría derrumbarse.Del mismo modo, este hechizo no afecta directamente al crecimiento de las plantas. La tierra movida arrastra consigo cualquier planta.', 'Hasta 2 horas', 'si', '1 acción', 'Nivel 6', '120 pies', 'Druida, Hechicero, Mago', 'Transmutacion'),
(341, 'Esfera congelante de Otiluke (Otiluke\'s Freezing Sphere)', 'Un gélido globo de energía fría brota de las puntas de tus dedos hasta un punto de tu elección dentro del alcance, donde explota en una esfera de 60 pies de radio. Cada criatura dentro del área debe realizar una tirada de salvación de Constitución. Si falla, la criatura recibe 10d6 puntos de daño por frío. Si tiene éxito, recibe la mitad de daño.Si el globo golpea una masa de agua o un líquido que sea principalmente agua (sin incluir criaturas acuáticas), congela el líquido hasta una profundidad de 15 cm en un área de 9 metros cuadrados. Este hielo dura 1 minuto. Las criaturas que nadaban en la superficie del agua congelada quedan atrapadas en el hielo. Una criatura atrapada puede usar una acción para hacer un chequeo de Fuerza contra tu DC de salvación de hechizo para liberarse.Puedes abstenerte de disparar el globo después de completar el hechizo, si lo deseas. Un pequeño globo del tamaño de una piedra de honda, frío al tacto, aparece en tu mano. En cualquier momento, tú o una criatura a la que le des el globo podéis lanzarlo (a una distancia de 40 pies) o arrojarlo con una honda (a la distancia normal de la honda). Se rompe al impactar, con el mismo efecto que el lanzamiento normal del hechizo. También puedes dejar el globo en el suelo sin que se rompa. Al cabo de 1 minuto, si el globo no se ha hecho añicos, explota.', 'Instantaneo', 'no', '1 acción', 'Nivel 6', '300 pies', 'Mago', 'Evocacion'),
(342, 'Danza irresistible de Otto (Otto\'s Irresistible Dance)', 'Elige una criatura que puedas ver dentro del alcance. El objetivo comienza una danza cómica en su lugar: arrastrando los pies, golpeándolos y haciendo cabriolas mientras dure el hechizo. Las criaturas que no pueden ser encantadas son inmunes a este hechizo.Una criatura danzante debe utilizar todo su movimiento para bailar sin salir de su espacio y tiene desventaja en las tiradas de salvación de destreza y en las tiradas de ataque. Mientras el objetivo esté afectado por este hechizo, otras criaturas tienen ventaja en las tiradas de ataque contra él. Como acción, una criatura danzante hace una tirada de salvación de sabiduría para recuperar el control de sí misma. Si tiene éxito, el hechizo termina.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 6', '30 pies', 'Bardo, Mago, Lanzador de Rituales', 'Encantamiento'),
(343, 'Imagen permanente (Permanent Image)', 'Creas la imagen de un objeto, una criatura o algún otro fenómeno visible que no sea mayor que un cubo de 20 pies. La imagen aparece en un punto que puedas ver dentro del alcance y dura hasta que se disipa. Parece completamente real, incluyendo los sonidos, olores y temperatura apropiados al objeto representado. No puedes crear suficiente calor o frío como para causar daño, un sonido lo suficientemente fuerte como para causar daño por trueno o ensordecer a una criatura, o un olor que pueda enfermar a una criatura (como el hedor de un troglodita).Mientras estés dentro del alcance de la ilusión, puedes usar tu acción para hacer que la imagen se mueva a cualquier otro lugar dentro del alcance. A medida que la imagen cambia de lugar, puedes alterar su apariencia para que sus movimientos parezcan naturales para la imagen. Por ejemplo, si creas una imagen de una criatura y la mueves, puedes alterar la imagen para que parezca que camina. Del mismo modo, puedes hacer que la ilusión emita diferentes sonidos en diferentes momentos, incluso que mantenga una conversación, por ejemplo.La interacción física con la imagen revela que es una ilusión, porque las cosas pueden pasar a través de ella. Una criatura que utilice su acción para examinar la imagen puede determinar que se trata de una ilusión con un chequeo de Inteligencia (Investigación) con éxito contra su DC de salvación de conjuro. Si una criatura discierne la ilusión por lo que es, la criatura puede ver a través de la imagen, y sus otras cualidades sensoriales se vuelven débiles para la criatura.', 'Hasta que se disipe', 'no', '1 acción', 'Nivel 6', '120 pies', 'Bardo, Hechicero, Brujo, Mago', 'Ilusion');
INSERT INTO `conjuros` (`id_spell`, `name`, `descr`, `duracion`, `concentracion`, `casteo`, `level`, `rango`, `clases`, `escuela`) VALUES
(344, 'Aliado planar (Planar Ally)', 'Pides ayuda a una entidad de otro mundo. El ser debe ser conocido por ti: un dios, un primordial, un príncipe demonio o algún otro ser de poder cósmico. Esa entidad envía un celestial, un elemental o un demonio leal a ella para ayudarte, haciendo que la criatura aparezca en un espacio desocupado dentro de su alcance. Si conoces el nombre de una criatura específica, puedes pronunciar ese nombre cuando lances este conjuro para solicitar esa criatura, aunque puede que obtengas una criatura diferente de todos modos (a elección del DM).Cuando la criatura aparece, no está obligada a comportarse de ninguna manera en particular. Puedes pedir a la criatura que realice un servicio a cambio de un pago, pero no está obligada a hacerlo. La tarea solicitada puede ser sencilla (cruzar el abismo volando o ayudarnos a librar una batalla) o compleja (espiar a nuestros enemigos o protegernos durante nuestra incursión en la mazmorra). Debes poder comunicarte con la criatura para negociar sus servicios.El pago puede adoptar diversas formas. Un celestial puede exigir una donación considerable de oro u objetos mágicos a un templo aliado, mientras que un demonio puede exigir un sacrificio en vida o un regalo de tesoros. Algunas criaturas pueden intercambiar sus servicios por una misión que tú emprendas.Como regla general, una tarea que pueda medirse en minutos requiere un pago de 100 gp por minuto. Una tarea medida en horas requiere 1.000 gp por hora. Y una tarea medida en días (hasta 10 días) requiere 10.000 gp por día. El DM puede ajustar estos pagos basándose en las circunstancias en las que lanzas el hechizo. Si la tarea está alineada con el ethos de la criatura, el pago puede reducirse a la mitad o incluso eximirse. Las tareas no peligrosas suelen requerir sólo la mitad del pago sugerido, mientras que las tareas especialmente peligrosas pueden requerir un regalo mayor. Las criaturas rara vez aceptan tareas que parezcan suicidas.Después de que la criatura complete la tarea, o cuando expire la duración acordada del servicio, la criatura regresa a su plano de origen después de informarte, si es apropiado para la tarea y si es posible. Si no consigues acordar un precio por el servicio de la criatura, ésta regresa inmediatamente a su plano natal.Una criatura reclutada para unirse a tu grupo cuenta como miembro del mismo, recibiendo una parte completa de los puntos de experiencia otorgados.', 'Instantaneo', 'no', '10 minutos', 'Nivel 6', '60 pies', 'Clerigo', 'Conjuracion'),
(345, 'Protección primordial (Primordial Ward)', 'Tienes resistencia al daño de ácido, frío, fuego, relámpago y trueno mientras dure el hechizo.Cuando recibes daño de uno de esos tipos, puedes utilizar tu reacción para obtener inmunidad a ese tipo de daño, incluso contra el daño desencadenante. Si lo haces, las resistencias terminan y tienes la inmunidad hasta el final de tu siguiente turno, momento en el que termina el hechizo.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 6', 'Personal', 'Druida', 'Abjuracion'),
(346, 'Ilusión programada (Programmed Illusion)', 'Creas una ilusión de un objeto, una criatura o algún otro fenómeno visible dentro del alcance que se activa cuando se produce una condición específica. La ilusión es imperceptible hasta entonces. No debe ser mayor que un cubo de 30 pies, y tú decides cuando lanzas el conjuro cómo se comporta la ilusión y qué sonidos hace. Esta actuación guionizada puede durar hasta 5 minutos.Cuando se produce la condición que especifiques, la ilusión comienza a existir y actúa de la manera que has descrito. Una vez que la ilusión termina de actuar, desaparece y permanece inactiva durante 10 minutos. Transcurrido este tiempo, la ilusión puede activarse de nuevo.La condición desencadenante puede ser tan general o detallada como desees, aunque debe basarse en condiciones visuales o audibles que se produzcan a menos de 30 pies del área. Por ejemplo, puedes crear una ilusión de ti mismo para que aparezca y advierta a otros que intentan abrir una puerta atrapada, o puedes configurar la ilusión para que se active sólo cuando una criatura diga la palabra o frase correcta.La interacción física con la imagen revela que es una ilusión, porque las cosas pueden pasar a través de ella. Una criatura que use su acción para examinar la imagen puede determinar que es una ilusión con un chequeo exitoso de Inteligencia (Investigación) contra tu DC de salvación de conjuro. Si una criatura discierne la ilusión por lo que es, la criatura puede ver a través de la imagen, y cualquier ruido que haga suena hueco para la criatura.', 'Hasta que se disipe', 'no', '1 acción', 'Nivel 6', '120 pies', 'Bardo, Mago', 'Ilusion'),
(347, 'Rayo solar (Sunbeam)', 'Un rayo de luz brillante sale de tu mano en una línea de 5 pies de ancho y 60 pies de largo. Cada criatura de la línea debe realizar una tirada de salvación de Constitución. Si falla, la criatura recibe 6d8 puntos de daño radiante y queda cegada hasta tu próximo turno. Con una salvación exitosa, recibe la mitad de daño y no queda cegada por este hechizo. Los muertos vivientes y los excrementos tienen desventaja en esta tirada de salvación.Puedes crear una nueva línea de resplandor como acción en cualquier turno hasta que el hechizo termine.Mientras dure, una mota de brillante resplandor brilla en tu mano. Arroja luz brillante en un radio de 30 pies y luz tenue en un radio adicional de 30 pies. Esta luz es luz solar.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 6', 'Personal', 'Druida, Hechicero, Mago', 'Evocacion'),
(348, 'Transporte a través de plantas (Transport via Plants)', 'Este hechizo crea un vínculo mágico entre una planta inanimada Grande o mayor dentro del alcance y otra planta, a cualquier distancia, en el mismo plano de existencia. Debes haber visto o tocado la planta de destino al menos una vez antes. Mientras dure, cualquier criatura puede entrar en la planta objetivo y salir de la planta de destino utilizando 5 pies de movimiento.', '1 ronda', 'no', '1 acción', 'Nivel 6', '10 pies', 'Druida', 'Conjuracion'),
(349, 'Visión verdadera (True Seeing)', 'Este hechizo otorga a la criatura que toques la capacidad de ver las cosas como realmente son. Mientras dura, la criatura tiene visión verdadera, se da cuenta de las puertas secretas ocultas por magia y puede ver en el Plano Etéreo, todo ello a una distancia de 120 pies.', '1 hora', 'no', '1 acción', 'Nivel 6', 'Toque', 'Bardo, Clerigo, Hechicero, Brujo, Mago', 'Adivinacion'),
(350, 'Muro de hielo (Wall of Ice)', 'Creas un muro de hielo sobre una superficie sólida dentro de tu alcance. Puedes darle forma de cúpula semiesférica o de esfera con un radio de hasta 3 metros, o puedes formar una superficie plana compuesta por diez paneles de 3 metros cuadrados. Cada panel debe ser contiguo a otro panel. En cualquiera de sus formas, el muro tiene un grosor de 1 pie y dura lo que dura.Si el muro atraviesa el espacio de una criatura cuando aparece, la criatura dentro de su área es empujada hacia un lado del muro y debe hacer una tirada de salvación de destreza. Si falla la tirada de salvación, la criatura recibe 10d6 puntos de daño por frío, o la mitad de daño si la tirada de salvación tiene éxito.El muro es un objeto que puede ser dañado y, por tanto, atravesado. Tiene CA 12 y 30 puntos de vida por sección de 3 metros, y es vulnerable al daño por fuego. Reducir a 0 puntos de vida una sección de pared de 3 metros la destruye y deja tras de sí una capa de aire helado en el espacio que ocupaba la pared. Una criatura que se mueva a través de la capa de aire helado por primera vez en un turno debe realizar una tirada de salvación de Constitución. Esa criatura recibe 5d6 puntos de daño por frío si falla la tirada de salvación, o la mitad de daño si tiene éxito.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 6', '120 pies', 'Mago', 'Evocacion'),
(351, 'Muro de espinas (Wall of Thorns)', 'Creas un muro de maleza resistente, flexible y enmarañada, erizada de espinas afiladas como agujas. El muro aparece dentro del alcance de una superficie sólida y dura lo que dura el efecto. Puedes elegir entre crear un muro de hasta 60 pies de largo, 10 pies de alto y 5 pies de grosor o un círculo de 20 pies de diámetro y hasta 20 pies de alto y 5 pies de grosor. El muro bloquea la línea de visión.Cuando el muro aparece, cada criatura dentro de su área debe hacer una tirada de salvación de destreza. Si falla la tirada de salvación, la criatura recibe 7d8 puntos de daño perforante, o la mitad de daño si la tirada de salvación tiene éxito.Una criatura puede moverse a través del muro, aunque lenta y dolorosamente. Por cada pie que una criatura se desplaza a través del muro, debe gastar 4 pies de movimiento. Además, la primera vez que una criatura entra en el muro en un turno o termina su turno allí, la criatura debe realizar una tirada de salvación de destreza. Si falla la tirada de salvación, recibe 7d8 puntos de daño cortante, o la mitad de daño si tiene éxito.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 6', '120 pies', 'Druida', 'Conjuracion'),
(352, 'Caminar por el viento (Wind Walk)', 'Tú y hasta diez criaturas voluntarias que puedas ver dentro del alcance adoptáis una forma gaseosa durante el tiempo que dure el efecto, apareciendo como volutas de nube. Mientras está en esta forma de nube, la criatura tiene una velocidad de vuelo de 300 pies y tiene resistencia al daño de armas no mágicas. Las únicas acciones que una criatura puede llevar a cabo en esta forma son la acción de Dash o volver a su forma normal. La reversión dura 1 minuto, durante el cual la criatura queda incapacitada y no puede moverse. Hasta que el hechizo termine, una criatura puede volver a su forma de nube, que también requiere la transformación de 1 minuto.Si una criatura está en forma de nube y volando cuando finaliza el efecto, desciende 18 metros por asalto durante 1 minuto hasta que aterriza, lo que hace de forma segura. Si no puede aterrizar después de 1 minuto, la criatura cae la distancia restante.', '8 horas', 'no', '1 minuto', 'Nivel 6', '30 pies', 'Druida', 'Transmutacion'),
(353, 'Palabra de retorno', 'Tú y hasta cinco criaturas dispuestas en un radio de 1,5 m os teletransportáis instantáneamente a un santuario designado previamente. Tú y cualquier criatura que se teletransporte contigo aparecéis en el espacio desocupado más cercano al lugar que designaste cuando preparaste tu santuario (ver más abajo). Si lanzas este hechizo sin preparar primero un santuario, el hechizo no tiene efecto.Debes designar un santuario al lanzar este hechizo dentro de un lugar, como un templo, dedicado o fuertemente vinculado a tu deidad. Si intentas lanzar el hechizo de esta manera en un área que no está dedicada a tu deidad, el hechizo no tiene efecto.', 'Instantaneo', 'no', '1 acción', 'Nivel 6', '5 pies', 'Clerigo', 'Conjuracion'),
(354, 'Invocar celestial (Conjure Celestial)', 'Invocas a un celestial de nivel de desafío 4 o inferior, que aparece en un espacio desocupado que puedas ver dentro de su alcance. El celestial desaparece cuando baja a 0 puntos de golpe o cuando finaliza el hechizo.El celestial es amistoso contigo y tus compañeros mientras dure el hechizo. Tira iniciativa para el celestial, que tiene sus propios turnos. Obedece cualquier orden verbal que le des (no requiere ninguna acción por tu parte), siempre que no infrinja su alineamiento. Si no le das ninguna orden, se defiende de las criaturas hostiles, pero no realiza ninguna otra acción.El DM tiene las estadísticas del celestial.', 'Hasta 1 hora', 'si', '1 minuto', 'Nivel 7', '90 pies', 'Clérigo, Clerigo', 'Conjuracion'),
(355, 'Bola de fuego retardada (Delayed Blast Fireball)', 'Un haz de luz amarilla parpadea desde el dedo que apuntas y luego se condensa para permanecer en un punto elegido dentro del alcance como una perla incandescente mientras dure el hechizo. Cuando el hechizo termina, ya sea porque se rompe tu concentración o porque decides ponerle fin, la cuenta se convierte con un rugido grave en una explosión de llamas que se extiende por las esquinas. Cada criatura en una esfera de 20 pies de radio centrada en ese punto debe hacer una tirada de salvación de destreza. Una criatura recibe un daño de fuego igual al daño total acumulado en una tirada de salvación fallida, o la mitad de daño en una exitosa.El daño base del hechizo es de 12d6. Si al final de tu turno el abalorio aún no ha detonado, el daño aumenta en 1d6.Si se toca el abalorio incandescente antes de que expire el intervalo, la criatura que lo toque debe realizar una tirada de salvación de destreza. Si falla la tirada de salvación, el hechizo termina inmediatamente y el abalorio estalla en llamas. Si la salvación tiene éxito, la criatura puede lanzar el abalorio hasta 40 pies. Cuando golpea a una criatura o a un objeto sólido, el hechizo termina y el abalorio explota.El fuego daña los objetos de la zona y enciende los objetos inflamables que no se lleven puestos.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 7', '150 pies', 'Hechicero, Mago, Lanzador de Rituales', 'Evocacion'),
(356, 'Palabra divina (Divine Word)', 'Pronuncias una palabra de Dios, llena del poder que ha dado forma al mundo en los albores de la creación. Elige tantas criaturas como quieras de entre las que veas, dentro del alcance del hechizo. Cada criatura que te escuche debe hacer una reserva de Carisma, o sufre un efecto basado en el valor actual de su vida.- pv o menos 50: silenciado durante 1 minuto- 40 hp o menos: ensordecido y cegado durante 10 minutos- 30 CV o menos: cegado, ensordecido y aturdido durante 1 hora- 20 CV o menos: muerte instantáneaIndependientemente de sus puntos de vida actuales, un celestial, un elemental, un hada o un demonio que falle su tirada es devuelto a su plan original (si no lo estaba ya) y no puede volver sobre su plan durante 24 horas, sea cual sea el medio, a excepción del hechizo de deseo.', 'Instantaneo', 'no', '1 acción adicional', 'Nivel 7', '30 pies', 'Clerigo', 'Evocacion'),
(357, 'Eterealidad (Etherealness)', 'Entras en las regiones fronterizas del Plano Etéreo, en la zona donde se solapa con tu plano actual. Permaneces en la Frontera Etérea mientras dure el hechizo o hasta que uses tu acción para desecharlo. Durante este tiempo, puedes moverte en cualquier dirección. Si te mueves hacia arriba o hacia abajo, cada pie de movimiento cuesta un pie extra. Puedes ver y oír el plano del que procedes, pero todo allí parece gris, y no puedes ver nada a más de 60 pies de distancia.Mientras estás en el Plano Etéreo, sólo puedes afectar y ser afectado por otras criaturas de ese plano. Las criaturas que no están en el Plano Etéreo no pueden percibirte ni interactuar contigo, a menos que una habilidad especial o magia les haya dado la capacidad de hacerlo.Ignoras todos los objetos y efectos que no estén en el Plano Etéreo, lo que te permite moverte por los objetos que percibes en el plano del que procedes.Cuando el hechizo termina, vuelves inmediatamente al plano del que procedes en el lugar que ocupas en ese momento. Si ocupas el mismo lugar que un objeto sólido o criatura cuando esto ocurre, eres inmediatamente desplazado al espacio desocupado más cercano que puedas ocupar y recibes un daño de fuerza igual al doble del número de pies que eres desplazado.Este hechizo no tiene efecto si lo lanzas mientras estás en el Plano Etéreo o en un plano que no limita con él, como uno de los Planos Exteriores.', '8 horas', 'no', '1 acción', 'Nivel 7', 'Personal', 'Bardo, Clerigo, Hechicero, Brujo, Mago', 'Transmutacion'),
(358, 'Dedo de la muerte (Finger of Death)', 'Envías energía negativa a una criatura que puedas ver dentro de tu alcance, causándole un dolor abrasador. El objetivo debe realizar una tirada de salvación de Constitución. Si falla la tirada de salvación, recibe 7d8 + 30 puntos de daño necrótico, o la mitad si tiene éxito.Un humanoide muerto por este hechizo se levanta al comienzo de tu siguiente turno como un zombi que está permanentemente bajo tu mando, siguiendo tus órdenes verbales lo mejor que puede.', 'Instantaneo', 'no', '1 acción', 'Nivel 7', '60 pies', 'Hechicero, Brujo, Mago', 'Nigromancia'),
(359, 'Tormenta de fuego (Fire Storm)', 'Una tormenta formada por láminas de llamas rugientes aparece en un lugar que elijas dentro del alcance. El área de la tormenta está formada por un máximo de diez cubos de 3 metros, que puedes colocar como quieras. Cada cubo debe tener al menos una cara adyacente a la cara de otro cubo. Cada criatura en el área debe hacer una tirada de salvación de destreza. Recibe 7d10 puntos de daño por fuego si falla la tirada de salvación, o la mitad de daño si tiene éxito.El fuego daña los objetos de la zona y enciende los objetos inflamables que no se lleven puestos. Si lo eliges, la vida vegetal de la zona no se ve afectada por este hechizo.', 'Instantaneo', 'no', '1 acción', 'Nivel 7', '150 pies', 'Clerigo, Druida, Hechicero', 'Evocacion'),
(360, 'Jaula de fuerza (Forcecage)', 'Una prisión inmóvil, invisible y con forma de cubo compuesta de fuerza mágica surge alrededor de un área que elijas dentro de su alcance. La prisión puede ser una jaula o una caja sólida, a tu elección.Una prisión en forma de jaula puede tener hasta 20 pies de lado y está hecha de barras de 1/2 pulgada de diámetro separadas 1/2 pulgada. Una prisión en forma de caja puede tener hasta 10 pies de lado, creando una barrera sólida que impide que cualquier materia pase a través de ella y bloquea cualquier conjuro lanzado dentro o fuera del área.Cuando lanzas el conjuro, cualquier criatura que esté completamente dentro del área de la jaula queda atrapada. Las criaturas que se encuentren sólo parcialmente dentro del área, o las que sean demasiado grandes para caber dentro de ella, son empujadas lejos del centro del área hasta que estén completamente fuera de ella.Una criatura dentro de la jaula no puede salir de ella por medios no mágicos. Si la criatura intenta utilizar el teletransporte o el viaje interplanar para salir de la jaula, primero debe realizar una tirada de salvación de carisma. Si tiene éxito, la criatura puede usar esa magia para salir de la jaula. Si falla, la criatura no puede salir de la jaula y pierde el uso del hechizo o efecto. La jaula también se extiende al Plano Etéreo, bloqueando el viaje etéreo.Este hechizo no se puede disipar con magia de disipación.', '1 hora', 'no', '1 acción', 'Nivel 7', '100 pies', 'Bardo, Brujo, Mago', 'Evocacion'),
(361, 'Espejismo arcano (Mirage Arcane)', 'Haces que el terreno de un área de hasta 1 milla cuadrada parezca, suene, huela e incluso se sienta como otro tipo de terreno. Sin embargo, la forma general del terreno sigue siendo la misma. Un campo abierto o una carretera pueden parecerse a un pantano, una colina, una grieta o cualquier otro terreno difícil o infranqueable. Un estanque puede parecerse a un prado cubierto de hierba, un precipicio a una suave pendiente o un barranco cubierto de rocas a un camino ancho y liso.Del mismo modo, puedes alterar el aspecto de las estructuras o añadirlas donde no las haya. El hechizo no disfraza, oculta ni añade criaturas.La ilusión incluye elementos audibles, visuales, táctiles y olfativos, por lo que puede convertir un terreno despejado en terreno difícil (o viceversa) o impedir de cualquier otro modo el movimiento por la zona. Cualquier trozo del terreno ilusorio (como una roca o un palo) que se retire del área del hechizo desaparece inmediatamente.Las criaturas con visión verdadera pueden ver a través de la ilusión la forma real del terreno; sin embargo, todos los demás elementos de la ilusión permanecen, por lo que aunque la criatura sea consciente de la presencia de la ilusión, aún puede interactuar físicamente con ella.', '10 days', 'no', '10 minutos', 'Nivel 7', 'Sight', 'Bardo, Druida, Mago', 'Ilusion'),
(362, 'Mansión magnífica de Mordenkainen (Mordenkainen\'s Magnificent Mansion)', 'Conjuras una morada extradimensional a tu alcance que dura lo que dura. Eliges dónde se encuentra su única entrada. La entrada brilla débilmente y mide 5 pies de ancho y 10 pies de alto. Tú y cualquier criatura que designes al lanzar el conjuro podéis entrar en la morada extradimensional mientras el portal permanezca abierto. Puedes abrir o cerrar el portal si te encuentras a menos de 30 pies de él. Mientras está cerrado, el portal es invisible.Más allá del portal hay un magnífico vestíbulo con numerosas cámaras. El ambiente es limpio, fresco y cálido.Puedes crear el plano que quieras, pero el espacio no puede exceder los 50 cubos, cada cubo de 3 metros de lado. El local está amueblado y decorado como tú elijas. Contiene comida suficiente para servir un banquete de nueve platos para un máximo de 100 personas. Un personal de 100 sirvientes casi transparentes atiende a todos los que entran. Tú decides la apariencia visual de estos sirvientes y su atuendo. Son completamente obedientes a tus órdenes. Cada sirviente puede realizar cualquier tarea que pueda realizar un sirviente humano normal, pero no pueden atacar ni realizar ninguna acción que pueda dañar directamente a otra criatura. Así, los criados pueden ir a buscar cosas, limpiar, remendar, doblar ropa, encender fuego, servir comida, servir vino, etcétera. Los criados pueden ir a cualquier parte de la mansión, pero no pueden salir de ella. Los muebles y otros objetos creados por este hechizo se disipan en humo si se sacan de la mansión. Cuando el hechizo termina, cualquier criatura que se encuentre dentro del espacio extradimensional es expulsada a los espacios abiertos más cercanos a la entrada.', '24 horas', 'no', '1 minuto', 'Nivel 7', '300 pies', 'Bardo, Mago', 'Conjuracion'),
(363, 'Espada de Mordenkainen (Mordenkainen\'s Sword)', 'Creas un plano de fuerza en forma de espada que flota dentro de tu alcance. Dura lo que dura.Cuando la espada aparece, realizas un ataque de conjuro cuerpo a cuerpo contra un objetivo de tu elección a menos de 1,5 m de la espada. Si aciertas, el objetivo recibe 3d10 puntos de daño de fuerza. Hasta que el hechizo termine, puedes usar una acción de bonificación en cada uno de tus turnos para mover la espada hasta 20 pies a un punto que puedas ver y repetir este ataque contra el mismo objetivo o uno diferente.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 7', '60 pies', 'Bardo, Mago', 'Evocacion'),
(364, 'Cambio de plano (Plane Shift)', 'Tú y hasta ocho criaturas dispuestas que enlazan sus manos formando un círculo sois transportados a un plano de existencia diferente. Puedes especificar un destino en términos generales, como la Ciudad de Bronce en el Plano Elemental del Fuego o el palacio de Dispater en el segundo nivel de los Nueve Infiernos, y apareces en ese destino o cerca de él. Si estás intentando llegar a la Ciudad de Bronce, por ejemplo, podrías llegar a su Calle de Acero, antes de su Puerta de Cenizas, o mirando la ciudad desde el otro lado del Mar de Fuego, a discreción del DM.Alternativamente, si conoces la secuencia de sigilos de un círculo de teletransportación en otro plano de existencia, este hechizo puede llevarte a ese círculo. Si el círculo de teletransportación es demasiado pequeño para contener a todas las criaturas que transportaste, éstas aparecen en los espacios desocupados más cercanos al círculo.Puedes utilizar este hechizo para desterrar a otro plano a una criatura que no lo desee. Elige una criatura a tu alcance y realiza un ataque de conjuro cuerpo a cuerpo contra ella. Si impacta, la criatura debe realizar una tirada de salvación de Carisma. Si la criatura falla la tirada de salvación, es transportada a una ubicación aleatoria en el plano de existencia que especifiques. Una criatura así transportada debe encontrar su propio camino de vuelta a tu plano de existencia actual.', 'Instantaneo', 'no', '1 acción', 'Nivel 7', 'Toque', 'Clerigo, Hechicero, Brujo, Mago', 'Conjuracion'),
(365, 'Rociada prismática (Prismatic Spray)', 'De tu mano parpadean ocho rayos de luz multicolor. Cada rayo es de un color diferente y tiene un poder y un propósito distintos. Cada criatura en un cono de 18 metros debe realizar una tirada de salvación de destreza. Por cada objetivo, tira un d8 para determinar qué rayo de color le afecta.<b>1. 1. Rojo.</b> El objetivo recibe 10d6 de daño por fuego si falla la tirada de salvación, o la mitad de daño si tiene éxito.<b>2. 2. Naranja.</b> El objetivo recibe 10d6 puntos de daño por ácido si falla la salvación, o la mitad si tiene éxito.<b>3. Amarillo.</b> El objetivo recibe 10d6 de daño de rayo si falla la salvación, o la mitad de daño si la salva.<b>4. Verde.</b> El objetivo recibe 10d6 de daño de veneno si falla la salvación, o la mitad de daño si la salva.<b>5. Azul.</b> El objetivo recibe 10d6 puntos de daño por frío si falla la salvación, o la mitad si tiene éxito.<b>6. Índigo.</b> Si falla la salvación, el objetivo queda inmovilizado. Debe realizar una tirada de salvación de constitución al final de cada turno. Si salva tres veces, el hechizo termina. Si falla la salvación tres veces, se convierte permanentemente en piedra y sufre la condición de petrificado. Los éxitos y fracasos no tienen por qué ser consecutivos; lleva la cuenta de ambos hasta que el objetivo consiga tres iguales.<b>7. Violeta.</b> Si falla la tirada de salvación, el objetivo queda cegado. Debe realizar una tirada de salvación de sabiduría al comienzo de tu siguiente turno. Una salvación con éxito acaba con la ceguera. Si falla la tirada de salvación, la criatura es transportada a otro plano de existencia a elección del DM y deja de estar cegada. (Normalmente, una criatura que se encuentra en un plano que no es su plano natal es desterrada a su hogar, mientras que otras criaturas suelen ser lanzadas a los planos Astral o Etéreo).<b>8. Especial.</b> El objetivo es alcanzado por dos rayos. Tira dos veces más, repitiendo cualquier 8.', 'Instantaneo', 'no', '1 acción', 'Nivel 7', 'Personal', 'Hechicero, Mago', 'Evocacion'),
(366, 'Imagen proyectada (Project Image)', 'Creas una copia ilusoria de ti mismo que dura lo que dura el efecto. La copia puede aparecer en cualquier lugar dentro del alcance que hayas visto antes, independientemente de los obstáculos que se interpongan. La ilusión parece y suena como tú, pero es intangible. Si la ilusión recibe algún daño, desaparece y el hechizo termina.Puedes usar tu acción para mover esta ilusión hasta el doble de tu velocidad, y hacer que gesticule, hable y se comporte de la forma que elijas. Imita tus gestos a la perfección.Puedes ver a través de sus ojos y oír a través de sus oídos como si estuvieras en su espacio. En tu turno, como acción adicional, puedes pasar de utilizar sus sentidos a utilizar los tuyos propios, o viceversa. Mientras utilizas sus sentidos, estás cegado y ensordecido con respecto a tu propio entorno.La interacción física con la imagen revela que es una ilusión, porque las cosas pueden pasar a través de ella. Una criatura que use su acción para examinar la imagen puede determinar que es una ilusión con un chequeo de Inteligencia (Investigación) con éxito contra tu DC de salvación de conjuro. Si una criatura discierne la ilusión por lo que es, la criatura puede ver a través de la imagen, y cualquier ruido que haga suena hueco para la criatura.', 'Hasta 24 horas', 'si', '1 acción', 'Nivel 7', '500 miles', 'Bardo, Mago', 'Ilusion'),
(367, 'Regenerar (Regenerate)', 'Tocas a una criatura y estimulas su capacidad curativa natural. El objetivo recupera 4d8 + 15 puntos de golpe. Mientras dure el hechizo, el objetivo recupera 1 punto de golpe al comienzo de cada uno de sus turnos (10 puntos de golpe cada minuto).Los miembros cercenados del cuerpo del objetivo (dedos, piernas, colas, etc.), si los hay, se recuperan al cabo de 2 minutos. Si tienes la parte cercenada y la sujetas al muñón, el hechizo provoca instantáneamente que el miembro se una al muñón.', '1 hora', 'no', '1 minuto', 'Nivel 7', 'Toque', 'Bardo, Clerigo, Druida', 'Transmutacion'),
(368, 'Resurrección verdadera (True Resurrection)', 'Tocas a una criatura muerta que no lleve más de un siglo muerta, que no haya muerto de vejez y que no sea un muerto viviente. Si su alma está libre y dispuesta, el objetivo vuelve a la vida con todos sus puntos de vida.Este hechizo neutraliza cualquier veneno y cura las enfermedades normales que afligían a la criatura cuando murió. Sin embargo, no elimina enfermedades mágicas, maldiciones y similares; si tales efectos no se eliminan antes de lanzar el conjuro, afligen al objetivo en su vuelta a la vida.Este hechizo cierra todas las heridas mortales y restaura cualquier parte del cuerpo que falte.Regresar de la muerte es un calvario. El objetivo sufre un penalizador de -4 a todas las tiradas de ataque, tiradas de salvación y chequeos de habilidad. Cada vez que el objetivo termina un descanso largo, el penalizador se reduce en 1 hasta que desaparece.Lanzar este conjuro para devolver la vida a una criatura que lleva muerta un año o más te supone un gran esfuerzo. Hasta que no termines un descanso largo, no puedes volver a lanzar conjuros y tienes desventaja en todas las tiradas de ataque, chequeos de habilidad y tiradas de salvación.', 'Instantaneo', 'no', '1 hora', 'Nivel 7', 'Toque', 'Bardo, Clerigo', 'Nigromancia'),
(369, '... (continúa)', 'Este hechizo invierte la gravedad en un cilindro de 50 pies de radio y 100 pies de altura centrado en un punto dentro del alcance. Todas las criaturas y objetos que no estén anclados al suelo en el área caen hacia arriba y alcanzan la parte superior del área cuando lanzas este conjuro. Una criatura puede hacer una tirada de salvación de destreza para agarrarse a un objeto fijo que pueda alcanzar, evitando así la caída.Si en esta caída se encuentra algún objeto sólido (como un techo), los objetos y criaturas que caen lo golpean igual que lo harían durante una caída normal hacia abajo. Si un objeto o criatura alcanza la parte superior del área sin golpear nada, permanece allí, oscilando ligeramente, durante el tiempo de duración.Al final de la duración, los objetos y criaturas afectados vuelven a caer.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 7', '100 pies', 'Druida, Hechicero, Mago', 'Transmutacion'),
(370, 'Secuestrar (Sequester)', 'Mediante este hechizo, una criatura o un objeto puede ocultarse, a salvo de ser detectado mientras dure el hechizo. Cuando lanzas el conjuro y tocas al objetivo, éste se vuelve invisible y no puede ser objeto de conjuros de adivinación ni percibido a través de sensores de adivinación creados por conjuros de adivinación.Si el objetivo es una criatura, entra en un estado de animación suspendida. El tiempo deja de fluir para él y no envejece.Puedes establecer una condición para que el hechizo termine antes. La condición puede ser cualquier cosa que elijas, pero debe ocurrir o ser visible en un radio de 1 milla del objetivo. Algunos ejemplos son \"después de 1.000 años\" o \"cuando la tarrasca despierte\". Este hechizo también termina si el objetivo recibe algún daño.', 'Hasta que se disipe', 'no', '1 acción', 'Nivel 7', 'Toque', 'Mago', 'Transmutacion'),
(371, 'Simulacro (Simulacrum)', 'Formas un duplicado ilusorio de una bestia o humanoide que esté dentro del alcance durante todo el tiempo de lanzamiento del hechizo. El duplicado es una criatura, parcialmente real y formada de hielo o nieve, y puede realizar acciones y verse afectada como una criatura normal. Parece ser igual que el original, pero tiene la mitad de los puntos de vida máximos de la criatura y está formado sin equipo. Por lo demás, la ilusión utiliza todas las estadísticas de la criatura que duplica.El simulacro es amistoso contigo y con las criaturas que designes. Obedece tus órdenes habladas, moviéndose y actuando de acuerdo con tus deseos y actuando en tu turno en combate. El simulacro carece de la capacidad de aprender o hacerse más poderoso, por lo que nunca aumenta su nivel u otras habilidades, ni puede recuperar las ranuras de hechizo gastadas.Si el simulacro resulta dañado, puedes repararlo en un laboratorio alquímico, utilizando hierbas raras y minerales por valor de 100 gp por punto de golpe que recupere. El simulacro dura hasta que baja a 0 puntos de vida, momento en el que se convierte en nieve y se derrite al instante.Si vuelves a lanzar este hechizo, los duplicados activos que hayas creado con él se destruyen al instante.', 'Hasta que se disipe', 'no', '12 horas', 'Nivel 7', 'Toque', 'Mago', 'Ilusion'),
(372, 'Símbolo (Symbol)', 'Cuando lanzas este conjuro, inscribes un glifo dañino en una superficie (como una sección del suelo, una pared o una mesa) o dentro de un objeto que pueda cerrarse para ocultar el glifo (como un libro, un pergamino o un cofre del tesoro). Si eliges una superficie, el glifo puede cubrir un área de la superficie no mayor de 3 metros de diámetro. Si eliges un objeto, ese objeto debe permanecer en su lugar; si el objeto se mueve más de 10 pies desde donde lanzas este hechizo, el glifo se rompe, y el hechizo termina sin activarse.El glifo es casi invisible y requiere un chequeo de Inteligencia (Investigación) contra tu DC de salvación para encontrarlo.Tú decides qué activa el glifo cuando lanzas el hechizo. Para los glifos inscritos en una superficie, los desencadenantes más típicos incluyen tocar o pisar el glifo, retirar otro objeto que lo cubra, acercarse a cierta distancia de él o manipular el objeto que lo sostiene. En el caso de los glifos inscritos dentro de un objeto, los desencadenantes más habituales son abrir el objeto, acercarse a cierta distancia de él o ver o leer el glifo.Puedes refinar aún más el desencadenante para que el hechizo se active sólo en determinadas circunstancias o en función de las características físicas de una criatura (como la altura o el peso), o de su tipo físico (por ejemplo, la protección podría establecerse para afectar a las brujas o a los cambiaformas). También puedes especificar criaturas que no activen el glifo, como las que digan una contraseña determinada.Cuando inscribas el glifo, elige una de las opciones siguientes para su efecto. Una vez activado, el glifo brilla, llenando de luz tenue una esfera de 60 pies de radio durante 10 minutos, transcurridos los cuales el hechizo finaliza. Cada criatura en la esfera cuando el glifo se activa es objetivo de su efecto, al igual que una criatura que entra en la esfera por primera vez en un turno o termina su turno allí. <b>Muerte.</b> Cada objetivo debe realizar una tirada de salvación de constitución, recibiendo 10d 10 de daño necrótico en caso de fallar la salvación, o la mitad de daño en caso de tener éxito.<b>Discordia.</b> Cada objetivo debe realizar una tirada de salvación de Constitución. Si falla la tirada de salvación, el objetivo discute con otras criaturas durante 1 minuto. Durante este tiempo, es incapaz de comunicarse de forma significativa y tiene desventaja en las tiradas de ataque y los chequeos de habilidad.<b>Miedo.</b> Cada objetivo debe realizar una tirada de salvación de sabiduría y se asusta durante 1 minuto si falla la salvación. Mientras está asustado, el objetivo suelta lo que tenga en la mano y debe alejarse al menos 9 metros del glifo en cada uno de sus turnos, si puede.<b>Desesperanza.</b> Cada objetivo debe realizar una tirada de salvación de Carisma. Si falla, el objetivo queda abrumado por la desesperación durante 1 minuto. Durante este tiempo, no puede atacar ni apuntar a ninguna criatura con habilidades dañinas, hechizos u otros efectos mágicos.<b>Locura.</b> Cada objetivo debe realizar una tirada de salvación de inteligencia. Si falla la tirada de salvación, el objetivo enloquece durante 1 minuto. Una criatura demente no puede realizar acciones, no puede entender lo que dicen otras criaturas, no puede leer y sólo habla en galimatías. El DM controla su movimiento, que es errático.<b>Dolor.</b> Cada objetivo debe hacer una tirada de salvación de constitución y queda incapacitado con un dolor insoportable durante 1 minuto si falla la tirada de salvación.<b>Sueño.</b> Cada objetivo debe hacer una tirada de salvación de sabiduría y cae inconsciente durante 10 minutos si falla la salvación. La criatura despierta si recibe daño o si alguien utiliza una acción para sacudirla o abofetearla.<b>Aturdimiento.</b> Cada objetivo debe realizar una tirada de salvación de sabiduría y queda aturdido durante 1 minuto si falla la salvación.', 'Hasta que se disipe', 'no', '1 minuto', 'Nivel 7', 'Toque', 'Bardo, Clerigo, Mago', 'Abjuracion'),
(373, 'Teletransporte (Teleport)', 'Este conjuro te transporta instantáneamente a ti y hasta ocho criaturas voluntarias de tu elección que puedas ver dentro del alcance, o un único objeto que puedas ver dentro del alcance, a un destino que selecciones. Si eliges como objetivo un objeto, éste debe caber por completo dentro de un cubo de 3 metros y no puede ser sujetado o transportado por una criatura involuntaria.El destino que elijas debe ser conocido por ti, y debe estar en el mismo plano de existencia que tú. Tu familiaridad con el destino determina si llegas allí con éxito. El DM tira d100 y consulta la tabla.', 'Instantaneo', 'no', '1 acción', 'Nivel 7', '10 pies', 'Bardo, Hechicero, Mago', 'Conjuracion'),
(374, 'Torbellino (Whirlwind)', 'Un torbellino aúlla hasta un punto del suelo que especifiques. El torbellino es un cilindro de 10 pies de radio y 30 pies de altura centrado en ese punto. Hasta que el hechizo termine, puedes usar tu acción para mover el torbellino hasta 30 pies en cualquier dirección a lo largo del suelo. El torbellino succiona cualquier objeto mediano o más pequeño que no esté sujeto a nada y que no lleve puesto o cargue nadie.Una criatura debe realizar una tirada de salvación de Destreza la primera vez en un turno que entre en el torbellino o que el torbellino entre en su espacio, incluyendo cuando el torbellino aparece por primera vez. Una criatura recibe 10d6 puntos de daño contundente si falla la tirada de salvación, o la mitad de daño si tiene éxito. Además, una criatura Grande o más pequeña que falle la salvación debe tener éxito en una tirada de salvación de Fuerza o quedar atrapada en el torbellino hasta que el conjuro termine. Cuando una criatura comienza su turno retenida por el torbellino, la criatura es arrastrada 5 pies más arriba dentro de él, a menos que la criatura esté en la parte superior. Una criatura retenida se mueve con el torbellino y cae cuando el hechizo termina, a menos que la criatura tenga algún medio para mantenerse en el aire.Una criatura retenida puede usar una acción para hacer un chequeo de Fuerza o Destreza contra la DC de salvación de tu hechizo. Si tiene éxito, la criatura deja de estar retenida por el torbellino y es lanzada a 3d6 x 10 pies de distancia en una dirección aleatoria.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 7', '300 pies', 'Druida, Mago', 'Evocacion'),
(375, 'Marchitamiento horrendo de Abi-Dalzim (Abi-Dalzim\'s Horrid Wilting)', 'Extraes la humedad de cada criatura en un cubo de 30 pies centrado en un punto que elijas dentro del alcance. Cada criatura de esa área debe realizar una tirada de salvación de Constitución. Los constructos y los muertos vivientes no se ven afectados, y las plantas y los elementales de agua realizan esta tirada de salvación con desventaja. Una criatura recibe 10d8 puntos de daño necrótico si falla la tirada de salvación, o la mitad de daño si tiene éxito.Lanzas una burbuja de ácido. Elige una criatura dentro del alcance, o elige dos criaturas dentro del alcance que estén a menos de 5 pies la una de la otra. El objetivo debe tener éxito en una tirada de salvación de Destreza o recibir 1d6 puntos de daño por ácido.El daño de este conjuro aumenta en 1d6 cuando alcanzas el 5º nivel (2d6), 11º nivel (3d6) y 17º nivel (4d6).', 'Instantaneo', 'no', '1 acción', 'Nivel 8', '150 pies', 'Hechicero, Mago, Lanzador de Rituales', 'Nigromancia'),
(376, 'Formas animales (Animal Shapes)', 'Tu magia convierte a los demás en bestias. Elige cualquier número de criaturas dispuestas que puedas ver dentro de tu alcance. Transformas a cada objetivo en una bestia grande o más pequeña con un valor de desafío de 4 o inferior. En turnos posteriores, puedes utilizar tu acción para transformar a las criaturas afectadas en nuevas formas.La transformación dura lo que dure cada objetivo, o hasta que el objetivo pierda 0 puntos de vida o muera. Puedes elegir una forma diferente para cada objetivo. Las estadísticas de juego de un objetivo se sustituyen por las estadísticas de la bestia elegida, aunque el objetivo conserva su alineamiento y sus puntuaciones de Inteligencia, Sabiduría y Carisma. El objetivo asume los puntos de golpe de su nueva forma, y cuando vuelve a su forma normal, recupera el número de puntos de golpe que tenía antes de transformarse. Si revierte como resultado de una caída a 0 puntos de golpe, cualquier exceso de daño se traslada a su forma normal. Mientras el exceso de daño no reduzca la forma normal de la criatura a 0 puntos de vida, no queda inconsciente. La criatura está limitada en las acciones que puede realizar por la naturaleza de su nueva forma, y no puede hablar ni lanzar hechizos.El equipo del objetivo se funde con su nueva forma. El objetivo no puede activar, empuñar ni beneficiarse de ninguna otra forma de su equipo.', 'Hasta 24 horas', 'si', '1 acción', 'Nivel 8', '30 pies', 'Druida', 'Transmutacion'),
(377, 'Campo antimagia (Antimagic Field)', 'Una esfera invisible de antimagia de 3 metros de radio te rodea. Esta zona está separada de la energía mágica que inunda el multiverso. Dentro de la esfera, no se pueden lanzar hechizos, las criaturas invocadas desaparecen e incluso los objetos mágicos se vuelven mundanos. Hasta que el hechizo termina, la esfera se mueve contigo, centrada en ti.Los conjuros y otros efectos mágicos, excepto los creados por un artefacto o una deidad, se suprimen en la esfera y no pueden sobresalir de ella. Una ranura gastada para lanzar un hechizo suprimido se consume. Mientras un efecto está suprimido, no funciona, pero el tiempo que pasa suprimido cuenta contra su duración.Efectos dirigidos. Los hechizos y otros efectos mágicos, como proyectil mágico y encantar persona, que tienen como objetivo una criatura o un objeto de la esfera no tienen efecto sobre ese objetivo.Áreas de Magia. El área de otro hechizo o efecto mágico, como bola de fuego, no puede extenderse dentro de la esfera. Si la esfera se superpone a un área de magia, la parte del área que está cubierta por la esfera se suprime. Por ejemplo, las llamas creadas por un muro de fuego se suprimen dentro de la esfera, creando un hueco en el muro si el solapamiento es lo suficientemente grande.Conjuros. Cualquier hechizo activo u otro efecto mágico sobre una criatura u objeto en la esfera se suprime mientras la criatura u objeto se encuentre en ella.Objetos mágicos. Las propiedades y poderes de los objetos mágicos se suprimen en la esfera. Por ejemplo, una espada larga +1 en la esfera funciona como una espada larga no mágica.Las propiedades y poderes de un arma mágica se suprimen si se usa contra un objetivo en la esfera o si la empuña un atacante en la esfera. Si un arma mágica o una pieza de munición mágica sale completamente de la esfera (por ejemplo, si disparas una flecha mágica o lanzas una lanza mágica a un objetivo fuera de la esfera), la magia del objeto deja de estar suprimida en cuanto sale.Viaje mágico. El teletransporte y los viajes planares no funcionan en la esfera, tanto si ésta es el destino como el punto de partida de dichos viajes mágicos. Un portal a otro lugar, mundo o plano de existencia, así como una abertura a un espacio extradimensional como la creada por el conjuro truco de la cuerda, se cierra temporalmente mientras se está en la esfera.Criaturas y objetos. Una criatura u objeto invocado o creado por magia desaparece temporalmente de la esfera. Dicha criatura reaparece instantáneamente una vez que el espacio que ocupaba la criatura ya no se encuentra dentro de la esfera.Disipar Magia. Los hechizos y efectos mágicos como disipar magia no tienen efecto sobre la esfera. Del mismo modo, las esferas creadas por diferentes hechizos de campo antimagia no se anulan entre sí.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 8', 'Personal', 'Clérigo, Clerigo, Mago, Lanzador de Rituales', 'Abjuracion'),
(378, 'Antipatía/Simpatía (Antipathy/Sympathy)', 'Este hechizo atrae o repele criaturas de tu elección. Apuntas a algo dentro del alcance, ya sea un objeto o criatura Enorme o menor o un área que no sea mayor que un cubo de 200 pies. Luego especifica un tipo de criatura inteligente, como dragones rojos, trasgos o vampiros. Invistes al objetivo con un aura que atrae o repele a las criaturas especificadas mientras dure el efecto. Elige antipatía o simpatía como efecto del aura.<b>Antipatía.</b> El encantamiento provoca que las criaturas del tipo que hayas designado sientan una intensa necesidad de abandonar la zona y evitar el objetivo. Cuando una criatura de este tipo puede ver al objetivo o se acerca a menos de 60 pies de él, debe tener éxito en una tirada de salvación de sabiduría o asustarse. La criatura permanece asustada mientras pueda ver al objetivo o esté a menos de 60 pies de él. Mientras esté asustada por el objetivo, la criatura debe usar su movimiento para moverse al punto seguro más cercano desde el que no pueda ver al objetivo. Si la criatura se mueve a más de 60 pies del objetivo y no puede verlo, la criatura deja de estar asustada, pero la criatura vuelve a estar asustada si recupera la vista del objetivo o se mueve a menos de 60 pies de él.<b>Simpatía.</b> El encantamiento hace que las criaturas especificadas sientan un intenso impulso de acercarse al objetivo mientras se encuentren a 60 pies de él o puedan verlo. Cuando dicha criatura pueda ver al objetivo o se acerque a menos de 60 pies de él, la criatura debe tener éxito en una tirada de salvación de sabiduría o utilizar su movimiento en cada uno de sus turnos para entrar en el área o moverse al alcance del objetivo. Cuando la criatura lo haya hecho, no puede alejarse voluntariamente del objetivo. Si el objetivo daña a una criatura afectada, la criatura afectada puede hacer una tirada de salvación de sabiduría para terminar el efecto, como se describe a continuación.<b>Fin del efecto.</b> Si una criatura afectada termina su turno sin estar a menos de 60 pies del objetivo o sin poder verlo, la criatura realiza una tirada de salvación de sabiduría. Con una salvación exitosa, la criatura ya no se ve afectada por el objetivo y reconoce el sentimiento de repugnancia o atracción como mágico. Además, una criatura afectada por el hechizo puede realizar otra tirada de salvación de sabiduría cada 24 horas mientras el hechizo persista.Una criatura que salva con éxito contra este efecto es inmune a él durante 1 minuto, tras el cual puede verse afectada de nuevo.', '10 days', 'no', '1 hora', 'Nivel 8', '60 pies', 'Druida, Mago, Lanzador de Rituales', 'Encantamiento'),
(379, 'Clon (Clone)', 'Este hechizo crea un duplicado inerte de una criatura viva como salvaguarda contra la muerte. Este clon se forma dentro de un recipiente sellado y crece hasta alcanzar su tamaño y madurez al cabo de 120 días; también puedes elegir que el clon sea una versión más joven de la misma criatura. Permanece inerte y perdura indefinidamente, siempre que su recipiente permanezca intacto.En cualquier momento después de que el clon madure, si la criatura original muere, su alma se transfiere al clon, siempre que el alma esté libre y dispuesta a regresar. El clon es físicamente idéntico al original y tiene la misma personalidad, recuerdos y habilidades, pero no posee el equipo del original. Los restos físicos de la criatura original, si aún existen, se vuelven inertes y no pueden volver a la vida, ya que el alma de la criatura está en otra parte.', 'Instantaneo', 'no', '1 hora', 'Nivel 8', 'Toque', 'Mago, Lanzador de Rituales', 'Nigromancia'),
(380, 'Controlar el clima (Control Weather)', 'Controlas el clima en un radio de 8 km mientras dure el hechizo. Debes estar al aire libre para lanzar este hechizo. Si te mudas a un lugar donde no tengas un camino despejado hacia el cielo, el hechizo termina antes de tiempo.Cuando lanzas el hechizo, cambias las condiciones meteorológicas actuales, que son determinadas por el DM basándose en el clima y la estación. Puedes cambiar la precipitación, la temperatura y el viento. Las nuevas condiciones tardan 1d4 x 10 minutos en surtir efecto. Una vez que lo hacen, puedes volver a cambiar las condiciones. Cuando el hechizo termina, el clima vuelve gradualmente a la normalidad.Cuando cambias las condiciones meteorológicas, busca una condición actual en las siguientes tablas y cambia su fase en una, hacia arriba o hacia abajo. Al cambiar el viento, puedes cambiar su dirección.', 'Hasta 8 horas', 'si', '10 minutos', 'Nivel 8', 'Personal', 'Clérigo, Clerigo, Druida, Mago, Lanzador de Rituales', 'Transmutacion');
INSERT INTO `conjuros` (`id_spell`, `name`, `descr`, `duracion`, `concentracion`, `casteo`, `level`, `rango`, `clases`, `escuela`) VALUES
(381, 'Semiplano (Demiplane)', 'Creas una puerta sombría en una superficie plana y sólida que puedas ver dentro de tu alcance. La puerta es lo suficientemente grande como para permitir que criaturas medianas la atraviesen sin obstáculos. Cuando se abre, la puerta conduce a un semiplano que parece ser una habitación vacía de 30 pies en cada dimensión, hecha de madera o piedra. Cuando el hechizo termina, la puerta desaparece, y cualquier criatura u objeto dentro del semiplano permanece atrapado allí, ya que la puerta también desaparece por el otro lado.Cada vez que lances este hechizo, puedes crear un nuevo semiplano, o hacer que la puerta sombría se conecte a un semiplano que hayas creado con un lanzamiento anterior de este hechizo. Además, si conoces la naturaleza y el contenido de un semiplano creado por otra criatura al lanzar este conjuro, puedes hacer que la puerta sombría se conecte a su semiplano.', '1 hora', 'no', '1 acción', 'Nivel 8', '60 pies', 'Mago, Brujo, Lanzador de Rituales', 'Conjuracion'),
(382, 'Dominar monstruo (Dominate Monster)', 'Intentas hechizar a una criatura que veas dentro de tu alcance. Debe tener éxito en una tirada de salvación de sabiduría o quedará hechizada por ti mientras dure el hechizo. Si tú o criaturas amigas tuyas estáis luchando contra ella, tiene ventaja en la tirada de salvación.Mientras la criatura esté encantada, tienes un vínculo telepático con ella mientras estéis en el mismo plano de existencia. Puedes utilizar este vínculo telepático para dar órdenes a la criatura mientras estás consciente (no requiere acción), que hará todo lo posible por obedecer. Puedes especificar un curso de acción simple y general, como \"Ataca a esa criatura\", \"Corre hacia allí\" o \"Busca ese objeto\". Si la criatura cumple la orden y no recibe más indicaciones tuyas, se defiende y se preserva lo mejor que puede.Puedes utilizar tu acción para tomar el control total y preciso del objetivo. Hasta el final de tu siguiente turno, la criatura sólo realiza las acciones que tú elijas y no hace nada que tú no le permitas hacer. Durante este tiempo, también puedes hacer que la criatura utilice una reacción, pero esto requiere que utilices también tu propia reacción.Cada vez que el objetivo recibe daño, realiza una nueva tirada de salvación contra el hechizo. Si la tirada de salvación tiene éxito, el hechizo termina.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 8', '60 pies', 'Bardo, Hechicero, Brujo, Mago', 'Encantamiento'),
(383, 'Terremoto (Earthquake)', 'Creas una perturbación sísmica en un punto del suelo que puedas ver dentro de tu alcance. Mientras dure, un intenso temblor recorre el suelo en un círculo de 30 metros de radio centrado en ese punto y sacude a las criaturas y estructuras en contacto con el suelo en esa zona.El suelo de la zona se convierte en terreno difícil. Cada criatura que se concentre en el suelo debe realizar una tirada de salvación de Constitución. Si falla, la concentración de la criatura se rompe.Cuando lanzas este hechizo y al final de cada turno que pasas concentrado en él, cada criatura en el suelo en el área debe hacer una tirada de salvación de destreza. Si falla la tirada de salvación, la criatura queda tendida.Este hechizo puede tener efectos adicionales dependiendo del terreno de la zona, según determine el DM.Fisuras. Se abren fisuras en toda el área del hechizo al comienzo de tu siguiente turno después de lanzar el hechizo. Un total de 1d6 fisuras se abren en lugares elegidos por el DM. Cada una tiene 1d10 × 10 pies de profundidad, 10 pies de ancho y se extiende desde un borde del área del hechizo hasta el lado opuesto. Una criatura que se encuentre en un lugar donde se abra una fisura debe tener éxito en una tirada de salvación de destreza o caer dentro. Una criatura que salva con éxito se mueve con el borde de la fisura a medida que se abre.Una fisura que se abre bajo una estructura hace que ésta se derrumbe automáticamente (ver más abajo).Estructuras. El temblor inflige 50 puntos de daño contundente a cualquier estructura en contacto con el suelo en el área cuando lanzas el hechizo y al inicio de cada uno de tus turnos hasta que el hechizo finalice. Si una estructura cae a 0 puntos de vida, se derrumba y puede dañar a las criaturas cercanas. Una criatura que se encuentre a menos de la mitad de la altura de la estructura debe realizar una tirada de salvación de destreza. Si falla la tirada de salvación, la criatura recibe 5d6 puntos de daño contundente, queda tendida y enterrada entre los escombros, por lo que debe realizar un chequeo de Fuerza (Atletismo) DC 20 como acción para escapar. El DM puede ajustar la DC más alta o más baja, dependiendo de la naturaleza de los escombros. Si la salvación tiene éxito, la criatura recibe la mitad de daño y no cae boca abajo ni queda enterrada.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 8', '500 pies', 'Clerigo, Druida, Hechicero', 'Evocacion'),
(384, 'Mente vacía (Feeblemind)', 'Haces estallar la mente de una criatura que puedas ver dentro de tu alcance, intentando destrozar su intelecto y personalidad. El objetivo recibe 4d6 puntos de daño psíquico y debe realizar una tirada de salvación de Inteligencia.Si falla la tirada de salvación, las puntuaciones de Inteligencia y Carisma de la criatura se convierten en 1. La criatura no puede lanzar hechizos, activar objetos mágicos, entender el lenguaje ni comunicarse de forma inteligible. Sin embargo, puede identificar a sus amigos, seguirlos e incluso protegerlos.Al final de cada 30 días, la criatura puede repetir su tirada de salvación contra este hechizo. Si tiene éxito en su tirada de salvación, el hechizo termina.El hechizo también puede finalizar mediante una restauración mayor, curación o deseo.', 'Instantaneo', 'no', '1 acción', 'Nivel 8', '150 pies', 'Druida, Mago, Brujo, Lanzador de Rituales', 'Encantamiento'),
(385, 'Elocuencia (Glibness)', 'Hasta que el hechizo termine, cuando hagas un chequeo de Carisma, puedes reemplazar el número que saques con un 15. Además, digas lo que digas, la magia que determinaría si dices la verdad indica que estás siendo sincero.', '1 hora', 'no', '1 acción', 'Nivel 8', 'Personal', 'Bardo, Brujo', 'Transmutacion'),
(386, 'Aura sagrada (Holy Aura)', 'Una luz divina emana de ti y se funde en un suave resplandor en un radio de 30 pies a tu alrededor. Las criaturas de tu elección en ese radio cuando lanzas este conjuro arrojan luz tenue en un radio de 5 pies y tienen ventaja en todas las tiradas de salvación, y otras criaturas tienen desventaja en las tiradas de ataque contra ellas hasta que el conjuro termina. Además, cuando un demonio o un no muerto golpea a una criatura afectada con un ataque cuerpo a cuerpo, el aura destella una luz brillante. El atacante debe tener éxito en una tirada de salvación de Constitución o quedar cegado hasta que finalice el hechizo.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 8', 'Personal', 'Clerigo', 'Abjuracion'),
(387, 'Nube ígnea (Incendiary Cloud)', 'Aparece una nube arremolinada de humo atravesada por ascuas al rojo vivo en una esfera de 6 metros de radio centrada en un punto dentro del alcance. La nube se extiende por las esquinas y queda muy oscurecida. Dura lo que dura o hasta que un viento de velocidad moderada o superior (al menos 10 millas por hora) la dispersa.Cuando aparece la nube, cada criatura que se encuentre en ella debe realizar una tirada de salvación de destreza. Una criatura recibe 10d8 puntos de daño por fuego si falla la tirada de salvación, o la mitad de daño si tiene éxito. Una criatura también debe hacer esta tirada de salvación cuando entra en el área del hechizo por primera vez en un turno o termina su turno allí.La nube se aleja 10 pies directamente de ti en una dirección que eliges al comienzo de cada uno de tus turnos.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 8', '150 pies', 'Hechicero, Mago', 'Conjuracion'),
(388, 'Laberinto (Maze)', 'Destierras a una criatura que puedas ver dentro de tu alcance a un demiplano laberíntico. El objetivo permanece allí mientras dure la acción o hasta que escape del laberinto.El objetivo puede utilizar su acción para intentar escapar. Cuando lo haga, realiza un chequeo de Inteligencia DC 20. Si tiene éxito, escapa. Si lo consigue, escapa y el hechizo termina (un minotauro o demonio goristro lo consigue automáticamente).Cuando el hechizo termina, el objetivo reaparece en el espacio que dejó o, si ese espacio está ocupado, en el espacio desocupado más cercano.', 'Hasta 10 minutos', 'si', '1 acción', 'Nivel 8', '60 pies', 'Mago', 'Conjuracion'),
(389, 'Mente en blanco (Mind Blank)', 'Hasta que el hechizo termine, una criatura que toques es inmune al daño psíquico, a cualquier efecto que pueda sentir sus emociones o leer sus pensamientos, a los hechizos de adivinación y a la condición de encantado. El conjuro también frustra los conjuros de deseo y los conjuros o efectos de poder similar utilizados para afectar a la mente del objetivo o para obtener información sobre él.', '24 horas', 'no', '1 acción', 'Nivel 8', 'Toque', 'Bardo, Mago', 'Abjuracion'),
(390, 'Palabra de poder aturdir (Power Word Stun)', 'Pronuncias una palabra de poder que puede abrumar la mente de una criatura que puedas ver dentro del alcance, dejándola aturdida. Si el objetivo tiene 150 puntos de vida o menos, queda aturdido. De lo contrario, el hechizo no tiene efecto.El objetivo aturdido debe realizar una tirada de salvación de Constitución al final de cada uno de sus turnos. Si la tirada de salvación tiene éxito, el efecto de aturdimiento termina.', 'Instantaneo', 'no', '1 acción', 'Nivel 8', '60 pies', 'Bardo, Hechicero, Brujo, Mago', 'Encantamiento'),
(391, 'Estallido solar (Sunburst)', 'Una luz solar brillante destella en un radio de 60 pies centrado en un punto que elijas dentro del alcance. Cada criatura bajo esa luz debe realizar una tirada de salvación de Constitución. Si falla la tirada de salvación, la criatura recibe 12d6 puntos de daño radiante y queda cegada durante 1 minuto. Con una salvación exitosa, recibe la mitad de daño y no queda cegada por este hechizo. Los muertos vivientes y los excrementos tienen desventaja en esta tirada de salvación.Una criatura cegada por este hechizo realiza otra tirada de salvación de Constitución al final de cada uno de sus turnos. Si tiene éxito, deja de estar ciega.Este hechizo disipa cualquier oscuridad en su área que haya sido creada por un hechizo.', 'Instantaneo', 'no', '1 acción', 'Nivel 8', '150 pies', 'Druida, Hechicero, Mago', 'Evocacion'),
(392, 'Telepatía (Telepathy)', 'Creas un vínculo telepático entre tú y una criatura con la que estés familiarizado. La criatura puede estar en cualquier lugar del mismo plano de existencia que tú. El hechizo termina si tú o el objetivo dejáis de estar en el mismo plano.Hasta que el hechizo termine, tú y el objetivo podéis compartir instantáneamente palabras, imágenes, sonidos y otros mensajes sensoriales a través del vínculo, y el objetivo te reconoce como la criatura con la que se está comunicando. El hechizo permite a una criatura con una puntuación de Inteligencia de al menos 1 comprender el significado de tus palabras y asimilar el alcance de cualquier mensaje sensorial que le envíes.', '24 horas', 'no', '1 acción', 'Nivel 8', 'Unlimited', 'Mago', 'Evocacion'),
(393, 'Atrapando el alma (Trap the Soul)', 'Este nombre de hechizo fue añadido como un error y no existe. Consulta el hechizo llamado \"encarcelamiento\" para obtener información sobre lo que pretendía ser este hechizo.', 'Hasta que se disipe', 'no', '1 minuto', 'Nivel 8', '30 pies', 'Mago', 'Conjuracion'),
(394, 'Tsunami (Tsunami)', 'Surge un muro de agua en el punto que elijas dentro de tu alcance. Puedes crear un muro de hasta 300 pies de largo, 300 pies de alto y 50 pies de grosor. El muro dura lo que dura.Cuando el muro aparece, cada criatura dentro de su área debe hacer una tirada de salvación de fuerza. Si falla la tirada de salvación, la criatura recibe 6 d10 de daño contundente, o la mitad de daño si la tirada de salvación tiene éxito.Al comienzo de cada uno de tus turnos tras la aparición del muro, éste, junto con las criaturas que haya en su interior, se aleja 15 m de ti. Cualquier criatura Huge o más pequeña dentro del muro o en cuyo espacio entre el muro cuando se mueva debe tener éxito en una tirada de salvación de fuerza o recibir 5 d10 de daño contundente. Una criatura sólo puede recibir este daño una vez por asalto. Al final del turno, la altura del muro se reduce en 50 pies, y el daño que las criaturas reciben del hechizo en los siguientes asaltos se reduce en 1d10. Cuando el muro alcanza 0 pies de altura, el hechizo finaliza.Una criatura atrapada en el muro puede moverse nadando. Sin embargo, debido a la fuerza de la ola, la criatura debe realizar con éxito un chequeo de Fuerza (Atletismo) contra su DC de salvación del hechizo para poder moverse. Si falla el chequeo, no puede moverse. Una criatura que se mueve fuera del área cae al suelo.', 'Hasta 6 rounds', 'si', '1 minuto', 'Nivel 8', 'Sight', 'Druida', 'Conjuracion'),
(395, 'Proyección astral (Astral Projection)', 'Tú y hasta ocho criaturas dispuestas dentro del alcance proyectáis vuestros cuerpos astrales al Plano Astral (el hechizo falla y el lanzamiento se desperdicia si ya estás en ese plano). El cuerpo material que dejas atrás está inconsciente y en estado de animación suspendida; no necesita comida ni aire y no envejece.Tu cuerpo astral se asemeja a tu forma mortal en casi todo, replicando tus estadísticas y posesiones del juego. La principal diferencia es la adición de un cordón plateado que se extiende desde entre tus omóplatos y se arrastra detrás de ti, desvaneciéndose hasta volverse invisible al cabo de 1 pie. Esta cuerda es la que te ata a tu cuerpo material. Mientras la cuerda permanezca intacta, podrás volver a casa. Si el cordón se corta -algo que sólo puede ocurrir cuando un efecto lo indica específicamente-, tu alma y tu cuerpo se separan, matándote al instante.Tu forma astral puede viajar libremente por el Plano Astral y atravesar los portales que conducen a cualquier otro plano. Si entras en un nuevo plano o vuelves al plano en el que estabas cuando lanzaste este hechizo, tu cuerpo y posesiones son transportados a lo largo del cordón de plata, permitiéndote volver a entrar en tu cuerpo al entrar en el nuevo plano. Tu forma astral es una encarnación separada. Cualquier daño u otros efectos que se le apliquen no tienen efecto en tu cuerpo físico, ni persisten cuando vuelves a él.El hechizo termina para ti y tus compañeros cuando utilizas tu acción para descartarlo. Cuando el hechizo termina, la criatura afectada vuelve a su cuerpo físico y se despierta.El hechizo también puede terminar antes para ti o uno de tus compañeros. Un hechizo de disipar magia con éxito usado contra un cuerpo astral o físico termina el hechizo para esa criatura. Si el cuerpo original de una criatura o su forma astral cae a 0 puntos de golpe, el hechizo termina para esa criatura. Si el hechizo termina y el cordón de plata está intacto, el cordón tira de la forma astral de la criatura de vuelta a su cuerpo, poniendo fin a su estado de animación suspendida.Si eres devuelto a tu cuerpo prematuramente, tus compañeros permanecen en sus formas astrales y deben encontrar su propio camino de vuelta a sus cuerpos, normalmente bajando a 0 puntos de golpe.', 'Special', 'no', '1 hora', 'Nivel 9', '10 pies', 'Clérigo, Clerigo, Mago, Brujo, Lanzador de Rituales', 'Nigromancia'),
(396, 'Previsión (Foresight)', 'Tocas a una criatura dispuesta y le otorgas una habilidad limitada para ver el futuro inmediato. Mientras dure, el objetivo no puede ser sorprendido y tiene ventaja en tiradas de ataque, chequeos de habilidad y tiradas de salvación. Además, otras criaturas tienen desventaja en las tiradas de ataque contra el objetivo mientras dure el hechizo.Este hechizo termina inmediatamente si vuelves a lanzarlo antes de que termine su duración.', '8 horas', 'no', '1 minuto', 'Nivel 9', 'Toque', 'Bardo, Druida, Brujo, Mago', 'Adivinacion'),
(397, 'Portal (Gate)', 'Conjuras un portal que une un espacio desocupado que puedes ver dentro de tu alcance con una ubicación precisa en un plano de existencia diferente. El portal es una abertura circular, que puedes hacer de 5 a 20 pies de diámetro. Puedes orientar el portal en cualquier dirección que elijas. El portal dura lo que dura.El portal tiene un anverso y un reverso en cada plano en el que aparece. Sólo es posible viajar a través del portal moviéndose por su parte delantera. Cualquier cosa que lo haga es transportada instantáneamente al otro plano, apareciendo en el espacio desocupado más cercano al portal.Las deidades y otros gobernantes planares pueden impedir que los portales creados por este hechizo se abran en su presencia o en cualquier lugar dentro de sus dominios.Cuando lanzas este hechizo, puedes pronunciar el nombre de una criatura específica (un seudónimo, título o apodo no sirve). Si esa criatura se encuentra en un plano distinto al tuyo, el portal se abre en las inmediaciones de la criatura nombrada y la atrae a través de él hasta el espacio desocupado más cercano a tu lado del portal. No obtienes ningún poder especial sobre la criatura, y ésta es libre de actuar como el DM considere apropiado. Puede marcharse, atacarte o ayudarte.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 9', '60 pies', 'Clerigo, Hechicero, Mago', 'Conjuracion'),
(398, 'Prisión (Imprisonment)', 'Creas una restricción mágica para retener a una criatura que puedas ver dentro de tu alcance. El objetivo debe tener éxito en una tirada de salvación de sabiduría o quedar atado por el hechizo; si tiene éxito, es inmune a este hechizo si vuelves a lanzarlo. Mientras esté afectada por este conjuro, la criatura no necesita respirar, comer ni beber, y no envejece. Los hechizos de adivinación no pueden localizar ni percibir al objetivo.Cuando lanzas el hechizo, eliges una de las siguientes formas de aprisionamiento.Entierro. El objetivo queda sepultado muy por debajo de la tierra en una esfera de fuerza mágica lo suficientemente grande como para contenerlo. Nada puede atravesar la esfera, ni ninguna criatura puede teletransportarse o utilizar el viaje planar para entrar o salir de ella.El componente especial de esta versión del hechizo es un pequeño orbe de mithral.Encadenamiento. Unas pesadas cadenas, firmemente arraigadas en el suelo, sujetan al objetivo. El objetivo queda inmovilizado hasta que finaliza el hechizo, y no puede moverse ni ser movido por ningún medio hasta entonces.El componente especial de esta versión del hechizo es una fina cadena de metal precioso.Prisión cubierta. El hechizo transporta al objetivo a un pequeño semiplano protegido contra el teletransporte y los viajes planares. El semiplano puede ser un laberinto, una jaula, una torre o cualquier estructura o área confinada similar de tu elección.El componente especial para esta versión del hechizo es una representación en miniatura de la prisión hecha de jade.Contención mínima. El objetivo se encoge a una altura de 1 pulgada y queda aprisionado dentro de una piedra preciosa u objeto similar. La luz puede atravesar la gema normalmente (permitiendo al objetivo ver hacia fuera y a otras criaturas ver hacia dentro), pero nada más puede atravesarla, ni siquiera mediante teletransporte o viaje planar. La gema no puede cortarse ni romperse mientras el hechizo siga vigente.El componente especial para esta versión del hechizo es una piedra preciosa grande y transparente, como un corindón, un diamante o un rubí.Adormecimiento. El objetivo se duerme y no puede ser despertado.El componente especial para esta versión del hechizo consiste en hierbas soporíferas raras.Finalización del hechizo. Durante el lanzamiento del hechizo, en cualquiera de sus versiones, puedes especificar una condición que hará que el hechizo termine y libere al objetivo. La condición puede ser tan específica o tan elaborada como elijas, pero el DM debe estar de acuerdo en que la condición es razonable y tiene una probabilidad de suceder. Las condiciones pueden basarse en el nombre, la identidad o la deidad de una criatura, pero por lo demás deben basarse en acciones o cualidades observables y no en intangibles como el nivel, la clase o los puntos de golpe.Un conjuro de disipar magia puede acabar con el conjuro sólo si se lanza como un conjuro de 9º nivel, apuntando a la prisión o al componente especial utilizado para crearla.Puedes utilizar un componente especial concreto para crear sólo una prisión a la vez. Si vuelves a lanzar el hechizo utilizando el mismo componente, el objetivo de la primera vez se libera inmediatamente de su atadura.', 'Hasta que se disipe', 'no', '1 minuto', 'Nivel 9', '30 pies', 'Brujo, Mago', 'Abjuracion'),
(399, 'Curar en masa (Mass Heal)', 'Un torrente de energía curativa fluye desde ti hacia las criaturas heridas que te rodean. Restauras hasta 700 puntos de golpe, divididos a tu elección entre cualquier número de criaturas que puedas ver dentro de tu alcance. Las criaturas curadas por este hechizo también se curan de todas las enfermedades y de cualquier efecto que las deje ciegas o sordas. Este hechizo no tiene efecto sobre muertos vivientes o constructos.', 'Instantaneo', 'no', '1 acción', 'Nivel 9', '60 pies', 'Clerigo', 'Conjuracion'),
(400, 'Lluvia de meteoritos (Meteor Swarm)', 'Ardientes orbes de fuego caen en picado al suelo en cuatro puntos diferentes que puedes ver dentro del alcance. Cada criatura en una esfera de 40 pies de radio centrada en cada punto que elijas debe hacer una tirada de salvación de destreza. La esfera se extiende por las esquinas. Una criatura recibe 20d6 puntos de daño de fuego y 20d6 puntos de daño contundente si falla la tirada de salvación, o la mitad de daño si tiene éxito. Una criatura en el área de más de una explosión de fuego sólo se ve afectada una vez.El hechizo daña los objetos de la zona y enciende los objetos inflamables que no se lleven puestos.', 'Instantaneo', 'no', '1 acción', 'Nivel 9', '1 mile', 'Hechicero, Mago', 'Evocacion'),
(401, 'Palabra de poder sanar (Power Word Heal)', 'Una oleada de energía curativa inunda a la criatura que tocas. El objetivo recupera todos sus puntos de golpe. Si la criatura está encantada, asustada, paralizada o aturdida, la condición termina. Si la criatura está tendida, puede usar su reacción para levantarse. Este hechizo no tiene efecto sobre muertos vivientes o constructos.', 'Instantaneo', 'no', '1 acción', 'Nivel 9', 'Toque', 'Bard', 'Evocacion'),
(402, 'Palabra de poder matar (Power Word Kill)', 'Pronuncias una palabra de poder que puede obligar a una criatura que puedas ver dentro del alcance a morir instantáneamente. Si la criatura que eliges tiene 100 puntos de vida o menos, muere. De lo contrario, el hechizo no tiene efecto.', 'Instantaneo', 'no', '1 acción', 'Nivel 9', '60 pies', 'Bardo, Hechicero, Brujo, Mago', 'Encantamiento'),
(403, 'Muro prismático (Prismatic Wall)', 'Un plano de luz brillante y multicolor forma un muro vertical opaco de hasta 90 pies de largo, 30 pies de alto y 1 pulgada de grosor, centrado en un punto que puedas ver dentro del alcance. Alternativamente, puedes formar el muro en una esfera de hasta 30 pies de diámetro centrada en un punto que elijas dentro del alcance. El muro permanece en su sitio mientras dure la acción. Si colocas el muro de forma que atraviese un espacio ocupado por una criatura, el hechizo falla y tu acción y la ranura del hechizo se desperdician.El muro emite luz brillante hasta un alcance de 100 pies y luz tenue durante 100 pies adicionales. Tú y las criaturas que designes en el momento de lanzar el hechizo podéis atravesar y permanecer cerca del muro sin sufrir daño. Si otra criatura que pueda ver el muro se mueve a menos de 20 pies de él o comienza su turno allí, la criatura debe tener éxito en una tirada de salvación de Constitución o queda cegada durante 1 minuto.El muro consta de siete capas, cada una de un color diferente. Cuando una criatura intenta alcanzar o atravesar el muro, lo hace capa por capa a través de todas las capas del muro. Al atravesar cada capa, la criatura debe realizar una tirada de salvación de destreza o se verá afectada por las propiedades de esa capa, tal y como se describe a continuación.El muro puede ser destruido, también capa por capa, en orden de rojo a violeta, por medios específicos para cada capa. Una vez destruida una capa, permanece así mientras dure el hechizo. Una vara de anulación destruye un muro prismático, pero un campo antimágico no tiene ningún efecto sobre él.<b>1. Rojo.</b> La criatura recibe 10d6 puntos de daño por fuego si falla la salvación, o la mitad de daño si tiene éxito. Mientras esta capa esté en su lugar, los ataques a distancia no mágicos no pueden atravesar el muro. La capa puede destruirse infligiéndole al menos 25 de daño de frío.<b>2. Naranja.</b> La criatura recibe 10d6 de daño ácido si falla la salvación, o la mitad de daño si tiene éxito. Mientras esta capa esté en su lugar, los ataques mágicos a distancia no pueden atravesar el muro. La capa se destruye con un viento fuerte.<b>3. Amarillo.</b> La criatura recibe 10d6 de daño por rayo si falla la salvación, o la mitad de daño si tiene éxito. Esta capa puede destruirse infligiéndole al menos 60 de daño de fuerza.<b>4. Verde.</b> La criatura recibe 10d6 puntos de daño de veneno si falla la salvación, o la mitad de daño si tiene éxito. Un hechizo de cortafuegos, u otro hechizo de igual o mayor nivel que pueda abrir un portal en una superficie sólida, destruye esta capa.<b>5. Azul.</b> La criatura sufre 10d6 de daño por frío si falla la salvación, o la mitad de daño si tiene éxito. Esta capa puede destruirse infligiéndole al menos 25 de daño de fuego.<b>6. Índigo.</b> Si falla la salvación, la criatura queda inmovilizada. Debe realizar una tirada de salvación de constitución al final de cada uno de sus turnos. Si salva tres veces, el hechizo termina. Si falla la salvación tres veces, se convierte permanentemente en piedra y sufre la condición de petrificado. No es necesario que los éxitos y los fracasos sean consecutivos; lleva la cuenta de ambos hasta que la criatura consiga tres iguales.Mientras esta capa esté en su lugar, no se pueden lanzar hechizos a través de la pared. La capa se destruye con la luz brillante derramada por un hechizo de luz diurna o un hechizo similar de nivel igual o superior.<b>7. Violeta.</b> Si falla la salvación, la criatura queda cegada. Debe realizar una tirada de salvación de sabiduría al comienzo de tu siguiente turno. Una salvación con éxito acaba con la ceguera. Si falla la tirada de salvación, la criatura es transportada a otro plano a elección del DM y deja de estar ciega. (Típicamente, una criatura que está en un plano que no es su plano natal es desterrada a casa, mientras que otras criaturas son normalmente lanzadas a los planos Astral o Etéreo). Esta capa es destruida por un hechizo de disipar magia o un hechizo similar de igual o mayor nivel que pueda acabar con hechizos y efectos mágicos.', '10 minutos', 'no', '1 acción', 'Nivel 9', '60 pies', 'Mago', 'Abjuracion'),
(404, 'Cambio de forma (Shapechange)', 'Adoptas la forma de una criatura diferente mientras dure el efecto. La nueva forma puede ser de cualquier criatura con un índice de desafío igual o inferior a tu nivel. La criatura no puede ser un constructo ni un no muerto, y debes haber visto ese tipo de criatura al menos una vez. Te transformas en un ejemplar medio de esa criatura, uno sin niveles de clase ni el rasgo Hechicería.Tus estadísticas de juego son reemplazadas por las de la criatura elegida, aunque conservas tu alineamiento y tus puntuaciones de Inteligencia, Sabiduría y Carisma. También conservas todas tus habilidades y tiradas de salvación, además de las de la criatura. Si la criatura tiene la misma competencia que tú y el bonificador que aparece en sus estadísticas es mayor que el tuyo, utiliza el bonificador de la criatura en lugar del tuyo. No puedes utilizar ninguna acción legendaria o de guarida de la nueva forma.Asumes los puntos de golpe y los Dados de Golpe de la nueva forma. Cuando vuelves a tu forma normal, recuperas el número de puntos de golpe que tenías antes de transformarte. Si vuelves a tu forma normal como resultado de una caída a 0 puntos de golpe, cualquier exceso de daño se traslada a tu forma normal. Mientras el exceso de daño no reduzca tu forma normal a 0 puntos de vida, no quedas inconsciente.Conservas los beneficios de cualquier característica de tu clase, raza u otra fuente y puedes utilizarlos, siempre que tu nueva forma sea físicamente capaz de hacerlo. No puedes utilizar ningún sentido especial que tengas (por ejemplo, visión oscura) a menos que tu nueva forma también tenga ese sentido. Sólo puedes hablar si la criatura puede hablar normalmente.Cuando te transformas, puedes elegir si tu equipo cae al suelo, se funde con tu nueva forma o lo lleva puesto. El equipo que lleva puesto funciona normalmente. El DM determina si es práctico para la nueva forma llevar una pieza de equipo, basándose en la forma y tamaño de la criatura. Tu equipo no cambia de forma o tamaño para adaptarse a la nueva forma, y cualquier equipo que la nueva forma no pueda llevar debe caer al suelo o fusionarse con tu nueva forma. El equipo que se fusiona no tiene ningún efecto en ese estado.Durante la duración de este hechizo, puedes usar tu acción para asumir una forma diferente siguiendo las mismas restricciones y reglas para la forma original, con una excepción: si tu nueva forma tiene más puntos de golpe que la actual, tus puntos de golpe permanecen en su valor actual.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 9', 'Personal', 'Druida, Mago', 'Transmutacion'),
(405, 'Tormenta de venganza (Storm of Vengeance)', 'Se forma una agitada nube de tormenta, centrada en un punto que puedes ver y que se extiende en un radio de 360 pies. Los relámpagos relampaguean en la zona, los truenos retumban y los fuertes vientos rugen. Cada criatura que se encuentre bajo la nube (a no más de 5.000 pies por debajo de la nube) cuando ésta aparece debe realizar una tirada de salvación de Constitución. Si falla la tirada de salvación, la criatura recibe 2d6 puntos de daño por trueno y queda ensordecida durante 5 minutos.Cada asalto que mantengas la concentración en este hechizo, la tormenta produce efectos adicionales en tu turno. <b>Segundo asalto.</b> Cae lluvia ácida de la nube. Cada criatura y objeto bajo la nube recibe 1d6 puntos de daño por ácido.<b>Tercer asalto.</b> Llamas a seis rayos de la nube para que golpeen a seis criaturas u objetos de tu elección bajo la nube. Una criatura u objeto no puede ser alcanzado por más de un rayo. La criatura alcanzada debe realizar una tirada de salvación de destreza. La criatura recibe 10d6 de daño por rayo si falla la tirada de salvación, o la mitad de daño si tiene éxito.<b>4º asalto.</b> De la nube llueven piedras de granizo. Cada criatura bajo la nube recibe 2d6 puntos de daño contundente.<b>Asalto 5-10.</b> Ráfagas de viento y lluvia helada asaltan la zona bajo la nube. La zona se convierte en terreno difícil y queda muy oscurecida. Cada criatura sufre 1d6 puntos de daño por frío. Los ataques con armas a distancia en la zona son imposibles. El viento y la lluvia cuentan como distracción grave a efectos de mantener la concentración en los conjuros. Por último, las ráfagas de viento fuerte (de 20 a 50 millas por hora) dispersan automáticamente la niebla, las brumas y fenómenos similares en la zona, ya sean mundanos o mágicos.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 9', 'Sight', 'Druida', 'Conjuracion'),
(406, 'Parar el tiempo (Time Stop)', 'Detienes brevemente el flujo del tiempo para todos menos para ti. El tiempo no pasa para las demás criaturas, mientras tú realizas 1d4 + 1 turnos seguidos, durante los cuales puedes utilizar acciones y moverte normalmente.Este conjuro finaliza si una de las acciones que utilizas durante este periodo, o cualquier efecto que crees durante el mismo, afecta a una criatura que no seas tú o a un objeto que lleve puesto o porte alguien que no seas tú. Además, el hechizo termina si te mueves a un lugar situado a más de 1.000 pies del lugar donde lo lanzaste.', 'Instantaneo', 'no', '1 acción', 'Nivel 9', 'Personal', 'Hechicero, Mago', 'Transmutacion'),
(407, 'Polimorfia verdadera (True Polymorph)', 'Elige una criatura u objeto no mágico que puedas ver dentro de tu alcance. Transformas a la criatura en otra criatura, a la criatura en un objeto o al objeto en una criatura (el objeto no debe ser llevado ni portado por otra criatura). La transformación dura lo que dure, o hasta que el objetivo quede con 0 puntos de vida o muera. Si te concentras en este hechizo durante toda su duración, la transformación se convierte en permanente.Los cambiaformas no se ven afectados por este hechizo. Una criatura no dispuesta puede hacer una tirada de salvación de sabiduría, y si tiene éxito, no se ve afectada por este hechizo.<b>Criatura en criatura.</b> Si conviertes una criatura en otro tipo de criatura, la nueva forma puede ser cualquier tipo que elijas cuyo índice de desafío sea igual o menor que el del objetivo (o su nivel, si el objetivo no tiene índice de desafío). Las estadísticas de juego del objetivo, incluyendo las puntuaciones de habilidad mental, son reemplazadas por las estadísticas de la nueva forma. Conserva su alineamiento y personalidad.El objetivo asume los puntos de vida de su nueva forma, y cuando vuelve a su forma normal, la criatura recupera el número de puntos de vida que tenía antes de transformarse. Si revierte como resultado de una caída a 0 puntos de golpe, cualquier exceso de daño se traslada a su forma normal. Mientras el exceso de daño no reduzca la forma normal de la criatura a 0 puntos de vida, no queda inconsciente.La criatura está limitada en las acciones que puede realizar por la naturaleza de su nueva forma, y no puede hablar, lanzar hechizos o realizar cualquier otra acción que requiera las manos o el habla a menos que su nueva forma sea capaz de tales acciones.El equipo del objetivo se funde con la nueva forma. La criatura no puede activar, utilizar, blandir ni beneficiarse de ninguna otra forma de su equipo.<b>Objeto en criatura.</b> Puedes convertir un objeto en cualquier tipo de criatura, siempre que el tamaño de la criatura no sea mayor que el tamaño del objeto y el índice de desafío de la criatura sea 9 o inferior. La criatura es amistosa contigo y tus compañeros. Actúa en cada uno de tus turnos. Tú decides qué acción realiza y cómo se mueve. El DM tiene las estadísticas de la criatura y resuelve todas sus acciones y movimientos.Si el hechizo se convierte en permanente, dejas de controlar a la criatura. Puede que siga siendo amistosa contigo, dependiendo de cómo la hayas tratado.<b>Criatura convertida en objeto.</b> Si conviertes a una criatura en un objeto, se transforma junto con cualquier cosa que lleve puesta en esa forma. Las estadísticas de la criatura se convierten en las del objeto, y la criatura no tiene memoria del tiempo pasado en esta forma, después de que el hechizo termine y vuelva a su forma normal.', 'Hasta 1 hora', 'si', '1 acción', 'Nivel 9', '30 pies', 'Bardo, Brujo, Mago', 'Transmutacion'),
(408, 'Resurrección verdadera (True Resurrection)', 'Tocas a una criatura que lleve muerta no más de 200 años y que haya muerto por cualquier motivo excepto por vejez. Si el alma de la criatura está libre y dispuesta, la criatura vuelve a la vida con todos sus puntos de golpe.Este hechizo cierra todas las heridas, neutraliza cualquier veneno, cura todas las enfermedades y levanta cualquier maldición que afectara a la criatura cuando murió. El hechizo reemplaza los órganos y miembros dañados o perdidos.El hechizo puede incluso proporcionar un nuevo cuerpo si el original ya no existe, en cuyo caso debes pronunciar el nombre de la criatura. La criatura aparece entonces en un espacio desocupado que elijas en un radio de 3 metros de ti.', 'Instantaneo', 'no', '1 hora', 'Nivel 9', 'Toque', 'Clerigo, Druida', 'Nigromancia'),
(409, 'Extraño (Weird)', 'Inspirándote en los miedos más profundos de un grupo de criaturas, creas criaturas ilusorias en sus mentes, visibles sólo para ellas. Cada criatura en una esfera de 30 pies de radio centrada en un punto de tu elección dentro del alcance debe hacer una tirada de salvación de sabiduría. Si falla la tirada de salvación, la criatura queda asustada mientras dure el efecto. La ilusión invoca los miedos más profundos de la criatura, manifestando sus peores pesadillas como una amenaza implacable. Al comienzo de cada turno de la criatura asustada, debe tener éxito en una tirada de salvación de sabiduría o sufrir 4 d10 de daño psíquico. Si la tirada de salvación tiene éxito, el hechizo termina para esa criatura.', 'Hasta 1 minuto', 'si', '1 acción', 'Nivel 9', '120 pies', 'Mago, Lanzador de Rituales', 'Ilusion'),
(410, 'Deseo (Wish)', 'El deseo es el hechizo más poderoso que puede lanzar una criatura mortal. Simplemente hablando en voz alta, puede alterar los fundamentos mismos de la realidad a su antojo.El uso más básico de este hechizo es duplicar cualquier otro de 8º nivel o inferior. Para ello, sólo tienes que cumplir unas condiciones, sin necesidad de componentes costosos. El destino simplemente surte efecto. También puedes crear uno de los siguientes efectos a tu elección:- Creas un objeto de hasta 25.000 gp de valor que no sea un objeto mágico. El objeto no puede medir más de 300 pies en cualquier dimensión, y aparece en un espacio desocupado que puedas ver en el suelo.- Concedes a un máximo de veinte criaturas que puedas ver todos sus puntos y disipas todos los efectos que les afecten, como se describe en conjuro mayor de restauración.- Concedes a un máximo de diez criaturas que puedas ver resistencia a un tipo de daño que elijas.- Concedes a un máximo de diez criaturas que puedas ver inmunidad a un único conjuro u otro efecto mágico durante 8 horas. Por ejemplo, puedes inmunizarte a ti y a tus compañeros contra el ataque del Lich drenador.- Usted cancelar un evento reciente único por el que se requiere un nuevo chorro de reemplazo diced cualquier chorro realizado durante la última ronda (incluyendo su último turno). La realidad se transforma para que coincida con el nuevo lanzamiento. Por ejemplo, un hechizo de deseo puede cancelar una exitosa tirada de salvación enemigo golpe crítico a un oponente o aliado tirada de salvación fallado. Usted puede imponer un chorro con ventaja o desventaja, y usted puede elegir utilizar el nuevo resultado de la puesta en marcha o el viejo.También puedes hacer otras cosas además de los ejemplos anteriores. Describe tus deseos a tu DM de la forma más precisa posible. El DM es libre de determinar lo que ocurre en este caso; cuanto más deseo, más probable es que algo salga mal. Este hechizo podría simplemente fallar, el efecto que deseas podría ejecutarse sólo parcialmente, o podrías sufrir consecuencias impredecibles dependiendo de tu deseo de formulación. Por ejemplo, desear la muerte de un enemigo podría propulsarte a un tiempo futuro en el que tu enemigo ya no está vivo, eliminando efectivamente el juego. Del mismo modo, desear un objeto mágico legendario o artefacto podría llevarte instantáneamente en presencia del actual propietario del objeto.La tensión de lanzar este hechizo para producir un efecto que no sea la reproducción de otro hechizo te debilita. Después de sufrir esta tensión cada vez que lances un conjuro, y esto hasta tu próximo descanso prolongado, sufres 1d10 puntos de daño necrótico por nivel de conjuro. Este daño no puede reducirse ni evitarse de ningún modo. Además, tu Fuerza baja a 3, si no es ya inferior a 3, durante 2d4 días. Por cada día que pases descansando o practicando una actividad menor, tu tiempo de recuperación disminuye en 2 días. Por último, tienes un 33% de probabilidades de no poder lanzar nunca el hechizo si tu deseo sufre estrés.', 'Instantaneo', 'no', '1 acción', 'Nivel 9', 'Personal', 'Hechicero, Mago', 'Conjuracion');
